window.__D("text/torat-shmuel/c033",{"p":[[2000460283,"דהנה כתיב שמש ומגן הוי' אלקים, כמו שהמגן הוא מכסה ומסתיר על אור השמש שלא יאיר כמו שהוא בהשמש, כמו\"כ ש' אלקים הוא מגן ונרתק שלא יאיר אור הוי' וקדושתו כמו שהוא שם רק דרך הנרתק. והנה בשם אלקים יש ק\"ך צירופי' אלקים וע\"י ריבוי השתל' נעשה אלקים אחרים שהוא העלם והסתר גמור (הג\"ה. ע' במצות מילה פ\"ד שיש כמה מסכים<sup data-n=\"852\">9</sup> ופרסאות ופרוכת וע\"י כולם מאיר האור, ויש פרסה שהוא מסתיר ומעלים לגמרי יעו\"ש עכ\"ה) וע\"י ביטול היש לאין מהפכין זה. והנה אמרז\"ל גמירי משמיא מיהב יהבי מישקל לא שקלי, מיהב יהבי היינו סדר השתל' אבל משקל לא שקלי היינו ביטול היש הוא דבר חדש למעלה ועי\"ז נעשה הצחוק, דעיקר תענוג הוא מדבר חדש דוקא, שאפי' בדבר שיש בו תענוג אם רואה אותו בכ\"י אינו מקבל תענוג מזה כלל, אבל כשרואה דבר חדש מקבל תענוג מזה, וכמו\"כ בהשכלה הנה אמרז\"ל ר' אבוהו מצא תוס' חדתא צהבו פניו מצד התענוג שקיבל מהתוס' חדתא, וכן אנו רואין בכל דבר חדש שיש בו תענוג כמו קניגא שעושין לפני מלכים שהוא דבר חדש, וזהו לויתן זה יצרת לשחק בו, דלויתן הוא ל' הפעם ילוה אישי, אשה הוא כנס\"י אשה יראת ה' היא תתהלל, ואיש הוא הקב\"ה כמ\"ש ה' איש מלחמה וכתי' ביום ההוא תקראי אישי, לויתן הוא חיבור איש ואשה דע\"י הביטול היש שמלמטה למעלה נמשך עונג מלמעלמ\"ט. וזהו ג' שעות הראשונות הקב\"ה יושב וזן כו' הוא מלמעלה למטה, רביעיות יושב ומשחק עם לויתן שע\"י הביטול היש שמלמטלמ\"ע נמשך העונג מלמעלה למטה.\n<b>הגה.</b> אפ\"ל למה דוקא ע\"י ביטול היש<sup data-n=\"853\">10</sup> של מנחה נמשך העונג<sup data-n=\"854\">11</sup>, והרי גם בתפלת שחרית יש ג\"כ ביטול היש דעיקר העבודה הוא שיהי' ביטול היש שהוא יחו\"ת ואח\"כ ממילא בא לביטול דיחו\"ע. והענין דהנה אי' בתוס' הובא בפרישה באו\"ח סי' רל\"ב ובמג\"א שם הטעם למה נק' תפילה זו בשם מנחה ע\"ש הקרבת המנחה, מפני שאז הוא עת רצון שכן אליהו נענה בעת שהקריב מנחה, ואפ\"ל שעת הרצון היינו שאז נמשך העונג מלמעלמ\"ט. וצ\"ל והלא בשחר ג\"כ הי' הקרבת המנחה<sup data-n=\"855\">12</sup>, וצ\"ל כמ\"ש בטור בסי' הנ\"ל שצריכים ליזהר בתפלת המנחה יותר משאר",[["852","9","<b>ע' במצות מילה פ\"ד שיש כמה מסכים</b>: דרמ\"צ ו, ב ואילך."],["853","10","<b>הג\"ה. אפ\"ל למה דוקא ע\"י ביטול היש</b>: בגוכי\"ק לא נסמן היכן סיום ההג\"ה. מכאן ועד סיום המאמר הוא ענין נוסף אשר ליתא במאמר זה לעיל בהספר."],["854","11","<b>אפ\"ל למה דוקא ע\"י ביטול היש של מנחה נמשך העונג</b>: ראה בכ\"ז גם ד\"ה ויהי בעלות המנחה באוה\"ת נ\"ך ע' עא ואילך. ד\"ה ויקח מן הבא בידו מנחה באוה\"ת וישלח רלז, ב ואילך. סה\"מ תרכ\"ז ע' נב (וע\"ש בהמ\"מ בתחילת המאמר). סה\"מ תרל\"ה ח\"א ע' ד ואילך וע' טו ואילך. ד\"ה לעולם יה\"א זהיר בתפילת המנחה, בסה\"מ עזר\"ת ע' פב ואילך. ועוד."],["855","12","<b>דהנה אי' בתוס'. . וצ\"ל והלא בשחר ג\"כ הי' הקרבת המנחה</b>: בתוס' פסחים קז, א ז\"ל: תימא אמאי קרי לי' מנחה דאי משום דמנחה היתה קריבה בין הערבים הלא גם בשחר קריבה מנחת חביתין ומנחת תמיד וי\"ל כו' ועוד דאמרינן בפ\"ק דברכות הוי זהיר בתפלת מנחה שאף אליהו לא נענה אלא בתפלת מנחה ושמא בשעת הקרבת מנחה נענה ולכך קרי לי' תפלת מנחה שאז הי' שעת רצון. ע\"כ."]]],[2000460284,"התפלות מפני שבתפלת שחרית הוא תיכף שהתחיל היום וא\"כ לא ישכח, ותפלת ערבית הוא כשבא לביתו והוא פנוי מעסקיו וג\"כ לא ישכח, אבל תפלת מנחה הוא באמצע היום והוא טרוד בעסקיו לכן צריכים ליזהר שלא ישכח ע\"ש. לכן נק' תפלה זו בשם מנחה ולא תפלת שחרית, מפני שהוא זמן שטרוד בעסקיו מ\"מ עומד ומתפלל הרי המס\"נ גדול וו ס ער רייסט זיך פ פון דיא עסקים לכן הוא עת רצון לכן נק' תפילה זו דוקא בשם תפלת מנחה. וכמו\"כ י\"ל כאן מפני שהוא טרוד בעסקיו בעניני עוה\"ז שנוגע לחיי נפשו מ\"מ עומד ומתפלל בביטול היש איז ד ך דער פ רייס זייער שט„רק, וגם מפני שטרוד בעניני עוה\"ז וניתק מזה און רייסט זיך פ דער פון ועומד ומתפלל אז הביטול היש גדול יותר [ואפ\"ל שעי\"ז בא גם לבחי' יחו\"ע אך תחילה צ\"ל ביטול היש יחו\"ת כידוע].\n<b>וזהו</b> מים רבים לא יוכלו לכבות<sup data-n=\"856\">13</sup> את האהבה, מים רבים היינו טרדת הפרנסה והמחשבות שבעניני עוה\"ז איך להחיות נפשו, דבנפשו יביא לחמו, וכמ\"ש בזיעת אפיך תאכל לחם, שצריך לייגע ע\"ז הרבה מאד, הגם דכתיב וברכך הוי' אלקיך פי' כשתזכור שה' אלקיך<sup data-n=\"857\">14</sup> פי' שהוא הנותן לך כח לעשות חיל ולא תאמר כוחי ועוצם ידי עשה לי החיל הזה, אז וברכך בכל אשר תעשה, ענין אומרו בכל פירושו כל מה שיעשה יעלה לטוב ולהצלחה, ויכולה שתהי' הצלחה יתירה גם בדבר קטן שיתעשר מזה בעושר רב ועצום, אך מ\"מ צריכים כלי במה שתשרה הברכה. והגם שהקב\"ה הוא המסבב כל הסיבות, אך מ\"מ לא כל אדם זוכה שיזמין לו הקב\"ה הכלי בנקל, ועינינו רואות שיש בנ\"א שמייגעים הרבה למצוא כלי במה שתשרה הברכה. ואף כשיש לו כלי מ\"מ צריך לעסוק בזה שירויח, אך מה שמרויח הוא ברכת הקב\"ה שאם לא ירצה הקב\"ה ח\"ו גם אם ייגע בכל כחו לא ירויח כלל, אבל ברצות הקב\"ה יצליח לו גם בעשיות דבר קטן ואינו צריך לעסוק בו הרבה דלכל אשר יפנה יצליח אבל מעט עכ\"פ צריך לעסוק בו. שאם נאמר שאין צריך לעסוק כלל א\"כ בטל הקללה שקילל לאדם הראשון מחמת חטא עה\"ד בזיעת אפיך תאכל לחם, שהרי עדיין לא נגמרו הבירורים, דלע\"ל כשיוגמרו הבירורים לא יהי' עבודת אדמה בגשמיות (שגם אז יהי' עבודה כמ\"ש ושם נעשה לפניך כמצות רצונך ה\"ז עבודה אך לא יהי' בגשמיות), אבל עכשיו שעדיין לא נגמרו הבירורים צ\"ל עבודה בגשמיות בזיעת כו'. ומאחר שצריך לעסוק א\"כ הוא טירדה היפך המנוחה, דמנוחה היינו שאין לו עסק כלל, אבל מאחר שיש לו עסק בו הוא טרדה.\n<b>ועכ\"ז</b> לא יוכלו לכבות את האהבה שהוא בחי' אהבה המוסתרת שיש בכל נפש מישראל בטבע מבחי' נה\"א שטבעה לעלות וליכלל תמיד למעלה כשלהבת",[["856","13","<b>וזהו מים רבים לא יוכלו לכבות</b>: ראה גם תו\"א נח ח, ג ואילך. תו\"ח נח נח, ד ואילך. שער האמונה בהקדמה. דרך חיים בהקדמה. שערי תשובה טו, א. סה\"מ תרל\"ב ח\"א ע' קפ. המשך מים רבים תרל\"ו בתחילתו. ובכ\"מ."],["857","14","<b>דכתיב וברכך ה' אלקיך</b>: ראה גם סה\"מ תקס\"ה ח\"ב ע' תרנו. תקס\"ח ח\"א ע' קסה. דרמ\"צ קו, א. ובמה שצויין בהערה הקודמת. ובכ\"מ."]]],[2000460285,"העולה מאלי', שהרי ידוע שהמדות מתחלקים לג' חלקים מוטבע מורגש מושכל<sup data-n=\"858\">15</sup> שהן חב\"ד חג\"ת נה\"י וכמ\"ש בפרד\"ס שער הנתיבות בענין ל\"ב נת\"ח, נתיב כ\"ז נק' שכל מורגש נתיב כ\"ח נק' שכל מוטבע. והנה יובן באדם התחתון כ\"ז, כי הטבעת המדות בתינוק הנולד מבטן אם, רחמן או אכזרי, כ\"ז נק' מוטבע שהמדות מוטבעים אצלו כך מבטן אמו, והרגשתם בלב בפ\"מ שהרי אנו רואין בתינוק בן יומו כל אופני מזוג מדותיו אם רך הלבב או אכזרי וכן בפיזור וקמצנות התנשאות ושפלות כו' בלתי שינוי במזגו גם כשיזקין ויגדל בכל הפרטים, אך יהי' שינוי בהנהגת המדות המוטבעות לכשיגדיל ויזקין שיוכל לשלוט במוחו על הטבעת לבו ויעשה חסד ופיזור יותר מכדי מזוג טבעו וכדומה מפני הצורך לו עפ\"י חכ' וטעם, ובפרט עפ\"י תורה שמשיג ויודע איך שמצוה ליתן צדקה לכך מפזר ונותן וכמ\"ש יכלכל דבריו במשפט, ששופט את נפשו, דהגם שאמרז\"ל חייך קודמים<sup data-n=\"859\">16</sup> היינו כשלא יש לו רק קיתון של מים וכשיתן לחבירו לא יספיק לשניהם כדי חיות נפשם אז חייך קודמים, אבל אם יש לו מותרות מכדי הוצאתו ומפזר זה על דברים שאינם מוכרחים לו כלל, יותר טוב ליתן לחבירו מכשיפזר על עצמו מה שאינו צריך לו כלל, דמאי חזית דדמך דידך סומק מדחברך. ואם נפשך לומר הרי נתן לי הקב\"ה ממון רב ויש לי גם על זה שאני מפזר ולחברי לא נתן ואם הי' ברצון הקב\"ה שיהי' לו ג\"כ הי' נותן לו בעצמו, טענה זו מה שנתן לך הקב\"ה ולא לחברך מועלת שאם לא יש לך רק קיתון של מים ואם תתן לחברך לא יספיק לשניכם כדי חיות נפשכם אז חייך קודמים שהרי לך נתן הקב\"ה ולא לחברך, אבל על זה שאתה תפזר על דברים שאינם נצרכים לך וחברך לא יהי' לו אפי' כדי חיות נפשו ע\"ז אינו מועלת טענה זו כלל, דמה שנתן לך הקב\"ה ממון רב הוא כדי שתתן לחברך. ומה שלא נתן לחברך, הנה אמרז\"ל אם הקב\"ה אוהב את עניים למה אינו מפרנסם, אלא יאה עניותא לישראל, שעיקר רצה\"ע הוא כדי שיהי' ביטול היש, ובזה יוצא המכוון לפועל, דהביטול בהעשיר מה שנותן להעני שהרי הוא מייגע עליו בנפשו בכל כחו ואח\"כ נותן לעני הרי זה ביטול, ובהעני הביטול מה שנכנע להעשיר ומבקש ממנו כידוע שאי אפ\"ל מקבל אא\"כ יהי' נכנע להמשפיע וכמו לבנה שמקבלת מהשמש הרי שנעשה תחילה נקודה תחת היסוד שהו\"ע הביטול אזעירת גרמי', סיהרא דלית לה מגרמי' כלום, ואז מקבל מאור השמש ומאיר, וכמו\"כ העני צריך להיות נכנע להעשיר וזהו ביטול היש, וא\"כ עי\"ז יוצא המכוון לפועל שיהי' ביטול היש בהעשיר וגם בהעני, ולכן נתן לזה ממון רב ולזה לא נתן כדי שיהי' ביטול היש, אבל לא שזה יפזר על דברים שאינם נצרכים לו כלל שהוא מותרות וזה לא יהי' לו אפי' על חיות נפשו, וזהו יכלכל דבריו במשפט שנותן צדקה במשפט ששופט את נפשו (ועי\"ז גורם למעלה ג\"כ<sup data-n=\"860\">17</sup> שיהי' אוהב צדקה",[["858","15","<b>שהמדות מתחלקים לג' חלקים מוטבע מורגש מושכל</b>: ראה גם פיה\"מ לאדהאמ\"צ ב, ג ואילך. המשך תער\"ב ח\"ג ע' א'רכה. א'רל."],["859","16","<b>דהגם שאמרז\"ל חייך קודמין</b>: ראה בכ\"ז תניא אגה\"ק סט\"ז (קכד, ב). תו\"א בשלח סג, ב. פיה\"מ לאדהאמ\"צ כה, ד. המשך תער\"ב ח\"א ע' רנג."],["860","17","<b>ועי\"ז גורם למעלה ג\"כ</b>: בגוכי\"ק חסר סיום המוסגר. ואולי צ\"ל בסוף הפיסקא (אחר תיבות: למקום הראוי)."]]],[2000460286,"ומשפט, דכמו שלמטה הצדקה הוא להחיות עניים כמו\"כ לגבי למעלה כולם עניים, שכללות העולמות אינם תופסים מקום כלל וכמארז\"ל מה איכפת לו להקב\"ה אם שוחט מהעורף או שוחט מהצואר, שממית בידים תתפש והיא בהיכלי מלך, דקמי' כחשיכה כאורה בב' כפי\"ם לא די שהחושך שוה לאור אלא שהאור שוה לחשך, וכמ\"ש אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו אם חטאת מה תפעל ומה מידך יקח, אלא כל מצותיך צדק שהוא רק צדקה, וגם חיות שנמשך בכלליות העולמות הוא רק צדקה להחיות רוח שפלים, וזה גורם ע\"י הצדקה שעושה למטה במשפט כמו\"כ גורם למעלה שיהי' במשפט היינו שיומשך למקום הראוי דקמי' כחשיכה כאורה ויוכל לימשך גם לסט\"א וכדי שיהי' ונפלינו אני ועמך שאפי' מבחי' פלא יומשך רק לבנ\"י זהו ע\"י שעושין למטה צדקה במשפט עי\"ז גורמים שהצדקה יהי' במשפט שיומשך למקום הראוי.\n<b>וזהו</b> מושכל שהצדקה הוא מצד מדת החסד, והנה בטבעו הוא חסדן אך מצד השכל שצריכין ליתן צדקה וע\"י המשפט שעושה בעצמו כנ\"ל עי\"ז יפזר על צדקה יותר מכפי מזוג טבעו, אך זה דוקא כשהמדות טבעים שלו הוא חסדן ורחמן אז ע\"י השכל מתגדלים ומצמיחים שיפזר יותר מכפי טבעו, אבל כשבטבעו אינו חסדן לא יועיל לו השכל כלל, וכמו\"כ יובן בנה\"א שטבעו לעלות למעלה כשלהבת העולה מאלי' לכן אח\"כ ע\"י התבוננות יוכל לבוא למדריגה שבלא התבוננות לא הי' יכול לבוא לבחי' זו, כמ\"ש לעיל מיני' רשפיה רשפי אש שלהבת יה, שהוא בחי' שלהבת הבאה מלמעלה שהיא הנפש האלקית שקודם התלבשותה בגוף הגשמי היתה נהנית מזיו השכינה והיתה מיוחדת בתכלית היחוד בא\"ס ב\"ה, וכמ\"ש חי הוי' אשר עמדתי לפניו שעמדה באהוי\"ר וביטול לאלקות, ולזאת גם אחר התלבשותה בגוף הגשמי לעסוק בענינים גשמיים שהם הנק' מים רבים עכ\"ז לא יוכלו לכבותה מלהיות תמיד בבחי' אהבה ותשוקה נפלאה לעלות וליכלל למעלה, ואדרבה ע\"י התלבשותה במים רבים הנ\"ל יכולה להגיע למדריגה היותר גבוה מקודם שירדה לעוה\"ז כמשי\"ת.\n<b>והנה</b> כמו שאי אפשר לנשמה לבוא בג\"ע ליהנות מזיו השכינה עד שתרד קודם לכן בגהנום וכמו שאמרו גבי אחר מוטב דלידייני' וליתי לעלמא דאתי, וגם לטבול בנהר דינור דכדי לעלות ממדריגה למדריגה צריכים לטבול בנהר דינור כדי שלא יבלבל לו מה שהשיג בהמדריגה שלמטה ממנו, וכמו שאמרז\"ל ר' זירא צם מאה תעניתא כדי לשכח תלמוד בבלי מפני שאין תורה כתורת א\"י וכדי שלא יבלבלוהו תלמוד בבלי לכן צם מאה תעניתא, וכמו\"כ כדי שיבוא לבחי' גבוה בג\"ע צריך טבילה בנהר די נור, כמו\"כ ע\"י שעבוד יכולים לעלות למעלה מעלה למדריגה היותר גבוה. והנה שעבוד אין הפי' מה שיש עלינו עתה מלך<sup data-n=\"861\">18</sup> ושנוטל מאיתנו מס",[["861","18","<b>והנה שעבוד אין הפי' מה שיש עלינו עתה מלך</b>: ראה בכ\"ז תו\"א ותו\"ח נח שם."]]],[2000460287,"שגם בזמן בהמ\"ק הי' עלינו מלך ישראל והמס הי' ביותר כידוע שחלק עשירי הוצרך כ\"א ליתן, אלא הכוונה היא שבזמן שבהמ\"ק הי' קיים הי' נמשך ברכה והשפעה עצומה עד שא\"י הי' ארץ זבת חלב ודבש כו' שלא ע\"פ הטבע כלל כמ\"ש בגמ' סוף מס' כתובות ולא הי' כלל דאגות וטרדת הפרנסה, ועתה יש לכאו\"א יגיעת וטרדת הפרנסה לעסוק בעניני עוה\"ז הגשמי והוא בחי' מים רבים הנ\"ל שנק' מי נח שהוא בחי' נייחא דרוחא, לפי שע\"י בחי' מים רבים הנ\"ל מתעלית הנשמה למדריגה היותר גבוה מקודם התלבשותה בגוף.\nחסר"],[2000460288,"<h3>ויירא ויאמר מה נורא</h3>\n<b>ש\"פ ויצא ל\"ט לפ\"ק.</b>\n<b>ויירא</b> ויאמר<sup data-n=\"862\">1</sup> מה נורא המקום הזה אין זה כי אם בית אלקים וזה שער השמים. ופי' הת\"א אין זה כ\"א בית אלקים לית דין אתר הדיוט אלהן אתר דרעוא בי' מן קדם הוי'. ות\"י פי' לית דין אתר חול. וצ\"ל אם חלוקים הן בפירושם או ששניהם פירשו פי' אחד, אלא זה אומר הל' חול וזה אומר הל' הדיוט.\n<b>והנה</b> בחול יש ב' פי' בזהר, הא' דאי' בזהר להבדיל בין קדש לחול בין עשי' לק\"נ (ובפ\"א ובין טמא לטהור<sup data-n=\"863\">2</sup> היינו בין ק\"נ לגקה\"ט לגמרי), וזהו שאנו אומרים במוצש\"ק המבדיל בין קדש לחול בין עשי' לק\"נ. ובמ\"א אי' בזהר חול הוא שרו של עולם מט\"ט נער הייתי וגם זקנתי והוא בחי' ו\"ק דיצי', ובזה גופא יש מדריגות, דהנה כתי' נער הייתי וגם זקנתי דסליק לסיבא ואתהדר כמלקדמין, שבשבת עולה באצי' ולשם נמשך מבחי' סבא קדישא (ובפ\"א שהוא עתיקא קדישא ומבחי' סבא דסבין<sup data-n=\"864\">3</sup>). ואח\"כ בחול אתהדר כמלקדמין שהוא נער וזהו חול (הג\"ה, נראה שר\"ל שבחי' נער הוא חול אבל לא כשהוא בחי' זקן).\n<b>וצ\"ל</b> תחילה הפי' הא' דחול הוא ק\"נ, דהנה נת\"ל ענין י\"א סממני הקטורת<sup data-n=\"865\">4</sup> שהם נגד י\"א כתרין דמסאבותא, ולכאורה והלא בכ\"מ אי' המספר עשר, עשר",[["862","1","<b>ויירא ויאמר</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה, הנדפס לעיל ע' לד. וראה במ\"מ בתחילת המאמר שם."],["863","2","<b>ובפ\"א בין טמא לטהור</b>: מוסגרים אלו מופיעים בגוכי\"ק (ועד\"ז לקמן במאמר כמה פעמים). ור\"ל שבפעם א' בעת אמירת המאמר אמר כ\"ק אדמו\"ר מהר\"ש בלשון הזה, אך לא הי' לשון זה בעת חזרת המאמר בפעם אחרת."],["864","3","<b>ומבחי' סבא דסבין</b>: ראה גם אוה\"ת חנוכה (כרך ב) רפט, ב ואילך."],["865","4","<b>דהנה נת\"ל ענין י\"א סממני הקטורת</b>: ראה לעיל ע' כח וע' לה. וש\"נ."]]],[2000460289,"ספירות בלי מ\"ה, עשר ולא תשע עשר ולא אחד עשר, ומהו המספר י\"א. והענין דבקדושה כתי' ואתה מחי' את כולם ומה שנמשך בהם פועל בהם ביטול, לכן הם עשר, אבל בסט\"א כשהי' נמשך האור בפנימיות הי' נבלע בהם, לכן נמשך בהם דרך מקיף, והוא מקיף דלבונה, ונק' זכה דעצם המקיף הוא קדושה מ\"מ ז\"ך הם ך\"ז אותיות אלפא ביתות שבבחי' מקיף יכולים ליתן חיות גם לסט\"א (ובפ\"א וכמו השבעת השמות מ\"מ אינו מתערב), וההבדלה הוא המקיף דלבונה זכה דכשם שהוא המחבר כמו\"כ הוא המבדיל, דכמו שבאצי' הנה מל' הוא נעשה עתיק לבריאה וזהו מלך יחיד חי העולמים<sup data-n=\"866\">5</sup>, מלך הוא בחי' מל' נעשה יחיד בבריאה [ויחיד הוא עתיק], והפרסא שבין אצי' לבריאה הוא נמשך מבחי' מל', כמו\"כ המקיף דלבונה זכה הוא ההבדלה דממל' דמל' דעשי' נעשה עתיק לק\"נ [שכן הוא בסדר השתל'], והוא ההבדלה, וע\"י שמבררים אותו נמשך מבחי' אנת הוא חד ולא בחושבן<sup data-n=\"867\">6</sup> בבחי' עשר תיקונין (הג\"ה נ\"ל שהוא משנת\"ל שע\"י הביטול היש לאין נמשך בחי' הענג עכ\"ה), ובחי' אנת הוא חד הוא בחי' עתיקא, וא\"כ גם המקיף דלבונה זכה הוא עתיק, הגם שנת\"ל דהמקיף הוא טוב ורק הפנימיות רע דמ\"ש שאין שם שמים שגור בפיו היינו מצד הפנימיות אבל מצד המקיף הוא טוב וזהו שא\"ל איך מעשרין את התבן כו', מ\"מ הבירור צ\"ל דרך המקיף. דהנה יצחק רצה לברר את עשו היינו להמשיך לו ריבוי אור בהמקיף כדי שהפנימיות יוכלל כנר בפני אבוקה, הגם שטעה שתהו א\"א להתברר מאיליו כ\"א דוקא יעקב שהוא בעל עולם האצי', אבל סדר הבירור צ\"ל כך שצריכים להמשיך ריבוי אור בהמקיף, ומוכרח לומר כן דהטעם שבסט\"א י\"א כתרין מפני שאם הי' נמשך בפנימיות הי' נבלע בהם, לכן צריכים לקבל חיות דרך המקיף, ואם הי' הבירור בפנימיות הי' נבלע בהם לכן צריכין להמשיך בהמקיף ריבוי אור, וזהו המבדיל בין קדש לחול היינו בין עשי' לק\"נ, וביו\"ט אומרים המבדיל בין קדש לקדש שיש כמה מדריגות בקדש.\n<b>והנה</b> יש עוד פי' אחר דחול הוא מט\"ט דאי' בזהר ששת ימים עשה כל יומא ויומא עביד עבידתי' כו' ואמאי אקרון חול אר\"י השתא מתנהג עלמא ע\"י דשליחותייהו שהם ו\"ק דיצי'. דכתיב שער החצר הפנימית הפונה קדים סגור יהי'<sup data-n=\"868\">7</sup> ששת ימי המעשה והסגירה אינו לגמרי, כ\"כ בפרד\"ס, וא\"כ זהו חולין שנעשה עטה\"ק שנמשך בהם [מו\"ק ד]אצי', וצ\"ל דהנה בספרים (ובפ\"א בשם מק\"מ) דבכל יום נמשך מו\"ק יום ראשון חסד דאצי' מתלבש בחסד דבריאה וחסד דבריאה בחסד דיצי' וחסד דיצי' בחסד דעשי', והנה מ\"ש בזהר השתא אתנהיג עלמא ע\"י דשליחותייהו ל' רבים הוא מפני כשמאיר מו\"ק דעשי' אז הוא ע\"י סנדל דבחו\"ל נמשך מו\"ק<sup data-n=\"869\">8</sup> ובזמן",[["866","5","<b>וזהו מלך יחיד חי העולמים</b>: ראה תו\"א מקץ מ, ג. מא, ב. סה\"מ תרכ\"ז ע' יח וע' ע. ובכ\"מ."],["867","6","<b>וע\"י שמבררים אותו נמשך מבחי' אנת הוא חד ולא בחושבן</b>: ראה אוה\"ת תולדות קנב, א ואילך. לעיל ע' כח ואילך."],["868","7","<b>סגור יהי'</b>: כ\"ה ג\"כ לעיל במאמר ע' לו. והוא צירוף ב' כתובים, כי ביחזקאל מו, א: שער החצר הפנימית הפונה קדים יהי' סגור גו'. ושם מד, א: השער הזה סגור יהי' לא יפתח."],["869","8","<b>דבחו\"ל נמשך מו\"ק</b>: כ\"ה בגוכי\"ק."]]],[2000460290,"הבית בכללות הארץ נמשך מו\"ק דיצי' (ובפ\"א כן משמע בפרד\"ס שרק בזה\"ב האור מו\"ק דיצי').\n<b>הג\"ה</b>, ע' בס' חסד לאברהם מאמר ג' עין הארץ נהר י\"ב שכ' וז\"ל דע כי נשמות הדרים בא\"י באים מי' ספי' של היצי' כו' כי כשאדם הוא בח\"ל יש לו נפש מהאופנים (שהוא עולם העשי' כידוע) וכשזוכה ליכנס לא\"י בא אליו נפש מיצי' חדשה כו' עכ\"ל. הרי שפי' שמקבל מיצי' ומשמע ממנו שגם לאחר חורבן הבית, וע' במאמר הנ\"ל בנהר ג' שכ' דבהמ\"ק שהי' ת\"ק אמה על ת\"ק אמה הוא מכוון נגד חלון השמים שהוא ג\"כ כמספר הנ\"ל ונמשך לבהמ\"ק דרך החלון הנ\"ל מלמעלה דרך צנור מל' הספי' י' מעולם האופנים הוא יורד דרך ישרה עד חלון הכיפה הנז' ויורד על בה\"מ ומשם מתפשט על כל א\"י, וענין חורבן הבהמ\"ק הוא שנסתם החלון, ואח\"כ נפתח החלון והוריד עולם האופנים וצמצם מל' עולם האופנים בתוך החלון, ע\"כ. מפרש שבבהמ\"ק נמשך האור מהיכל קדה\"ק דבריאה ובאמת אורות האצי' נמשכים בבריאה וכמשית\"ל אי\"ה ונמשך בעולם היצי' (צ\"ע אם בדרך התלבשות או בדרך מעבר, ולפי משנת\"ל צ\"ל דבבהמ\"ק נמשך האור מעולם הבריאה שלא בדרך התלבשות היצי' ובא\"י נמשך ע\"י התלבשות היצי') ועובר דרך צנור מל' דעשי' רק בדרך מעבר וכמו שמשמע לקמן אי\"ה (משמע אבל בבריאה הוא בדרך התלבשות). ומ\"ש ועובר דרך שער השמים איני יודע פירושו מהו שער השמים. וזה הי' בזמן הבית שהי' נמשך האור מעולם היצי' רק דרך מעבר הבריאה, אבל לאחר חורבן הבית אף שפתח החלון מ\"מ לא נמשך רק מל' דעשי', דעל קודם חורבן הבית אומר שנמשך מלמעלה דרך צנור הרי שנמשך מלמעלה מהצנור אך עובר דרך הצנור, וכאן אמר וצמצם מל' עולם האופנים שהוא הצינור שהי' קודם חורבן הבית ודרך בו נמשך אור עליון ואינו מתלבש בתוכו כמו צינור שמה שנמשך דרך בו אינו משתנה בו, נמצא שנמשך דרך בו אור עליון כנ\"ל, ואחר חורבן הבית נמשך ממנו האור שלו, ובנהר י\"ב שהובא לעיל משמע שגם אחר החורבן נמשך מעולם היצי', ובמעיין שלישי נהר י\"ד כ' וז\"ל ואמנם זכו לזה שהנהגתם הי' בקדושה ע\"י מט\"ט עכ\"ל<sup data-n=\"870\">9</sup>, וידוע דמט\"ט הוא ו\"ק דיצי', וא\"כ דבריו סותרים זה את זה (וצ\"ע אם מ\"ש כאן דבזמן שבהמ\"ק קיים נמשך מו\"ק דיצי' בא להוציא אפי' קודם בנין הבהמ\"ק האיר",[["870","9","<b>ובמעיין שלישי נהר י\"ד כ' וז\"ל ואמנם זכו לזה שהנהגתם הי' בקדושה ע\"י מט\"ט עכ\"ל</b>: צ\"ל: ובמעיין ראשון כו'. וז\"ל שם: בהנהגת ישראל אחר פטירת מרע\"ה וכניסת ישראל לארץ הנה זכו ישראל בכניסתן לארץ מצד אחד והוא חוב להן מצד אחר. הנה זכו במה ששברו הקליפות ונכנסו לארץ באויר של הקדושה וטהרה שאין שום קליפה בהכיבוש שכבשו והמעלה הזו מעולם לא הי' אפילו אל האבות שישבו בה, ואמנם זכו לזה [ובדפו\"א: חבו לזה] שהנהגתם הי' בקדושה ע\"י מט\"ט אשר דחה אותו מרע\"ה כמ\"ש רז\"ל ע\"פ אני שר צבא ה' עתה באתי כדפרש\"י ז\"ל עתה באתי בימי יהושע אבל לא בימי מרע\"ה כו'. ע\"כ. וראה עוד מענין עתה באתי כו' וההנהגה בימי יהושע ע\"י מט\"ט — בד\"ה ונערים ממשתה נגינתם בסה\"מ תקס\"ח ח\"ב ע' תרכב ואילך. ובהגהות לשם בס' אוה\"ת על סידור ע' רצו ואילך. ובס' תורת שמואל — דרושי חתונה ע' צז ואילך."]]],[2000460291,"מו\"ק דעשי' וא\"כ צ\"ע דמחסד לאברהם הנ\"ל משמע שאף קודם שהי' בנין בהמ\"ק האיר מו\"ק דיצי', או נאמר שאף קודם בנין הבית האיר מו\"ק דיצי' ולא בא אלא להוציא שאחר חורבן הבית האיר מו\"ק דעשי') עכ\"ה).\n<b>וא\"כ</b> מהו חולין שנעשו עטה\"ק. והענין דהנה בהתלבשות גופא יש כמה מדריגות יש התלבשות שהוא העלם, ויש אף שהוא התלבשות מ\"מ הוא גילוי, ויש מעבר. וההפרש גדול ביניהם, דהתלבשות נק' האור ע\"ש דבר הנלבש, ומעבר נק' ע\"ש המשפיע, וזהו ענין חולין שנעשו עטה\"ק. והנה כדי להבין בכלל ענין חול הנה מצינו ל' חול בנדרים דכתיב לא יחל דברו, וצ\"ל ענין נדרים בקצרה. הנה נדרים הם סיג לפרישות, דכשאינו יכול לברר הניצוץ פורש ממנו לגמרי. והנה נדרים הם בבינה וכמאמר כל הנודר כאילו נודר בחיי המלך<sup data-n=\"871\">10</sup> שהוא בחי' בינה, דאלקים חיים ומלך עולם, מלך עולם הוא ז\"א דעולם היינו מל' מלכות כל עולמים.\nחסר",[["871","10","<b>וצ\"ל ענין נדרים בקצרה. . כאילו נודר בחיי המלך</b>: ראה גם ד\"ה וידבר גו' ראשי המטות הנדפס לקמן ח\"ב. אוה\"ת מטות ע' א'שכו ואילך. ובהנסמן עוד לעיל ע' לז."]]],[2000460292,"<h3>אתה אחד</h3>\n<b>ש\"פ וישלח ל\"ט לפ\"ק.</b>\n<b>אתה</b> אחד<sup data-n=\"872\">1</sup> ושמך אחד ומי כעמך כישראל גוי אחד בארץ, משמע שע\"י גוי אחד ממשיכים אתה אחד ושמך אחד. וכן משמע בגמ' אתם עשיתוני חטיבה אחת אף אני אעשה אתכם חטיבה אחת, אתם עשיתוני חטיבה אחת ה' אלקינו הוי' אחד, אף אני אעשה אתכם חטיבה אחת מי כעמך כישראל גוי אחד בארץ [שהוא השתבחות דהקב\"ה בישראל], משמע שע\"י גוי אחד ממשיכים הוי' אחד שהוא כולל אתה אחד ושמך אחד. וצ\"ל דהנה אתה הוא קודם שנבה\"ע אתה הוא לאחר שנבה\"ע, אני ה' לא שניתי, ואיך שייך להמשיך אתה אחד ושמך אחד. ועוד צ\"ל דהנה אמרז\"ל ע\"פ ביום ההוא יהי' הוי' אחד ושמו אחד אטו האידנא לאו אחד הוא, דהאידנא ג\"כ אחד הוא. והנה על הוי' אחד תירצו לא כעוה\"ז עוה\"ב, דלעוה\"ב יהי' כולו הטוב והמטיב, ועל שמו אחד תירצו לא כמו שאני נק' אני נכתב דלא כהעוה\"ב עוה\"ז דבעוה\"ז הקרי שם הוי' והכתיב אד' ובעוה\"ב יהי' הקרי ג\"כ שם הוי' כמו הכתיב, א\"כ דוקא ביום ההוא יהי' הוי' אחד וא\"כ מהו עשיתוני.",[["872","1","<b>אתה אחד</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה, הנדפס לעיל ע' מ. וראה במ\"מ שם בתחילת המאמר. עניני המאמר נמצאים באריכות בד\"ה אתה אחד בסה\"מ קונטרסים ח\"א קס, א, וכנראה הוא מיוסד על לשון ההנחה כאן."]]],[2000460293,"<b>והנה</b> להבין זה צ\"ל ענין מלחמת יעקב דכתיב ויותר יעקב לבדו<sup data-n=\"873\">2</sup> ויאבק איש עמו עד עלות השחר ויאמר שלחני כי עלה השחר, משמע שהמלחמה הי' מפני שויותר לבדו, וענין מ\"ש ויאבק איש עמו אמרז\"ל מלמד שהעלה אבק עד תחת כסה\"כ, וצ\"ל דהנה לכאורה עיקר המלחמה לא הי' האבק, דהמלחמה הי' מצד ד\"א אך כשלוחמים עולה אבק, א\"כ הוא דבר הבא ממילא ואיך שייך לקרות המלחמה ע\"ש דבר הבא ממילא. והנה צ\"ל ענין מלחמת עמלק דכתי' מלחמה להוי' בעמלק, וצ\"ל מה שייך ללחום עם שם הוי' דכתי' ואתה מחי' את כולם א\"ת מחי' אלא מהווה ושם הוי' הוא מקור כל ההתהוות וא\"כ איך שייך ללחום עם שם הוי'.\n<b>והנה</b> כדי להבין זה צ\"ל משארז\"ל ר\"א רמי כתיב טוב ה' לכל וכתיב טוב ה' לקויו, משל כשהוא משקה משקה את כל השדה כולה אף מה שאינו נצרך לו, וכשהוא עודר אינו עודר אלא הטובים שבהם סביב האילנות. וצ\"ל המשל והנמשל. וצ\"ל תחילה ענין אתם עשיתוני חטיבה א' שמע כו' ה' אחד ולכאו' הול\"ל יחיד<sup data-n=\"874\">3</sup>, לבד מה שאחד מורה על א' המנוי כמו מע\"ב, והשבטים שהיו י\"ב א' מהם נק' אחד כמ\"ש ויפתח האחד את שקו, לבד זאת הנה אחד מורה על שלימות מצד ההתכללות כמו האדם שהוא כלול מרמ\"ח אברים אך הוא שלימות נק' אחד, אבל א\"ס שהוא פשוט בתחה\"פ איך שייך לומר עליו א'. והענין דהנה אמרז\"ל כד אמליכתי' למעלה ולמטה ולד' רוחות העולם תו לא צריכנא והו\"ע יחוד אלקות בעולמות וזהו תיבת אחד דאל\"ף קאי על א\"ס אלופו ש\"ע מה שברה\"ע לא הי' אפשר להיות באל\"ף כ\"א בבי\"ת ואח\"כ כשהי' ברה\"ע בבי\"ת הי' אפ\"ל מ\"ת באל\"ף, ובחי' זו יאיר בח' וד'.\n<b>והנה</b> כדי שיאיר בחי' זו דאנת הוא חד ולא בחושבן י\"ס ולאו מכל אלין מדות כלל, ולית מחשבה תפיסא בי' כלל, מח' הוא חכ' דאי' בזהר מחשבה ויובלא לא אתפריש לעלמא (מח' חכ', ויובלא בינה<sup data-n=\"875\">4</sup> כידוע), שבחי' חכ' אינו תופס מקום כלל, וכדי שיאיר בחי' זו בעולמות צ\"ל צמצום [אבל יחיד הוא עצמות א\"ס שלפני הצמצום] (הג\"ה אפ\"ל שהוא מכוון עם מ\"ש בתו\"ח ד\"ה ויהי כל הארץ שפה א' בפי' אנת הוא חד כו', וזהו שאנו אומרים אחד ולא יחיד דצריכים להמשיך אוא\"ס בעולמות והוא ע\"י צמצום, אבל יחיד הוא למעלה מהצמצום, כמ\"ש שם עכ\"ה).",[["873","2","<b>והנה להבין זה צ\"ל ענין מלחמת יעקב דכתיב ויותר יעקב לבדו</b>: ראה בכ\"ז תו\"א וישלח כו, א. אוה\"ת בראשית (כרך ב) תנז, ב. לקמן ד\"ה כמים הפנים [שם נמצא המשך הביאור ע\"פ ויותר יעקב לבדו גו']."],["874","3","<b>שמע כו' ה' אחד ולכאו' הול\"ל יחיד</b>: ראה תו\"א וארא נה, ב. ואילך. ובהנסמן עוד לעיל בהמאמר ע' מב."],["875","4","<b>מח' הוא חכ' דאי' בזהר מחשבה ויובלא. . מח' חכ' ויובלא בינה</b>: ראה תו\"א ז, ד (ע\"פ זח\"א קכג, א). תו\"ח חיי\"ש קכו, ב. סה\"מ תרל\"ב ח\"א ע' רטו. תרל\"ג ח\"א ע' פה. קונטרס לימוד החסידות ע' 5. וש\"נ."]]],[2000460294,"<b>והענין</b> דהנה אמרז\"ל צמצם שכינתו<sup data-n=\"876\">5</sup> בין שני בדי הארון, וצ\"ל הלא בבהמ\"ק הי' גילוי אלקות דבמקדש קוראין את השם ככתבו ובמדינה בכינויו, דההוגה את השם באותיותיו אין לו חלק לעוה\"ב לאבא שאול, ובמקדש קוראין אותו ככתבו, ששם האיר שם הוי', וגם משה קבל נבואתו שם כמ\"ש ונועדתי אליך שם ודברתי אתך מעל הכפורת מבין שני הכרובים, ומהו הצמצום. אך הענין דהיא הנותנת דכדי שיהי' גילוי זה צ\"ל צמצם שכינתו בין שני בדי ארון, ארון הוא אור נו\"ן<sup data-n=\"877\">6</sup> וצ\"ל צמצום, וזה\"ע הוי' ועיקר הוי' הוא יו\"ד שהוא חכ' והוא צמצום, ולכן יעקב שהשיג מקום המקדש אמר אכן יש הוי' במקום הזה.\n<b>והנה</b> כדי שיהי' הצמצום הוא ע\"י הביטול, דבמקום שבטל שורה אוא\"ס, כמ\"ש בסש\"ב שמעתי ממורי שבחכ' השראת אחד האמת<sup data-n=\"878\">7</sup> שהוא ביטול. ובעבודה בנפש האדם העיקר הוא הביטול דמוחין שהוא ביטול האמיתי, משא\"כ הביטול דמדות כמו אהבה הרי יש מי שאוהב, וצריכים להמשיך מוחין למדות שיהי' התכללות המדות אהוי\"ר וממילא יהי' הזזה בהמדות, מ\"מ העיקר הוא הביטול דמוחין שהוא כח מ\"ה. ומי שאין לו הביטול דמדות הנה יש ענפי המדות, נצח הוא ענף החסד וצ\"ל נצחון שלא יהי' מופרד מאלקות ויהי' מקושר לאלקות, ובזה אינו שייך התבוננות דחסד הוא מצד ההתבוננות אבל נצח אינו שייך להתבוננות רק שיהי' מקושר ואל יהי' נפרד. ומי שאין לו גם זה הנה יש עוד בחי' והו\"ע ההודאה שמודה שהוא כן אף שאינו מבין בשכלו שצ\"ל כן מ\"מ מודה שצ\"ל כן, וזה אפ\"ל לכאו\"א לכן אמרז\"ל מאן דלא כרע במודים אינו קם לתחה\"מ, ובזה גופא יש מדריגות, הודאה, והודאה להודאה, וזהו מיד כשאדם עומד משנתו והוא אז ברי' חדשה אומר מודה אני לפניך היא המדריגה היותר נמוכה, ואח\"כ אומרים הודו להוי', ואח\"כ בסיום שמ\"ע אומרים מודים אנחנו, וזהו מצד מדריגה שאינו שייך השגה, דתחילה אומרים ק\"ש וברכת ק\"ש שהוא השגה אך לית מחשבה תפיסא בי' כלל לכן אומרים אח\"כ מודים אנחנו לך, וע\"י הביטול שפועלים למטה גורמים למעלה שיהי' הצמצום.\n<b>והנה</b> בסיום הקדושה יכולים לקבל גם סט\"א, וזהו המבדיל בין קדש לחול, ומקבלים מאחורי העור של בחי' מל'. ועל לשון ע\"ח שמקבלים מבין צירוף לצירוף<sup data-n=\"879\">8</sup> בין נקב לנקב, דבעור האדם יש נקבים, מל' הוא (עולם) הדיבור ויש צירופי",[["876","5","<b>והענין דהנה ארז\"ל צמצם שכינתו</b>: ראה גם לקו\"ת אמור לד, ד. אוה\"ת חנוכה (כרך ה) תתקכה, א. סה\"מ תרל\"ב ח\"א ע' מח וע' רי."],["877","6","<b>ארון הוא אור נו\"ן</b>: ראה אוה\"ת חוקת (הוצאת תשנ\"ח) ע' תתפט. סה\"מ תרל\"ה ח\"ב ע' תנז. תרל\"ח ע' קמח. לקמן ח\"ב ד\"ה עבדו את ה' בשמחה."],["878","7","<b>כמ\"ש בסש\"ב שמעתי ממורי שבחכ' השראת האמת</b>: תניא פל\"ה (בהגה\"ה)."],["879","8","<b>ועל לשון ע\"ח שמקבלים מבין צירוף לצירוף</b>: ראה גם תו\"א וישלח כו, ב. לקו\"ת שמע\"צ צ, ד. סה\"מ תקס\"ב ח\"א ע' קט. סה\"מ תרל\"ב ח\"א רכה. ובכ\"מ."]]],[2000460295,"אותיות הדיבור ובין צירוף לצירוף בין נקב לנקב מקבלים הם, ואף זאת מאחורי העור. היוצא מזה שחיותם חיות מועט.\n<b>וזהו</b> ר\"א רמי כתי' טוב ה' לכל וכתיב טוב ה' לקויו, משל כשהוא משקה משקה את כל השדה כולה, וכשהוא עודר אינו עודר אלא הטובים שבהם, דטוב הוא השפעת רוחני' עד [שנעשה] השפעת גשמיות, וזהו לכל דע\"צ ההכרח צריך להימשך גם לסט\"א, אך טוב ה' לקויו, היינו השראת אוא\"ס זהו דוקא לנפש תדרשנו שהו\"ע אתעדל\"ת וזהו לקויו מי שהוא בטל לזה נמשך השראת אוא\"ס.\n<b>וזהו</b> מלחמה להוי' בעמלק, דהנה עמלק הוא חוצפה ועקשות וגסות, אם תגביה כנשר, דרך הנשר בשמים, וזהו החוצפה שמגביהים לקבל מבחי' זו ששם הביטול אינו תופס מקום כלל, וכמ\"ש שממית בידים תתפש<sup data-n=\"880\">9</sup> והיא בהיכלי מלך, אפי' בהיכלי מלך מ\"מ שממית כו' ודוקא בהיכלי מלך ששם אינו נוגע כלל דאם צדקת מה תתן לו ורבו פשעיך מה תעשה לו אם חטאת מה תפעול בו ומה מידך יקח. אך משם אורידך נאום הוי' דכך עלה ברצונו שיהי' רצון אותיות צינור שיהי' אני הוי' אני הוא עצמיות אוא\"ס, שיהי' אני הוי' כולא חד. וזהו מלחמה להוי' בעמלק, דלמעלה משם הוי' אינו נוגע כלל, אך בשם הוי' שבסדר השתל' הוא לוחם שיומשך למקום הראוי דוקא, וזהו משם אורידך אפי' ממדריגה ששם (אפ\"ל שהוא מ\"ש קרא שם פרעה מלך מצרים) מגיע, ג\"כ אורידך. ובאמת לאו דוקא ברצון אפי' בחפץ ג\"כ דאי' במדרש והארץ היתה תהו אלו מעשיהן של רשעים, ויאמר אלקים יהי אור אלו מעשיהם של צדיקים, ועדיין איני יודע באיזה מהם חפץ וכשהוא אומר וירא אלקים את האור כי טוב הוי כשהוא חפץ אינו חפץ אלא במעשיהם של צדיקים. ולכאורה מהו החקירה בתחילת ברה\"ע, והלא ברה\"ע הי' כדי שיהיה המשכת אלקות ומהו החקירה באיזה מהם חפץ. והענין דהנה בפנימיות הרצון באיזה מהם חפץ, וכשהוא אומר וירא אלקים את האור כי טוב הרי גם בפנימיות הרצון ג\"כ חפץ במעשיהם של צדיקים, ואמר ל' חפץ הרי שגם בבחי' חפץ יומשך רק למקום הראוי. והענין הוא שיומשך האל\"ף, שברה\"ע לא הי' אפשר להיות באל\"ף מפני שהוא ר\"ת ארור<sup data-n=\"881\">10</sup> כ\"א בבי\"ת בחכמה יבנה בית יבנה בי\"ת, ואחר שהי' ברה\"ע בבי\"ת יכול להיות מ\"ת באל\"ף [וצריכים להמשיך האל\"ף בח' ד'] (ובפ\"ג כנ\"ל<sup data-n=\"882\">11</sup>).\n<b>ולכן</b> אומרים אחד ולא יחיד, דמצד יחיד אפשר סט\"א ג\"כ לקבל לכן אומרים יחיד<sup data-n=\"883\">12</sup> שיומשך למקום הראוי. וזהו מי כעמך כישראל גוי אחד בארץ שממשיכים",[["880","9","<b>אם תגביה כנשר. . שממית בידים תתפש</b>: ראה תו\"א ויחי קב, ב ואילך. קג, ד ואילך. סה\"מ תרל\"ב ח\"א ע' נג ואילך. ועוד."],["881","10","<b>שברה\"ע לא הי' אפשר להיות באל\"ף מפני שהוא ר\"ת ארור</b>: ראה הנסמן ע\"ז לעיל במאמר ס\"ע מה."],["882","11","<b>ובפ\"ג כנ\"ל)</b>: ר\"ל שבעת חזרת המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש בפעם שלישית אמר ג\"כ: וצריכים להמשיך האל\"ף כו'."],["883","12","<b>לכן אומרים יחיד</b>: כ\"ה בגוכי\"ק, ואוצ\"ל אחד."]]],[2000460296,"אחד בארץ. והענין דהנה כתיב וזאת המצוה אשר צוה ה' לעשות בארץ שמע ישראל כו', והי' לו לומר כל התרי\"ג ומהו אומר רק מצות ק\"ש. והענין דק\"ש כולל הכל דנכלל בו תורה ומצות ואפי' דברים גשמים נכלל ג\"כ בפ' שני' (ובפ\"ג ופ' שני'<sup data-n=\"884\">13</sup> [שייך לפ' ראשונה א\"כ] הוא ג\"כ דבוק לאחד) דכתיב ואספת דגנך ותירושך ויצהרך ולכאורה מה שייך זה לק\"ש הגם שיש דרשות ע\"ז בגמ', אך אין מקרא יוצא מידי פשוטו. והענין שצריכים לקבץ כל ענינים גשמים ולהעלותם לאלקות. דהנה הגם שכאו\"א צריך לעסוק במו\"מ לפי ערכו, אך במח' אחת יכולים להעלותם לאלקות. דהנה מה שעוסק במו\"מ הוא כדי להרויח וכשירויח יהי' על צרכי גופו ויוכל ללמוד ולהתפלל, וגם העושה צדקות בכל עת זה הזן ומפרנס בניו וב\"ב, וגם שיתן צדקה (לעניים), ועי\"ז מעלה אותם לאלקות, וזהו בארץ שממשיכים אחד בארץ, ועי\"ז יומשך ה' אחד שהוא כולל אתה אחד ושמך אחד [כמ\"ש ברש\"י זה שאתה הוי' אלקינו יהי' לע\"ל הוי' אחד] דכתיב ויקרא הוי' הוי', שיש ב' שמות הוי'<sup data-n=\"885\">14</sup> אחד שבסדר השתל' ואחד למעלה מסדר השתל', והנה מצד שם הוי' שבסדר השתל' יש חסדים אבל מצד שם הוי' שלמעלה מסדר השתל' לית שמאלא בהאי עתיקא והגבורות הוא תגבורת וצריכים להמשיך משם הוי' שלמעלה מסדר השתל' וזהו ע\"י גוי אחד ממשיכים אתה אחד שהוא בחי' הוי' אחד.",[["884","13","<b>ובפ\"ג ופ' שני'</b>: ר\"ל אשר בעת חזרת המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש בפעם שלישית, אמר הלשון: ופרשה שני' כו'."],["885","14","<b>דכתיב ויקרא הוי' הוי' שיש ב' שמות הוי'</b>: ראה תו\"א בשלח סא, ד ואילך. תצוה פג, א. פד, א. לקו\"ת תזריע כא, ד. חוקת נז, ג. דרושים לר\"ה נט, א. ועוד."]]],[2000460297,"<h3>כמים הפנים</h3>\n<b>י\"ט כסליו ל\"ט.</b>\n<b>כמים</b> הפנים<sup data-n=\"886\">1</sup> לפנים כן לב האדם אל האדם, ופירש\"י כשאדם רואה במים מראה הפנים שלו במים, כן לב האדם אל האדם כמו שמראין לו כן הוא נראה. וצ\"ל מהו\"ע המשל ממים, ואומרו לב האדם למה אמר לב דוקא.\n<b>והענין</b> דהנה כתיב זה דור דורשיו מבקשי פניך יעקב סלה, וצ\"ל הלא פניך הוא של הקב\"ה כמ\"ש את פניך הוי' אבקש, ומהו אומרו אח\"כ יעקב. והנה מפרשים פי' כל המבקש פניו של יעקב<sup data-n=\"887\">2</sup> הוא מזרע של יעקב וכל שאינו מבקש פניו",[["886","1","<b>כמים הפנים</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב מד\"ה זה, הנדפס לעיל ע' מט. וע\"ש בהמ\"מ בתחילת המאמר. מאמר זה קשור עם ד\"ה אתה אחד שלפני\"ז."],["887","2","<b>והנה מפרשים פי' כל המבקש פניו של יעקב</b>: אולי במקום יעקב, צ\"ל: הקב\"ה. וראה במ\"מ לעיל במאמר ס\"ע מט."]]],[2000460298,"של הקב\"ה כו'. והענין דהנה הגם שכל האבות הן המרכבה, מ\"מ יעקב הוא בחיר שבאבות שההשפעה פנימיות הוא ע\"י יעקב, דלבד שהוא בריח התיכון המבריח מן הקצה אל הקצה קצה העליון וקצה התחתון, הוא מחבר חו\"ג, הרי שהוא התכללות ב' הפכים, והוא שלימות מעלה ומטה וחו\"ג, לכן ההשפעה פנימיות הוא ע\"י יעקב. ולכן נק' פנים כמארז\"ל ע\"פ ויוציאך ה' בפניו בכחו הגדול<sup data-n=\"888\">3</sup>, בפניו זה יעקב, בכחו זה יצחק, הגדול זה אברהם, דבפנים שם כל החושים הנעלים כמו ראי' שהוא מהחושים הנעלים, וטעם וריח ושמיעה ג\"כ שייך להפנים, לכן יעקב שהוא בחיר שבאבות נק' פנים.\n<b>וזהו\"ע</b> מלחמת יעקב שלחם עם אותו האיש<sup data-n=\"889\">4</sup>, דכתיב וירא כי לא יכול לו ויגע בכף יריכו<sup data-n=\"890\">5</sup>, ומה ראה. והענין דהנה האבות הן המרכבה מרכבתא עילאה דאצי', ואותו האיש טעה וסבור שהם מרכבה למדות, וכתיב שממית בידים תתפש והיא בהיכלי מלך, באיזה זכות השממית מתחפשת בזכות הידים וגם צפרנים גדלים מהידים. אך הנה לבד מה שיעקב הוא יו\"ד עקב שהיו\"ד נמשך עד העקביים דכתיב וידו אוחזת בעקב עשו שאפי' בעקב עשו נמשך ג\"כ היו\"ד, יו\"ד הוא חכ' וכתיב ימותו ולא בחכמה שחכמה הוא למעלה משבירה ותיקון, וזהו יעקב לא מת<sup data-n=\"891\">6</sup> דמאן דנפל מדרגא איקרי מית אבל יעקב הוא בחי' שלמעלה משבירה ותיקון (הג\"ה אפ\"ל שזה נתינת טעם למה הוא נמשך עד העקבים מפני שבחכמה לא הי' שבירה לכן בכחו לברר, ואיני זוכר איך אמר זה אם בדרך טעם או ענין בפ\"ע, עכ\"ה). הנה לבד זאת הנה כתיב אז יבקע כשחר אורך וארוכתך מהרה תצמח, שתחילת בקיעת החושך הוא [ע\"י] יעקב, וזהו ויותר יעקב לבדו<sup data-n=\"892\">7</sup> שאפי' מבחי' לבדו יומשך ג\"כ. וזהו כי לא יכול לו דהנה כתיב מלחמה להוי' בעמלק דלמעלה משם הוי' שם אינו תופס מקום כלל, אך בשם הוי' שייך מלחמה. אך שם הוא כדי שלא יומשך (הג\"ה. אך כאן הי' המלחמה למעלה משם הוי' כנ\"ל בענין אז יבקע כו' ולכאורה שם יכול לקבל, ע\"ז תירץ) אך ענין המלחמה הוא בשם הוי' שלא יומשך בסדר השתל' וכאן בבחי' אז יבקע הוא שיומשך ג\"כ בסדר השתל' (הג\"ה. ולזה נלחם עמו שלא יומשך לסדר השתל', ומפני שגם בחי' אז יבקע נמשך בסדר השתל' לכן לא יכול לו, וזהו דגבי עמלק כתיב מלחמה להוי' בעמלק מדור דור שבכל דור ודור יש מלחמת עמלק, וגבי יעקב כתיב לא יכול לו ולא הי' עוד מלחמה, ולפ\"ז אפ\"ל דמלחמת עמלק הי' עם שם הוי' לכן מדור דור, דשם הוא בסדר השתל' ואפשר להלחם עמו, אבל ביעקב שהוא",[["888","3","<b>ויוציאך ה' בפניו בכוחו הגדול</b>: ע\"פ ואתחנן ד, לז."],["889","4","<b>מלחמת יעקב שלחם עם אותו האיש</b>: לעיל במאמר (ע' נ) מפורש הס\"מ. אבל כאן כנראה נרשם ע\"פ הסגנון בעת אמירת המאמר."],["890","5","<b>דכתיב וירא כי לא יכול לו ויגע בכף יריכו</b>: ראה בכ\"ז תו\"א וישלח, כו, ב ואילך. אוה\"ת שה\"ש כרך ב' ע' תשיח ואילך. וראה אוה\"ת וישלח רמה, א ואילך. שם (כרך ה) תתעו, ב."],["891","6","<b>אך הנה לבד מה שיעקב הוא יו\"ד עקב. . וזהו יעקב לא מת</b>: ראה בכ\"ז ביאוה\"ז לאדהאמ\"צ קלז, ב. אוה\"ת וישלח שם תתעו, ב."],["892","7","<b>וזהו ויותר יעקב לבדו</b>: ראה לעיל ד\"ה אתה אחד, בתחילתו."]]],[2000460299,"בחי' אז יבקע כנ\"ל לכן א\"א להלחם עמו, עכ\"ה). וזהו וירא שראה שא\"א לו להלחם עמו ויגע בכף יריכו ירכין הם נו\"ה שפגם בנצח, בא שמואל הנביא ותיקן<sup data-n=\"893\">8</sup> דכתיב וגם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם.\n<b>וזהו</b> ויאבק איש עמו, דהנה כמו שיש לעו\"ז דהוי' איש מלחמה כמו\"כ יש לעו\"ז כנגד מל' דקדושה, ואי' בזהר שהו\"ע אבק ועפר<sup data-n=\"894\">9</sup>, עפר הוא מ\"ש ומן העפר אשר יהי' בקרקע המשכן, ואבק הוא לעו\"ז של עפר, והעלה אבק שאף האבק העלה עד תחת כסא הכבוד הוא בחי' מל' דקדושה. דהנה יש עוד פי' בתי' אבק ל' אבוקה<sup data-n=\"895\">10</sup>, [דהנה אמרז\"ל למה הצדיקים דומין בפני הקב\"ה כנר בפני אבוקה וכמו\"כ כנגד בע\"ת ג\"כ כנר בפני אבוקה, דצדיק הם נר הוי' נשמת אדם ובע\"ת משכין לי' לקוב\"ה בחילי' יתיר]. והנה להבדלה ההידור שיהי' אבוקה ומה שייך אבוקה להבדלה. והענין דהנה הבדלה הוא להבדיל בין קודש לחול שהם ע\"ס דנוגה, והגם שיש מקיף דלבונה זכה מ\"מ ההשפעה היא כדי שיהי' חיל בלע ויקיאנו [וכמו שנת\"ל בענין הברכות שיצחק רצה לברך את עשו כדי להמשיך לו ריבוי אור ויקח ממנו הניצוצות כמו\"כ כאן ע\"י.\n]חסר]",[["893","8","<b>ויגע בכף יריכו ירכין הם נו\"ה. . בא שמואל הנביא ותיקן</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיט ואילך. דרמ\"צ יב, א ואילך. ובכ\"מ."],["894","9","<b>ואי' בזהר שהו\"ע אבק ועפר</b>: ראה בארוכה אוה\"ת שה\"ש שם ע' תשכ. וראה גם אוה\"ת בראשית (כרך ג) תקכו, ב. בשלח ע' תנג. וראה ספר הערכים חב\"ד ח\"א ערך אבק ע' סג ואילך."],["895","10","<b>דהנה יש עוד פי' בתי' אבק ל' אבוקה</b>: ראה גם אוה\"ת שה\"ש שם (ע' תשכ). אוה\"ת ויצא קפח, א. ספר הערכים חב\"ד ח\"א ע' טו אילך."]]],[2000460300,"<h3>בד\"ה המגביהי לשבת</h3>\n<b>ש\"פ מקץ ל\"ט לפ\"ק</b>\n<b>בד\"ה</b> המגביהי<sup data-n=\"896\">1</sup> לשבת כו' בענין שמיני אפ\"ל זהו מעלת הכוכבים שהם ברקיע תמינאה בינה (ולכן (ישעי' כ\"ד כ\"ג) ובושה החמה וחפרה הלבנה וכוכבים לא כתי', דהנה אמרז\"ל (פסחים ס\"ח ע\"א) ר\"ח רמי כתי' וחפרה הלבנה ובושה החמה וכתי' והי' אור הלבנה כאור החמה כו' (ופירש\"י וחפרה ובושה (ולא כמו שפי' הוא ז\"ל בישעי' על הפסוק הנ\"ל כמו שפי' הת\"י ויבהתון דסגדין כו') יהי' שבעתים כו'",[["896","1","<b>בד\"ה המגביהי</b>: הבא להלן, הוא הגה\"ה על המאמר ד\"ה מי כה' אלקינו גו' המגביהי לשבת, הנדפס לעיל בספר (מש\"פ וישב). הגהות אלו נמצאו על גליון בפ\"ע בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב, ואפשר הוא מה ששמע מכ\"ק אדמו\"ר מהר\"ש בש\"פ מקץ על המאמר של שבת הקודם, ובתוס' כמה הגהות מדילי' בתוך מוסגרים."]]],[2000460301,"שבעתים הם ארבעים ותשע וכתי' כאור שבעת הימים כו' נמצא עודף על אור של עכשיו ג' מאות וארבעים ושלשה עכ\"ל), (והוא גי' גש\"ם) ל\"ק כאן לעוה\"ב כאן לימות המשיח (ופירש\"י בעוה\"ב וחפרה הלבנה ובושה החמה שלא יהי' בעולם אלא זיו זוהר ומראה שכינה עכ\"ל), ולשמואל כו' אידי ואידי לעוה\"ב ל\"ק כאן במחנה שכינה וכאן במחנה צדיקים, הנה ארז\"ל כל אורה האמור באלי' בן ברכאל בירידת הגשמים הכתוב מדבר פי' שהאור מתגשם ויורד למטה והוא בחי' ג\"ר דעתיק (והו\"ע ג' שעות הראשונות הקב\"ה יושב ועוסק בתורה) וזה יאיר בימות המשיח, אבל בעוה\"ב אז וחפרה כו' שיאיר מבחי' אין הנק' שמש בישעי' בסי' הנ\"ל, והוא מ\"ש ובאו במערות כו' מפני פחד הוי' והדר גאונו (ואפ\"ל שיאיר ג\"כ מבחי' עתיק יומין), והנה אי' בזהר הוא דא עתיקא שמאיר בו בחי' עת\"י, ולכן ובושה החמה וחפרה הלבנה, דחמה ולבנה הוא זו\"ן וכשיאיר עליהם מבחי' הנ\"ל לא יאירו עוד, אבל כוכבים הם בינה ובבינה מאיר תמיד מבחי' עתיק כנ\"ל, ע\"כ לא יבושו ולא יחפרו כלל ומכ\"ש לפ\"ד שמואל דבעוה\"ב ג\"כ יהי' אור הלבנה כו' היינו שיאיר מבחי' עתיק וניחא למה לא נא' כוכבים וזהו\"ע מעלת הכוכבים שהם ברקיע תמינאה בינה.\n<b>ועוד</b> אפ\"ל ענין מעלת השמיני דהתחלת התיקון הוא מלך השמיני הדר שהוא ג\"כ שמיני הרי מובן מכל הנ\"ל מעלת השמיני."],[2000460302,"<h3>ואהבת את ה\"א</h3>\n<b></b><b>בס\"ד. ש\"פ ויגש ל\"ט, לפ\"ק.</b>\n<b></b><b>בפ\"א, ובפ\"ב לא שמעתי מא'). </b>\n<b>ואהבת</b> את ה' אלקיך<sup data-n=\"897\">1</sup> בכל לבבך ובכל נפשך ובכל מאדך. וצ\"ל למה מזהיר כ\"כ על אהבה יותר מן שאר כל הדברים, דפעמים מקשים מה שייך ציווי על אהבה<sup data-n=\"898\">2</sup>, ומתרצים שהוא על ההתבוננות. אך למה מצוה ע\"ז יותר מעל שאר הדברים. והנה ואהבת א\"ת כולל יראה וצ\"ל והלא הנשמה מורגלת באהוי\"ר דכתיב חי הוי' אשר עמדתי לפניו, ולמעלה אינו שייך עמידה ע\"פ פשוט אלא שעמדה באהוי\"ר,",[["897","1","<b>ואהבת את ה' אלקיך</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב, והוא התחלה נוספת למאמר שלאח\"ז. והוא הנחה מד\"ה אריב\"ל הנדפס לעיל ע' סו ואילך. להתחלה זו ראה גם לעיל ע' עא [ד\"ה ואהבת].\nבכותרת המאמר נרשם: ”(בפ\"א, ובפ\"ב לא שמעתי מא')\", והכוונה שהמאמר נרשם כאן ע\"פ שמיעתו את המאמר בפעם הא' מאביו כ\"ק אדמו\"ר מהר\"ש, אבל בפעם הב' ”לא שמעתי מאאמו\"ר\" (או: מאדמו\"ר)."],["898","2","<b>דפעמים מקשים שמה שייך ציווי על אהבה</b>: ראה תו\"א תשא פו, ג-ד. הוספות לדרמ\"צ קצט, א. סה\"מ תרכ\"ז ע' עד. וש\"נ. תרל\"ב ח\"א ע' צה. תש\"א ע' 116 ואילך. לעיל ע' עא שם."]]],[2000460303,"ולמה מצווה ע\"ז כל כך, [וגם] בכל לבבך ובכל נפשך וכו'. אך הנה באמת צ\"ל ענין ירידת הנשמה בגוף.\n<b>]המשך</b> המאמר לקמן בסמוך תיבות: וצלה\"ק תחילה ענין ירידת הנשמה בגוף, עד גמירא]."],[2000460304,"<h3>אמר ריב\"ל עתיד הקב\"ה</h3>\n<b>)בפ\"א</b> ההתחלה) אמר ריב\"ל עתיד הקב\"ה<sup data-n=\"899\">1</sup> כו' ש\"י עולמות שנא' כו' וצ\"ל המספר דש\"י. וצלה\"ק תחילה ענין ירידת הנשמה בגוף<sup data-n=\"900\">2</sup> שהיא ירידה עצומה, דהנשמה כמו שהיא למעלה כתי' חי הוי' אשר עמדתי לפניו, ולמעלה אינו שייך עמידה ע\"פ פשוט אלא שעמדה באהוי\"ר וביטול לאלקות, דש' עמידה מורה על ביטול וכמו ויעמידם לעד לעולם פי' שעומדים בביטול, ומלאכים הם מחיצוניות הכלים ונשמות מפנימיות הכלים, הרי עמדה כו', וירדה למטה שצריכה לייגע עד אשר תעורר האהבה, ואף שיעורר האהבה אינו בערך כמו שהי' למעלה [דכתיב אשר עמדתי לפניו] הרי עמדה באהוי\"ר, ולמטה הוא רק בשעת התפלה ואח\"כ חולף ועובר, וניכר שבשעת התפלה הוא ג\"כ שלא כדבעי הרי הירידה ירידה עצומה.\n<b>והענין</b> דהנה כתיב טוב לי תורת פיך<sup data-n=\"901\">3</sup> מאלפי זהב וכסף, אלפי הוא לימוד כמו אאלפך חכמה, וזהב הוא יראה כמ\"ש מצפון זהב יאתה, וכסף הוא אהבה, וטוב לי תורת פיך כו' וצ\"ל למה טוב לי, הלא לתורה צריכים ג\"כ אהוי\"ר דאורייתא בלא דחילו ורחימו לא פרחת לעילא ולמה טוב לי כו'.\n<b>והענין</b> דהנה כתיב ביום חתונתו זו מ\"ת, דכמו חתונה הוא יחוד חתן וכלה כמו\"כ כדי שיהי' יחוד כנס\"י עם הקב\"ה הוא ע\"י התורה, דתלת קשרין מתקשרין דא עם דא, והיחוד הוא יחוד עצמי דמאן דלא נסיב הוא פלג גוף דכתיב זכר ונקבה בראם ויברך אותם ויקרא את שמם אדם, אז דוקא נק' אדם וכתי' אח\"כ ויברך אותם דלית ברכתא שריא אלא באתר שלים ומאן דלא נסיב כו'. וכמו\"כ למעלה נעשה היחוד עצמי לאשתאבא בגופא דמלכא. והענין דהנה אנו רואין בענין ההולדה שהוא בא מהמוח, ושם אינו שייך שיהי' בגשמיות כ\"א הרגש רוחני, ואח\"כ נתגשם ונעשה",[["899","1","<b>אמר ריב\"ל עתיד הקב\"ה</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב, מד\"ה זה שנדפס לעיל ע' סו ואילך. וראה בהנסמן שם לכללות המאמר. וראה לעיל ד\"ה ואהבת שהוא התחלה נוספת למאמר זה."],["900","2","<b>וצלה\"ק תחילה ענין ירידת הנשמה בגוף</b>: בהבא לקמן ראה גם תו\"א נח י, ב. בשלח סב, סע\"ד. ובארוכה בתו\"ח שמות (הוצאת תשס\"ד) קסד, ב ואילך. המשך והחרים תרל\"א ע' כח ואילך. וככה תרל\"ז ע' קפה ואילך. המשך יונתי בסה\"מ תר\"מ. סה\"מ עטר\"ת ע' שע-עא. ועוד."],["901","3","<b>והענין דהנה כתיב טוב לי תורת פיך</b>: ראה תו\"א וישב כו, סע\"ד. תו\"ח וישב נה, א ואילך. אוה\"ת וישב (כרך ב) רנג, ב ואילך. שם (כרך ה) תתפט, ב ואילך."]]],[2000460305,"הולדה שמוליד בדומה, א\"כ מוכרח לומר שהוא מעצמות האב, ועוד זאת דיפה כח הבן מכח האב, ואיך אפשר שיהי' יפה מאחר שאינו אצל האב, אלא שיש כוחות נעלמים<sup data-n=\"902\">4</sup> אצל האב (הג\"ה, משמע שהכחות א\"א להגלות אצל האב כלל, וכן משמע לקמן ד\"ה ואהבת (הב'<sup data-n=\"903\">5</sup>) יעו\"ש) וניתנין להבן, אף שהטפה היא גשמית, ובאמת דוקא מפני שהיא גשמי כו'. וכמו\"כ למעלה ע\"י התורה נתיחד יחוד עצמי לאשתאבא בגופא דמלכא. וזהו טוב לי תורת פיך מאלפי זהב וכסף דאף שהנשמה היתה עומדת באהוי\"ר כו' מ\"מ היתה מופרדת, דמלאכים אף שהם בטלים לאלקות דיש מלאכים מששת ימי בראשית הם עומדים בהביטול דפעם ג' קדוש<sup data-n=\"904\">6</sup> מ\"מ הם מופרדים, וכמו\"כ נשמות דאפי' נשמות דאצי' הם מורחקים<sup data-n=\"905\">7</sup> מהוי', לכן טוב לי תורת פיך כו' שעי\"ז יבוא לאשתאבא בגופא דמלכא. וביאור הענין דהנה כתיב ויקרא לו אל אלקי ישראל ואמרז\"ל אמר יעקב להקב\"ה אתה אלוקה בעליונים ואני אלוקה בתחתונים<sup data-n=\"906\">8</sup>, ונענש ע\"ז, פי' דכתר הוא מושל על חמש ספי' העליונות ות\"ת על חמש ספי' התחתונות<sup data-n=\"907\">9</sup>.",[["902","4","<b>ועוד זאת דיפה כח הבן מכח האב. . שיש כוחות נעלמים</b>: ראה גם סה\"מ תרל\"ב ח\"ב ע' תצה. ועוד."],["903","5","<b>לקמן ד\"ה ואהבת (הב')</b>: נדפס לעיל ע' עא ואילך, אך שם לא נמצא מענין זה, וכנראה נוסף בעת אמירת המאמר ע\"י כ\"ק אדמו\"ר מהר\"ש, ולע\"ע לא הגיע לידינו הנחה מד\"ה ואהבת הב'."],["904","6","<b>דיש מלאכים. . עומדים בהביטול דפעם ג' קדוש</b>: ראה לקו\"ת אמור לב, סע\"ד ואילך."],["905","7","<b>דאפי' נשמות דאצי' הם מורחקים</b>: ראה אגה\"ק ס\"כ (קל, סע\"א). סה\"מ תרל\"ב ח\"א ע' מ. וש\"נ. תרל\"ג ח\"א ע' נב."],["906","8","<b>ואמרז\"ל. . אתה אלקה בעליונים ואני אלקה בתחתונים</b>: ראה סה\"מ תרל\"ב ח\"א ע' לז ואילך. [ובהנסמן שם]. ע' קנט. קצט ואילך. תרל\"ג ח\"א ע' מח ואילך. וש\"נ."],["907","9","<b>התחתונות</b>: ע\"כ נרשם בגוכי\"ק. וראה המשך המאמר לעיל ע' סט ואילך."]]],[2000460306,"<h3>שמע ישראל</h3>\n<b>בס\"ד, ש\"פ וארא ל\"ט.</b>\n<b>שמע</b> ישראל<sup data-n=\"908\">1</sup> ה' אלקינו ה' אחד. הנה רוב המפרשים מקשים למה נא' הוי' אלקינו הוי', והול\"ל הוי' אלקינו שזה מוכרח אל הענין (הג\"ה, דהנה אמרז\"ל כד אמליכתי' למעלה ולמטה וד' רוחות העולם כו', וזהו שאומרים הוי' אלקינו, הוי' הוא בחי' סוכ\"ע (נת' בלקו\"ת בד\"ה ויקרא<sup data-n=\"909\">2</sup> אוא\"ס המלובש בחכ' הוא בחי' סוכ\"ע), ואלקינו הוא בחי' ממכ\"ע, אוא\"ס הסוכ\"ע מאיר בבחי' ממכ\"ע והוא אח\"ד ז' רקיעים וארץ וד' רוחות העולם דמלא כל הארץ כבודו, וכשיתבונן דבמקום שהוא שם אוא\"ס הסוכ\"ע לא יעשה עוד מאחת אשר לא תעשנה וגם יתחרט על העבר וישוב אל ה',",[["908","1","<b>שמע ישראל</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב. והוא הנחה מד\"ה זה הנדפס לעיל ע' עה ואילך. וראה בהנסמן שם לכללות המאמר."],["909","2","<b>נת' בלקו\"ת בד\"ה ויקרא</b>: דף א, א."]]],[2000460307,"עכ\"ה), אבל הוי' אלקינו הוי' זה אינו מוכרח. ועוד צ\"ל דהנה כתיב אח\"כ ואהבת את ה' אלקיך בכל לבבך ובכל נפשך ובכל מאדך והיו הדברים האלה כו' ואמרז\"ל בד\"ת הכתוב מדבר דא\"א לומר זה על ק\"ש, דק\"ש הוא רק פעמים ביום וכאן ע\"פ פשוט (הג\"ה, דהנה אי' במשנה בברכות פ\"א מ\"ג, בש\"א בערב כו' ובבוקר כו' שנא' בשכבך ובקומך ובה\"א כו' אדם כו' שנא' בלכתך בדרך א\"כ למה נא' בשכבך ובקומך בשעה כו', א\"כ קאי הכל על ק\"ש אבל ע\"פ פשוט משמע שמצותה תמיד בשבתך בביתך וגם בלכתך בדרך וגם בשכבך ובקומך א\"כ קאי על תורה, עכ\"ה) הרי אמר בשבתך בביתך ובלכתך בדרך הרי כל היום, וקאי על תורה דכתיב והגית בו יומם ולילה, רק בעלי עסקים פרק א' שחרית פרק א' ערבית, וצ\"ל והלא תחילה אומר בכל מאדך היינו שהוא יוצא מהגבלת הכלי, ואיך אמר והיו כו' בד\"ת כו' שהוא כשר פסול טמא טהור התלבשות אוב\"כ.\n<b>והענין</b> דהנה כתיב טעמה כי טוב סחרה לא יכבה בלילה נרה, ופי' המפרשים ע\"פ פשוט דכשהמסחר טוב גם בלילה אינו שובת מהמסחר, דהנה אמרז\"ל לא אברי לילה אלא לגרסא או לשינתא לפ\"ע כו' וכמ\"ש ויהי להם הלילה למשמר והיום למלאכה, דמסחר הוא ג\"כ מלאכה, אבל כשהמסחר טוב גם בלילה אינו שובת מהמסחר וזהו לא יכבה נרה דלמסחר צריכים נר כ\"ה ע\"פ פשוט. ואפ\"ל פי' הפסוק דהנה אי' במדרש התורה והנפש קרוין נר דכתיב נר הוי' נשמת אדם הרי הנשמה נק' נר, וכתיב כי נר מצוה ותורה אור, והגם שנאמר כאן אור אך הנה מצות לימוד התורה שהיא מ\"ע נכלל בנר מצוה, לכן מביא ע\"ז פסוק זה. וראי' שכאן ג\"כ נרה הוא התורה והנפש דהנה אי' במדרש ע\"פ זה שקאי על בתי' בת פרעה שהיתה בכורה וניצלה ממכת בכורות בזכות דליל כתי' וקאי על ליל שמורים שנצלה, וע\"ז קאמר נרה הרי קאי על הנשמה ומשה<sup data-n=\"910\">3</sup> הוא תורה הרי נרה שכ' קאי על תורה ונפש, ובלילה הנה יש בזה ב' פירושים, א' דלילה קאי על עוה\"ז שהוא חשך והעלם והסתר, הב' שקאי על זמן שאין בהמק\"ד קיים, דבזמן שבהמק\"ד קיים האיר גילוי אלקות דצמצם שכינתו בין ב' בדי ארון, אבל בזמן שאין בהמק\"ד קיים הרי העלם והסתר חשך כפול ומכופל, וזהו לילה, ומ\"מ לא יכבה נרה והוא כמו לילה כיום יאיר. ופי' טוב סחרה הנה אי' בס' דירידת הנשמה בגוף הוא עיסקא<sup data-n=\"911\">4</sup> מסחר, ולכן ההנהגה בהיתר עיסקא אי פלגא ופלגא תלתא באגרא כו', וכמו\"כ אנו מוצאים שנוטל תלתא באגרא דאי' במדרש משל למלך שעשה ג' כתרים שנים נתן בראש בניו ואחד נטל לעצמו, ובהפסד הוא נוטל פלגא דיצחק א' פלגא עלי ופלגא עלך. וזהו טעמה כי טוב סחרה שכשהמסחר טוב אזי גם בלילה לא יכבה נרה.",[["910","3","<b>ומשה</b>: תיבה זו אינה ברורה בגוכי\"ק."],["911","4","<b>אי' בס' דירידת הנשמה בגוף הוא עיסקא</b>: הובא לעיל ע' עו בשם ערכי הכינויים של בעל הסדר הדורות (ערך הלואה). וראה בכ\"ז אוה\"ת משפטים ע' א'קע. שם (כרך ח) ע' ג'ל. סה\"מ תרכ\"ו ע' פ-פא. תרכ\"ט ע' עד-ה. קפה-ו. ס' תורת שמואל דרושי חתונה ע' קלב. לקו\"ש ח\"ג ע' 1010 ואילך."]]],[2000460308,"<b>וענין</b> המסחר הנה נת\"ל בד\"ה אריב\"ל ובד\"ה ואהבת<sup data-n=\"912\">5</sup> מ\"ש טוב לי תורת פיך מאלפי זהב וכסף הוא אהוי\"ר, דהנה הנשמה כמו שהיא למעלה היתה עומדת באהוי\"ר וביטול לאלקות ונת' שם דאינו שייך עמידה בלא ביטול, וירדה למטה בגוף ונה\"ב המעלים ומסתיר, וצריכה הרבה יגיעה עד שתבא לבחי' אהוי\"ר ואף זאת לא כמו שהי' מקודם, וא\"כ הלא ירידה עצומה, אך טוב לי תורת פיך והוא בחי' ואנשי קדש תהיון לי, ובד\"ה ואהבת נת' שהוא בחי' תשובה<sup data-n=\"913\">6</sup>, דהנשמה כמו שהיא למעלה לא הי' לה רק אהוי\"ר דזהו לפי השגת הנפש והוא לאחר התלבשות הנשמה בגוף הוא ביטול דכל לבבך וכל נפשך, בכל לבבך הוא ויפול דער לב קען פאר נעמען, ובכל נפשך הוא בכל כחות הנפש, וכמו\"כ קודם התלבשות הנשמה הוא לפי השגת הנשמה אבל אחר שמתלבשת בגוף תבוא לתשובה (הג\"ה, דתשובה אינו דוקא על חטא אלא תשובה הוא והרוח תשוב<sup data-n=\"914\">7</sup> אל האלקים ושייך גם בצדיקים גמורים וכמ\"ש משיחא אתי לאתבא צדיקייא בתיובתא, וצדיק הוא מי שמקיים תומ\"צ ע' מזה במאמר של ר\"ה ד\"ה וכל מאמינים<sup data-n=\"915\">8</sup> שהוא שופט צדק עכ\"ה) רעו\"ד שיוצא (הג\"ה, דאף שקודם התלבשותה בגוף היתה מוגבלת, אך לא היתה יכולה לצאת מהגבלתה דלזה צריכים תשובה, וזה לא הי' לה קודם התלבשותה בגוף כ\"א אחר התלבשותה בגוף אז יכולה לצאת מהגבלתה, דביטול בכל מאדך שהו\"ע תשובה רעו\"ד כנ\"ל זהו מצד כח המנגד, וכמו המלחמה שהוא מלא רציחה ברתיחות הדמים והורג את חבירו שזהו מצד מנגדו שרוצה להרוג אותו וצר לו מאד לכן נתמלא רציחה ורתיחות הדמים והורג אותו, כמו\"כ כאן ג\"כ לאחר שנתלבש הנשמה בגוף ונה\"ב שמעלים ומסתיר ומסית ומדיח עי\"ז דוקא יוצא מהגבלת הכלי, ולכן אמרז\"ל טוב מאד זה מלאך המות ע' מזה בפי' המלות (של אדמו\"ר האמצעי זצללה\"ה) בפ' איש בער<sup data-n=\"916\">9</sup> כו' באריכות עכ\"ה) מהגבלת הכלי, וזהו הריוח שמרויח, וה\"ז כמו סוחר שמפזר כסף וזהב הרבה מפני שמרויח אח\"כ, כמו\"כ מפזר האהוי\"ר מפני שיכול לבוא לבחי' רעו\"ד.\n<b>וע\"י</b> מה יבוא לבחי' זו, הוא ע\"י התבוננות כשיתבונן דאני ראשון ואני אחרון ומבלעדי אלקים, אני ראשון הוא קודם שנברה\"ע ואני אחרון הוא לאחר עלי' דנו\"ן אלפים יובלות דיש (הג\"ה כמדומה לי שאמר דעכשיו הוא שבוע, ולא זכיתי להבין דבריו הקדושים והטהורים, דזה לא נמצא דעכשיו הוא שבוע, דבת\"א פ' שמות ד\"ה ויאמר כו' מי שם פה<sup data-n=\"917\">10</sup> הביא שבס' התמונה אי' דעכשיו הוא שמטה שני'",[["912","5","<b>נת\"ל בד\"ה אריב\"ל ובד\"ה ואהבת</b>: לעיל ע' סו ואילך. וע' עא ואילך. וראה גם לעיל בהנחה מד\"ה אריב\"ל."],["913","6","<b>ובד\"ה ואהבת נת' שהוא בחי' תשובה</b>: לעיל ע' עג-ד."],["914","7","<b>דתשובה אינו דוקא על חטא אלא. . והרוח תשוב</b>: ראה לקו\"ת דרושים לר\"ה ס, ד. וראה גם לקו\"ת בלק עד, א. האזינו עא, א. לעיל ע' עד. ועוד."],["915","8","<b>ע' מזה במאמר של ר\"ה ד\"ה וכל מאמינים</b>: מאמר דר\"ה תרל\"ט נדפס בסה\"מ תרל\"ח ע' שיח ואילך. שם ע' תקד ואילך."],["916","9","<b>ע' מזה בפי' המלות. . בפ' איש בער</b>: דף פג, ג ואילך."],["917","10","<b>דבת\"א פ' שמות ד\"ה. . מי שם פה</b>: דף נא, ד."]]],[2000460309,"ולזה הסכים גם האריז\"ל, אבל לא שבוע, ועוד יש להבין בזה, ואין להאריך בדברים אלו עכ\"ה) שבוע, שנה, שמיטה, יובל, נו\"ן אלפים יובלות, ולאחר עלי' דנו\"ן אלפים יובלות זהו אני אחרון, ומבלעדי באמצעיתא אין אלקים, דאני הוי' לא שניתי שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנברה\"ע ואתה הוא לאחר שנברה\"ע, דכללות השתל' העולמות הוא רק שם והארה בעלמא שאינו נוגע לעצמות וא\"כ אינו שייך בו שום שינוי. וזהו שמע ישראל ה' אלקינו ה' ולכאורה קשה למה הג' שמות אלו, והנה אי' ברוקח דג' שמות אלו הם אני ראשון ואני אחרון<sup data-n=\"918\">11</sup> ומבלעדי אין אלקים, והנה אני ראשון הוא כמ\"ש בפרדר\"א שעד שלא נברא העולם הי' הוא ושמו בלבד, ובעבוה\"ק אי' עד שלא נאצל אצי' העליון<sup data-n=\"919\">12</sup> הי' הוא ושמו בלבד, דהנה הוי' שם העצם והוא שמו הגדול ואמר שעד שלא נבה\"ע כו' הוא שמו העצמי שאינו מקור אפי' על השתל' עולמות הא\"ס וזהו שמוסיף העבוה\"ק, ואני אחרון הוא מ\"ש ונשגב הוי' לבדו ביום ההוא וקאי ג\"כ על שמו העצמי דלאחר עלי' דנו\"ן אלפים יובלות יאיר בחי' זו, דענין נו\"ן אלפים יובלות אינם במספר, אלא מספר הוא מל', וז\"א הוא מקור המספר, ומה שסדר זמנים קודם לכן הוא מספר גדול בחי' א\"א<sup data-n=\"920\">13</sup>, ולאחר עלי' דנו\"ן כו' ויהי' ביטול העולמות אז יאיר בחי' גבוה מאד שאינו רשאין עתה לדבר בו, ומבלעדי באמצעיתא אין אלקים, אין הפי' שאין אלקים כלל, א\"כ איך הי' בריאת העולמות ויש הרבה ראיות ע\"ז, אלא הפי' אלקים דכדי שיהי' גילוי מוכרח להיות צמצום וזהו אין אלקים שההסתר אינו מצד שם אלקים דההסתר הוא ג\"כ מצד שם הוי' וההסתר בשרשו למעלה יותר מהגילוי, דכתי' וחכיתי להוי' המסתיר<sup data-n=\"921\">14</sup>, כתי' המסתיר, וכתי' אצל שם הוי' שיש הוי' הנראה שהוא בחי' יאר הוי' פניו אליך, והוי' המסתיר שרשו למעלה יותר דכתי' אנכי הסתר אסתיר פני ביום ההוא, הנה הסתר אסתיר הוא לעילא ולעילא, וההסתר הוא מהיום ההוא [ושרש ההסתר הוא מבחי' אנכי מי שאנכי], וכמו\"כ כאן וחכיתי להוי' המסתיר הוא ג\"כ מצד בחי' זו, וההסתר הוא כדי שיהי' ובקשתם משם שית\"ל אי\"ה, וסדר ההסתר צ\"ל ע\"י שם אלקים דהוי' ואלקים כולא חד וכדי שיהי' הסתר זהו מצד שם אלקים, וזהו אין אלקים דאלקים בגימ' הטבע שהשמש זורח במזרח ושוקע במערב, וטבע אין פירושו כמו שמפרשים החוקרים דאי' בתשו' ח\"צ שגם טבע הוא נסים תכופים<sup data-n=\"922\">15</sup>, אלא שלעיננו נראה שהוא הסתר, ובאמת הוא למעלה יותר דכתר עליון אע\"ג דאיהו אור צח אור",[["918","11","<b>אי' ברוקח דג' שמות אלו הם אני ראשון ואני אחרון</b>: הובא ונת' בסה\"מ תרכ\"ז ע' שה ואילך. וש\"נ. תרכ\"ט ע' רעו ואילך. וש\"נ."],["919","12","<b>ובעבוה\"ק אי' עד שלא נאצל אצי' העליון</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' קכז. סה\"מ תרמ\"ג-ד (הוצאת תשס\"ג) ע' שמו ואילך [ובהמובא בהמ\"מ שם]."],["920","13","<b>ומה שסדר זמנים. . מספר גדול בחי' א\"א</b>: ראה גם שע\"ת לאדהאמ\"צ כט, ב ואילך. קמה, א ואילך. וראה בארוכה אודות סדר זמנים לקמן ח\"ב ד\"ה מי זאת הנשקפה. וש\"נ."],["921","14","<b>וההסתר בשרשו למעלה יותר מהגילוי דכתי' וחכיתי להוי' המסתיר</b>: בהבא לקמן ראה גם סה\"מ תרכ\"ו ע' רו. תרכ\"ז ע' שפה. תרכ\"ט ע' קסג. וש\"נ. תרל\"ב ח\"א ע' רעו. ח\"ב ע' תקפז. וע' תר."],["922","15","<b>דאי' בתשו' ח\"צ שגם טבע הוא נסים תכופים</b>: ראה בארוכה לקמן ח\"ב ד\"ה מזמור לתודה. וש\"נ."]]],[2000460310,"מצוחצח אוכם הוא קדם עה\"ע חשך ושחרות שאינו שייך בו השגה, אע\"ג שהם מדריגות גבוהות אור קדמון אור צח אור מצוחצח הוא ג' ראשי ראשין מ\"מ הוא חשך מפני שאין בו השגה. ושרש ההסתר ולמה הוא ההסתר שיבקשו בחי' זו וימצאו אנכי, [וה\"ז כמו שמסתיר א\"ע מהבן והוא כדי שיבקש אותו הבן, דכשהוא עמו תמיד אין האהבה כ\"כ, לכן הוא מסתיר א\"ע ממנו ואין העיקר ההסתר אלא כדי שיבקשו הבן], ועי\"ז יהי' גדולים מעשה צדיקים ממעשה שמים וארץ, דמעשה צדיקים הם מיש לאין. והנה כדי שיהי' מיש לאין צ\"ל תחילה מאין ליש והוא ד\"ת שהוא ג\"כ אמת, אך ד\"ע שכולא קמי' כלא חשיב, וקמי' הוא למעלה גם מבחי' ד\"ע, וזהו גדולים מעשה צדיקים שהו\"ע ביטול היש לאין והוא בחי' מספר גדול, וזהו\"ע רעו\"ד ביטול."],[2000460311,"<h3>להבין כו' שחותמים בברכת אירוסין</h3>\n<b>בס\"ד. ח' ב\"א תי'.</b>\n<b>להבין</b> ענין מה שחותמים בברכת אירוסין מקדש עמו ישראל ע\"י חופה וקדושין<sup data-n=\"923\">1</sup>, לכאו' מה\"ע בחי' חופה לברכת אירוסין, הלא חופה היא הקדמת נשואין וכמו שהקשה הרא\"ש ז\"ל<sup data-n=\"924\">2</sup> אשר לאירוסין לא היו עושין חופה כלל. ויש ע\"ז כמה תירוצים ומהם אשר מזכירי' בברכת אירוסין ענין החופה להזכיר לנשואין שצריכים לעשות חופה.\n<b>והענין</b> הוא דהנה כתי' כי על כל כבוד חופה ונודע כי יש ב' בחי' כבוד, כבוד נברא וכבוד נאצל כמ\"ש הרמב\"ן ז\"ל וכמ\"ש מזה בסידור ובלק\"ת<sup data-n=\"925\">3</sup>, שעל ב' בחי' כבוד אלו יש בחי' חופה ומקיף דוקא. והענין שבכדי שיומשך בחי' היחוד בפנימי' צ\"ל תחלה בחי' מקיף דוקא, ואז יומשך ההמשכה בפנימיות, וכמו שע\"י ענין",[["923","1","<b>להבין ענין מה שחותמים. . ע\"י חופה וקדושין</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב. והוא כנראה הנחה מד\"ה צאינה וראינה הנדפס לעיל ע' פה ואילך. ונמצא תוכנו בשינויים בד\"ה ואהבת לעיל ע' עב ואילך.\nמאמר זה נכרך בכרך הכת\"י של ס' תרל\"ט בוך גוכי\"ק כ\"ק אדמו\"ר מהר\"ש [מס. 1069 עה, א], שלא כמו שאר הנחות כ\"ק אדמו\"ר מוהרש\"ב שנכרכו בפ\"ע.\nבכותרת המאמר נרשם בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב: ”ח' ב\"א תי'\" ר\"ל חתונה בת-אחותו (או: בת-אחיו) תחי'. ולע\"ע לא נתברר למי הכוונה."],["924","2","<b>מה\"ע בחי' חופה לברכת אירוסין. . וכמו שהקשה הרא\"ש ז\"ל</b>: ראה גם תו\"א מג\"א צח, סע\"ד. סד\"ה והוא כחתן בסה\"מ תרנ\"ז ס\"ע קעא-ב. ושם מציין ע\"ז כ\"ק אדמו\"ר זי\"ע: הרא\"ש ז\"ל לכתובות (ז, ב). וראה גם טושו\"ע ונו\"כ אה\"ע סל\"ד."],["925","3","<b>כי על כל כבוד חופה. . ב' בחי' כבוד. . וכמ\"ש מזה בסידור ובלק\"ת</b>: סידור עם דא\"ח קכח, ד ואילך. לקו\"ת שה\"ש מז, ב ואילך. ובארוכה מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' א ואילך. וש\"נ."]]],[2000460312,"הקטורת דיוהכ\"פ נעשה אח\"כ מקיפי' דחה\"ס ואז אח\"כ נמשך בשמע\"צ בחי' היחוד בפנימיות שיוקלט ההמשכה בנש\"י, והיינו בחי' המשכת הדעת שנמשך ע\"י ד' מינים שבלולב.\n<b>וכן</b> יובן בענין ביום חתונתו דמ\"ת שהוא בחי' יחוד עליון דנש\"י עם בחי' האלקות, כמ\"ש במ\"א שהתורה היא בחי' טיפת אבא להוליד בדומה לו<sup data-n=\"926\">4</sup>, שיומשך בחי' ביטול החכ' שנק' אבא בנש\"י להיות בדומה לו, היינו להיות בחי' כי עם קדוש אתה לה' אלקיך שזהו ע\"י בחי' אשר קדשנו במצותיו כו', שע\"י וציוונו ל' צוותא וחיבור לו ית' כבי' להיות בדומה לו.\n<b>ולכן</b> עתידי' צדיקים המקיימי' תומ\"צ שיאמרו המלאכים לפניהם קדוש כדרך שאומרי' לפני הקב\"ה, והיינו כי עכשיו ההמשכה היא מלמעלמ\"ט, והמלאכי' שהם נבראי' שכלים נבדלים<sup data-n=\"927\">5</sup> אומרי' קדוש, היינו שמשיגי' איך שהוא ית' קדוש ומובדל מגדר בחי' ההמשכה בעולמות, והגם כי ממך הכל, עכ\"ז הנה אני ה' לא שניתי כלל, ואתה הוא קודם שנבה\"ע ואתה הוא כו', כי כלליות השתלשלות העולמות הם מבחי' זיו והארה שאינו נוגע לו כלל, כי בי\"ה הוי' צור עולמי' ביו\"ד נברא העוה\"ב ובה' העוה\"ז אתא קלילא כו', והיו\"ד צמצום נקודה, שהצמצום הוא בכדי שיוכל להיות בחי' העוה\"ב כי אינו תופס מקום כלל, כי באמת לאו מכל אלין מדות איהו כלל, ולית מח' תפיסא בי', שאפי' בחי' מחשבה דמחשבה ויובלא כו' ג\"כ אינה תפיסא בי' כלל. רק מפני כי ה' חפץ למען צדקו, פי' צדקה זו הוא כמ\"ש כל מצוותיך צדק, שבאמת זהו צדקה אצלו כי מאי איכפת לי' אם שוחט מן העורף או שוחט מן הצואר, אלא שזהו בדרך צדקה לבד, ובכדי שיצא לפועל צדקה זו לכן נמשך תחילה בחי' הצמצום מה שעלה ברצונו הפשוט רצון דאנא אמלוך שנז' בתחלת הע\"ח, שע\"י בחי' חפץ חסד זה נברא ונוצר ונעשה כל מעשה בראשית, ותנאי התנה עם מעשה בראשית אם יקיימו ישראל תורתי כו' ובא\"ל אחזיר כו', וכמ\"ש עשרה עשרה הכף בשקל הקדש, שעה\"ד מכוונים נגד ע\"מ<sup data-n=\"928\">6</sup> כנ\"ל, וכמארז\"ל אלה בזכות מי נבראו ובזכות מי עומדין בזכות אלה שמות כו' אלה העדות כו'. והיינו שע\"י אלה העדות כו' נמשך בחי' הצדקה דכל מצותיך צדק, שעי\"ז יומשך בחי' חפץ ה' בבחי' פנימיות באופן היותר נעלה מכמו ההמשכה שנמשך לצורך ברה\"ע בתחלת הבריאה מבחי' כי חפץ חסד הוא, כי הבריאה היא יש מאין כו' משא\"כ תומ\"צ הם המשכת טיפת אבא להוליד בדומה לו כבי' כנ\"ל להיות עם קדוש כו' בחי' ואנשי קדש תהיון לי. ואי לזאת לעת\"ל עתידי' המלאכי' שיאמרו לפני הצדיקי' קדוש, כי יהי' ההמשכה מלמטלמ\"ע פי' שבחי' המטה תתעלה להיות בחי'",[["926","4","<b>כמ\"ש במ\"א שהתורה היא בחי' טיפת אבא להוליד בדומה לו</b>: ביאוה\"ז לאדהאמ\"צ ב, א ואילך. ולהצ\"צ ח\"ב ע' תריב ואילך."],["927","5","<b>והמלאכי'. . שכלים נבדלים</b>: ראה גם לקו\"ת שלח מו, רע\"א. ועוד."],["928","6","<b>וכמ\"ש עשרה עשרה הכף שעשה\"ד מכוונים נגד ע\"מ</b>: ראה בארוכה לקמן ח\"ב ד\"ה וידבר גו' בהעלותך ס\"ט. וש\"נ."]]],[2000460313,"מעלה כו', ובחי' מ\"ח יוצא מירושלי' אל בחי' הים הקדמוני, פי' ים הוא חכ', הקדמוני כתר, והיינו חכ' שבא\"א בחי' חכ' שבכתר כו', ולע\"ל יצא מ\"ח מבחי' כבוד נברא דוקא אל בחי' הים דחכ' שבכתר דא\"א, והיינו מפני שבגמר הבירורי' יומשך בחי' פנימיות הרצון שארז\"ל נתאוה הקב\"ה להיות לו דירה בתחתוני' דוקא, וכמארז\"ל שוקיו זה העולם, עמודי שש שנברא לששת ימי', שנשתוקק הקב\"ה לבראותו, והיינו בשביל שיצא מכח אל הפועל ענין בחי' דירה בתחתוני' הנ\"ל ע\"י עבודת האדם דוקא כו'.\n<b>ובחי'</b> זו נק' יחוד עליון, שיחוד היא בחי' המשכה פנימיות להוליד בדומה לו, והוא שע\"י העבודה יהי' בדומה לו ממש כבי', שכשם שעתה אומרי' קדוש בשביל הביטול שבטלי' מלמטלמ\"ע, עד שהשרפי' עומדי' ממעל לו היינו לש' אד' בחי' אנת אשתמודעא אדון על כולא, כן יהי' בדומה לו שהמשכה כזו תהי' מלמטלמ\"ע כו' ע\"י תומ\"צ שעי\"ז נק' צדיקי'. ולכן גדולים מעשה צדיקים ע\"ד כבי' יפה כח הבן, והגם שג\"ז מכח האב הוא, עכ\"ז בגילוי נק' כח הבן כו'.\n<b>וכדי</b> להיות יחוד זה צ\"ל חופה תחילה, מקיף דתשובה בכל מאדך. ויש לפרש על צדיקי' ובע\"ת, דבע\"ת ז\"ע לוחות אחרונות שכלליותם הוא בחי' תשובה, שהרי בלוחות ראשונות לבד היו צדיקי' גמורי'<sup data-n=\"929\">7</sup>, משא\"כ בשניים הם בחי' בע\"ת, וכן י\"ל ע\"י בחי' והרוח תשוב שהיא בחי' העלי' שאחר הירידה כו', ובחי' בע\"ת גמורי' הוא כפשוטו. ועוי\"ל בענין בע\"ת דצדיקי' שזהו מה שמשיח אתא לאתבא צדיקי' בתיובתא. ועכ\"פ על כל כבוד אפי' כבוד נאצל א\"א להיות כ\"א ע\"י חופה, וזהו מקדש שיומשך בחי' קדש ע\"י הקדמת החופה הוא בחי' מקיף התשובה, ואז יוקדשו ישראל בקדש העליון כנ\"ל.\n<b>ואמנם</b> עדיין צ\"ל הלא הנהוג הי' אצלם שהי' הקדושין בעת האירוסין, ולפי מה שנת\"ל צ\"ל חופה מקודם, וא\"כ א\"צ לתירוץ שמה שאומרים חופה בברכת אירוסין זהו רק להזכיר איסור הנשואין בלא חופה, הלא גם לקדושין צ\"ל חופה כנ\"ל.\n<b>אך</b> הענין הוא שיש ב' בחי', אירוסין ונשואין<sup data-n=\"930\">8</sup>, אירוסין הוא בחי' לבושי' שלובש טבעת קדושין להכלה, שזהו בחי' מקיף עדיין, וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה<sup data-n=\"931\">9</sup>, משא\"כ נשואין הוא בחי' יחוד פנימי, ועיקר החופה הוא בשביל יחוד פנימי דוקא כנ\"ל, כי לבחי' אירוסין שהוא מקיף א\"צ לחופה, רק שנק' בשם קדושין ע\"ש",[["929","7","<b>דבע\"ת ז\"ע לוחות אחרונות. . בלוחות ראשונות. . צדיקים גמורי'</b>: ראה סה\"מ תרל\"ב ח\"א ע' רמח. ובארוכה ד\"ה ביום השמע\"צ תרל\"ב בסוף סה\"מ תרל\"א. סה\"מ מלוקט ח\"א ע' שסא ואילך. וש\"נ."],["930","8","<b>שיש ב' בחי' אירוסין ונשואין</b>: ראה תו\"א ויגש מד, ד. לקו\"ת בחוקתי נ, א. במדבר טז, ג. שה\"ש ג, ב. ועוד."],["931","9","<b>וכמ\"ש מזה בלק\"ת בד\"ה תורה צוה</b>: פ' ברכה צד, ג. צה, סע\"ד ואילך."]]],[2000460314,"שאומר לה הרי את מקודשת, פי' מזומנת, והזמנה מילתא שאוסרה על כל העולם, והיינו ע\"י שקדשה לו לעצמו, שאם היות שזהו ג\"כ מלשון קדש כמו אנשי קדש, אמנם באמת אינו, וזה השתוות רק למה שתהיון לי כמו מקודשת לי, אמנם ענין הולדה בדומה לו זהו ע\"י היחוד דוקא שזהו ע\"י הקדמת החופה דוקא.\n<b></b><b>]לד\"ה לה\"ע מה שחותמים בברכת אירוסין] </b>\n<b>הסבר</b> על הנ\"ל<sup data-n=\"932\">10</sup>, י\"ל מן מ\"ש באוה\"ח בענין ק\"ש ה' אחד, והתבוננות מן תאוות המשפיע אל המקבל, כמ\"ש בד\"ה וספרתם<sup data-n=\"933\">11</sup>.\n<b>וילה\"ק</b> ענין שלפעמי' נק' תורה כלה, ונש\"י חתן מאורסה, ופעם נק' הקב\"ה חתן ביום חתונתו כו', והענין ביום חתונתו ז\"ע השפעת הטפה מבחי' חתן דמ' שלמה כבוד נברא, ונש\"י דבי\"ע נק' כלה, והתו' שנתלבשה בבי\"ע ז\"ע הטיפה, ומה שנק' התו' כלה זהו ע\"י העבודה בעוה\"ז שע\"י התפילה ולכי לך לשרשך הקדום במח' הקדומה, עי\"ז משפיעי' בתורה בחי' כבוד נאצל והוא ע\"י אמצעית החופה כנ\"ל.",[["932","10","<b>הסבר על הנ\"ל</b>: הוא תוס' ביאור על המאמר שלפנ\"ז, ונמצא בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב לאחר המאמר שלפנ\"ז."],["933","11","<b>מ\"ש באוה\"ח בענין ק\"ש ה' אחד. . וההתבוננות. . כמ\"ש בד\"ה וספרתם</b>: סה\"מ תר\"ל ע' שנג ואילך. [וראה שם ע' שנד: אי' באוה\"ח על התורה ע\"פ ואהבת כו' בכל לבבך וארז\"ל בכל לבבך בשני יצריך, ומובן מדבריו שהפי' שמאהבת ותאוות היצר יכולים להבין איך שצריך לאהוב את הקב\"ה]."]]],[2000460315,"<h3>דרש רבי שמלאי תרי\"ג מצות</h3>\n<b></b><b>בס\"ד, ש\"פ בשלח, יום א' מש'.</b>\n<b>דרש</b> ר' שמלאי<sup data-n=\"934\">1</sup> תרי\"ג מצות נאמרו למשה מסיני רמ\"ח מ\"ע ושס\"ה מל\"ת כו', בא דוד והעמידן על י\"א הולך תמים ופועל צדק לא עשה לרעהו רעה וחרפה לא נשא על קרובו כו' כספו לא נתן בנשך כו', ובא ישעיה והעמידן על שש כו', בא חבקוק והעמידן על אחת צדיק באמונתו יחי'. ופירש\"י בא דוד כו' מפני שנתמעטו הדורות וא\"א לקיים התרי\"ג מצות, דדורות הראשונים הי' באפשרם לקיים תרי\"ג",[["934","1","<b>דרש ר' שמלאי</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב, בגוכי\"ק נרשם רק חלקו הראשון של המאמר, המאמר נמצא בשלימות לקמן בחלק ההנחות מרשימת א' מהשומעים, וראה בהנסמן שם לכללות המאמר.\nבכותרת המאמר נרשם: בס\"ד. ש\"פ בשלח, יום א' מש'. ור\"ל שמאמר זה נאמר ב' פעמים: בש\"פ בשלח וביום א' פ' משפטים."]]],[2000460316,"מצות, אבל בדורות אחרונים כו', לכן בא דוד והעמידן כו', בא ישעיה כו' שנתמעטו עוד כו', עד שבא חבקוק כו'. וצ\"ל הלא תורה היא נצחיות ואם נאמרו תרי\"ג מצות צריכין לקיים כולם רמ\"ח מ\"ע, רק שיש מצות שא\"א לקיים עכשיו שהם תלוים בארץ וכהן ולוי, אבל הפ\"ז מצות צריכין לקיים<sup data-n=\"935\">2</sup> כולם, ושס\"ה מל\"ת כמעט כולם, ואין להוסיף ולא לגרוע ח\"ו אות אחת בתורה, וגם נביא אינו רשאי לחדש בתורה כלום, ואיך העמידן על י\"א כו'. והענין דהנה הי\"א הם כללים כדי שיוכלו לקיים התרי\"ג מצות<sup data-n=\"936\">3</sup>, דבדורות הראשונים לא היו צריכים לכללים, אבל משנתמעטו [הדורות צריכי'] לענין הכללים.\n<b>הנה</b> צ\"ל פ' אליעזר עבד אברהם שיש כמה אריכות בתורה, איך שאברהם התנה עמו והסימן שלו ואח\"כ הסיפור, ואי' במדרש יפה שיחתן של עבדי בתי אבות מתורתן של בנים דגופי תורה נאמרו ברמיזה, כמו דם השרץ שאינו כבשרו הוא מדכתיב וזה לכם הטמא, והי' די שיכתוב זה מזה לומדים כו', הרי גופי תורה נאמרו ברמיזה, ובשיחתן של עבדי כו' מאריך לכן יפה כו', והנה צ\"ל למה יפה כו'.\n<b>הענין</b> הוא דהנה על ג' דברים העולם עומד על תורה ועבודה וגמ\"ח, וג' אבות הם דוגמת הג' עמודים, דג' עמודים נאמרו לאחר מ\"ת, והאבות קיימו תורה ברוחניות, ומעשה אבות סימן לבנים הם נגד הג' עמודים, אברהם נגד עמוד דגמ\"ח דכתיב ויטע אשל בבאר שבע ויקרא שם בשם ה' אל עולם, אשל חד א' פונדק וחד א' פרדס, ור\"ת דאשל הוא אכילה שתי' לוי', שהי' מאכיל לכ\"א ולא הי' מדקדק כו', שהי' מאכיל ומשקה גם לערבים, וזהו השפעה בגשמיות, וגם ברוחניות שאחר אכילה א' ברכו למי שאכלתם משלו והי' משגר שם שמים בפי כל, שהי' מודיע אלקות בעולם, וזהו חסד דכל השפעה הוא חסד, דהשפעת גשמיים הוא חסד, וגם השפעות שלמעלה הוא חסד. וזהו שכ' באאע\"ה שהי' נדיב בין בנפשו בין בגופו בין בממונו<sup data-n=\"937\">4</sup>, בממונו פשוט, ובגופו שהי' משתדל להגדיל ש\"ש<sup data-n=\"938\">5</sup>, ובנפשו בכל כחות נפשו להשפיע אלקות, וכל כך הי' משפיע חסד עד שהחליף מקום כו' כדאי' בפרד\"ס בשם ס' הבהיר אמרה מדת החסד לפני הקב\"ה כל ימי היות אברם בארץ לא הוצרכתי אני",[["935","2","<b>שיש מצות שא\"א לקיים עכשיו. . אבל הפ\"ז מצות צריכין לקיים</b>: כ\"ה גם בס' מאמרי אדהאמ\"צ קונטרסים ע' רסו: פ\"ז מצות שנשארו מרמ\"ח כי קס\"א נתבטלו. עיי\"ש. ועד\"ז בסה\"מ תרכ\"ז ע' שעט. המשך וככה תרל\"ז פנ\"ג (ע' עח). וראה בהנסמן ע\"ז בסה\"מ תרכ\"ז שם. ובס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רעט."],["936","3","<b>והענין דהנה הי\"א הם כללים כדי שיוכלו לקיים התרי\"ג המצות</b>: ראה גם סה\"מ תרכ\"ז ע' טז-יז. תרל\"ד ע' מח. פר\"ת ע' קלג. תרפ\"ו ס\"ע קב-ג. תש\"ח ע' 240."],["937","4","<b>שכ' באאע\"ה שהי' נדיב בין בנפשו. . בגופו. ֿ. בממונו</b>: לקמן בהנחת השומעים הובא זה בשם ס' אורחות צדיקים. הובא גם באוה\"ת וירא צ, ב. סה\"מ תרכ\"ז ע' קצט. תרפ\"ט ע' 90. תרח\"צ ע' קכט ואילך. ועוד."],["938","5","<b>להגדיל ש\"ש</b>: להגדיל שם שמים."]]],[2000460317,"לעשות מלאכתי שהרי אברם עומד ומשמש במקומי, ויעקב הי' נגד תורה דכתי' ויקם עדות ביעקב ותורה שם בישראל, ויצחק נגד עמוד העבודה, דעבודה הוא קרבנות וכתיב לעבדו בכל לבבכם איזה עבודה שבלב זו תפלה דתפלה נגד תמידין תקנו. וזהו שאברם שלח את אליעזר להביא את רבקה שהו\"ע קרבן שהם קיימו תורה ע\"י עובדות. והנה צ\"ל תחילה ענין הקרבן, הנה ע\"י שמעלה בהמה ע\"ג מזבח נכלל באש של מעלה ועי\"ז נמשך ריח נחוח, וצ\"ל למה נמשך עי\"ז ריח נחוח. הענין דהנה אמרז\"ל ג' שותפין באדם והעיקר חלק הקב\"ה<sup data-n=\"939\">6</sup>.",[["939","6","<b>והעיקר חלק הקב\"ה</b>: ע\"כ נרשם בגוכי\"ק. וראה המשך המאמר לקמן בהנחת השומעים מהמאמר."]]],[2000460318,"<h3>ואל משה אמר עלה</h3>\n<b></b><b>ש\"פ משפטים ל\"ט, לפ\"ק.</b>\n<b>ואל</b> משה אמר עלה אל הוי'<sup data-n=\"940\">1</sup> כו' ונגש משה לבדו, הנה אמחז\"ל כשעלה משה למרום אמרו מלאכי השרת מה לילוד אשה בינינו א\"ל הקב\"ה לקבל תורה, אמרו אשר תנה הודך על השמים, והתחילו לקטרג מה אנוש כי תזכרנו ובן אדם כי תפקדנו, אמר הקב\"ה למשה שיטעון עמהם, א\"ל כלום יצה\"ר יש בכם, הודו לו ואמרו ה' אדוננו מה אדיר שמך בכל הארץ ולא אמרו אשר תנה כו'. וצ\"ל והלא מצינו תורה למעלה בלא יצה\"ר כמאחז\"ל קא מיפלגי במתיבתא דרקיע זה אומר כו' וזה אומר כו' מאן נוכח כו' וה\"ז בלא יצה\"ר כו', וכן מ\"ש היושבת בגנים חברים מקשיבים לקולך השמיעני שמלאכים שומעין כמו שלומדים נשמות תורה בג\"ע ה\"ז בלא יצה\"ר.",[["940","1","<b>ואל משה אמר עלה אל הוי'</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב, בגוכי\"ק נרשם רק התחלת המאמר. וראה עוד ע\"פ זה בד\"ה זה באוה\"ת משפטים (כרך ח) ע' ג'מא ואילך.\nברשימת מאמרי אדמו\"ר מהר\"ש משנת תרל\"ט (נדפסה לעיל במפתח המאמרים) מביא כ\"ק אדמו\"ר זי\"ע מאמר זה ותוכנו: ואל משה אמר עלה כו' יתרון לחכמה מן הסכלות כו' וישב שלמה על כסא ה' כו' שית ושביעאה עלייהו. מאמר זה בשלימותו לא הגיע לידינו לע\"ע. אך לקמן בהוספות נדפס ד\"ה אריב\"ל כשעלה משה שהוא כנראה מהדו\"ק ממאמר זה, והוא מיוסד על ד\"ה זה בס' מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קיח ואילך. וראה לקמן בהמאמר שלאח\"ז ד\"ה וראיתי אני שהוא בהמשך למאמר זה. [וראה ד\"ה וראיתי אני בס' מאמרי אדהצ\"צ שם ע' קכט שהוא ג\"כ בהמשך לד\"ה כשעלה משה למרום הנ\"ל]."]]],[2000460319,"<h3>וראיתי אני שיש יתרון</h3>\n<b></b><b>בס\"ד. ש\"פ תרומה ט\"ל, לפ\"ק.</b>\n<b>וראיתי</b> אני<sup data-n=\"941\">1</sup> שיש יתרון לחכמה מן הסכלות כיתרון האור מן החושך, ואי' במדרש תנא בשם ר\"מ כשם שיש יתרון לאור על החושך כן יש יתרון לד\"ת על דברי הבלים. וצ\"ל והלא זהו הפי' הפשוט בהפסוק ומה מחדש ר\"מ וקאמר תנא בשם ר\"מ.\n<b>והענין</b> דהנה כתי' ומותר האדם מן הבהמה אין כי הכל הבל, וצ\"ל האיך אומר שלמה החכם במשלי ומותר כו', והלא האדם יש לו חכמה ומברר בירורים, ועל אכילה מברך תחילה וסוף, ולומד ומתפלל, ואיך אומר ע\"ז שהוא הבל. והענין דהנה הבל אין פי' ע\"פ פשוט אלא כו', דהנה שלמה אמר ז' הבלים, הבל הבלים אמר קהלת הבל הבלים הכל הבל. ובקצרה יש בזה ג' שיטות, הזהר מפרש למעליותא שהוא ע\"ד מ\"ש וישע ה' אל הבל ואל מנחתו שהוא מדריגה גבוה, וכמארז\"ל אין העולם מתקיים אלא בהבל פיהם של תנוקות של בית רבן שהוא הבל של תורה, ובזוהר אי' הבלא דעלמא קאים עלי', והוא משל כמו שההבל הוא עיקר קיום האדם מה שהוא מכניס הבל ומוציא הבל, וזהו מיתת חנק ח\"ו שמונע התפשטות ההבל ועי\"ז נחנק ח\"ו, וכמו\"כ בהבראם בה' בראם דהוא אתא קלילא דלית בי' מששא מ\"מ יש בי' מעט הבל, והעיקר הוא הבל הלב<sup data-n=\"942\">2</sup> שנמשך בקול, וקול הוא כלול מאש מים רוח ונמשך לה' מוצאות, הקול מחבר ההבל עם הדיבור, וזהו הבל ה' ל\"ב, ל\"ב הם ל\"ב פעמים ש' אלקים שבמע\"ב דבעשרה מאמרות ברא הקב\"ה את עולמו והוא דיבור ויאמר אלקים, וה' הם ה' מוצאות הפה, וזהו והלא במאמר א' יכול להבראות<sup data-n=\"943\">3</sup> הוא ההבל טרם שנמשך לדיבור הוא מאמר א', והוא מ\"ש כי על כל מוצא פי הוי' יחי' האדם שהוא מוצא פי מקור הדיבור, הרי מפרש הבל למעליותא. והמדרש דרש לגריעותי' דקאמר כל מה שנברא בששת ימי בראשית ועל יום השביעי מאטערט מען זיך, הכל הבל, דבראשון נברא שמים וארץ כתי' שמים כעשן נמלחו והארץ כבגד יבלה עש יאכלם, בשני יהי רקיע וכתי' ונגלו כספר השמים, בשלישי יקוו המים וכתיב",[["941","1","<b>וראיתי אני</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב. והוא מיוסד על ד\"ה זה להצ\"צ בכת\"י הנק' ”במדבר דברים — רב\"ק\" (מס. 466 שפה, ב). ונו\"א בס' מאמרי אדהצ\"צ תרט\"ו ע' קכט ואילך. ונו\"א שם ע' רנז ואילך. [וראה גם ביאוה\"ז להצ\"צ ח\"ב ע' תתעג ואילך. תתעח-ט. תתפא ואילך. תתצו ואילך]. ונמצא בתוס' הגהות בד\"ה זה בסה\"מ תר\"ל ע' קסג ואילך. תרנ\"ח ע' קסו ואילך.\nמאמר זה הוא בהמשך להמאמר שלפנ\"ז ד\"ה ואל משה אמר עלה אל ה', שלע\"ע הגיע לידינו רק התחלתו. [ראה ד\"ה אריב\"ל כשעלה משה למרום שנדפס לקמן בהוספות הוספה ע' שכג]."],["942","2","<b>יש בי' מעט הבל והעיקר הוא הבל הלב</b>: נת' בארוכה בביאוה\"ז להצ\"צ שם ע' תתפד. וס\"ע תתצו ואילך."],["943","3","<b>דבעשרה מאמרות. . והלא במאמר א' יכול להבראות</b>: ראה בארוכה (בענין מאמר א' שלמע' מעש\"מ) סה\"מ תרכ\"ז ע' רפב ואילך. [ובהמקומות שנסמנו שם ע' רפא]."]]],[2000460320,"והחרים ה' את לשון ים מצרים, ברביעי יהי מאורות וכתיב וחפרה הלבנה ובושה החמה, בה' כו'.\n<b>ובת\"י</b> מפרש באופן אחר והמכוון א', דכד חמי שלמה מלכא ברוח נבואה דיתחלק רחבעם וירבעם ויתחרב ביהמק\"ד אי' כל היגיעות שיגעתי אני ודוד הכל הבל, וצ\"ל מה שייך זה למה שנתחלקו כו' וא\"ל לא הי' בהמק\"ד חרב, ואיך אומר ע\"ז הכל הבל. והענין דהנה נק' ע\"ש יוסף<sup data-n=\"944\">4</sup> כמ\"ש נוהג כצאן יוסף, דהנה יוסף הוא ל' תוספת וכתיב ויגש אליו יהודה שצריכים אליו יהודה, דהנה יש ב' מיני המשכות א' בסוד שרש, עוד כל ימי הארץ קיץ וחורף קור וחום יום ולילה לא ישבותו, והוא חק נתן ולא יעבור, ויש סוד תוס'<sup data-n=\"945\">5</sup> שתוספתו של הקב\"ה מרובה על העיקר, ומשל גשמי לזה הוא כמו עצם כתובה הוא מנה ומאתים, ותוס' כתובה הוא על כמה אלפים ורבבות, כמו\"כ כאן תוספתו של הקב\"ה מרובה על העיקר שיהי' ע\"ד שיהי' לע\"ל ונגלה כבוד הוי' וראו כל בשר יחדיו כי פי הוי' דיבר, ולא יכנף עוד מוריך והיו עיניך רואות את מוריך, וזהו בחי' יוסף. והנה הכלי לבחי' זו הוא יהודה, דהנה יהודה הוא הודאה<sup data-n=\"946\">6</sup>, דאא\"ס לית מחתב\"כ וצ\"ל הודאה, וזהו שבתפלה העיקר הודאה הודו לה', מודים אנחנו לך, לכן מאן דלא כרע במודים אינו קם כו' שאין לו גם בחי' הודאה זו, ויש מודים דרבנן שהוא הודאה על הודאה<sup data-n=\"947\">7</sup> מודים אנחנו לך על שאנו מודים. וה\"ה כמו מודים חכמים לר\"מ, הגם שסוברים דלא כר\"מ מ\"מ מודים שדינו אמת, הגם שאינם משיגים למה הוא כן מ\"מ מודים. כמו\"כ באוא\"ס אינו שייך השגה, מודה שכן הוא, איהי בהוד [שכל מה שאפשר להשיג צריכים להשיג, ומה שא\"א להשיג צריכים], [דצריכים להשיג שיש, וצריכים] להודות<sup data-n=\"948\">8</sup>, וזהו שביוסף יש ג' אותיות השם עדות ביהוסף, וביהודה שם שלם, דאיהו דכשנמשך המשכת [אוא\"ס] אלקות [הוא בנצח] גם נצח ישראל לא ישקר ולא ינחם כי לא אדם הוא להנחם, והכלי לזה הוא יהודה. וצ\"ל התחברות יהודה ויוסף אחד באחד יגשו<sup data-n=\"949\">9</sup> למהוי אחד באחד, אחד דיחו\"ע באחד דיחו\"ת. אבל כד יתחלקון יוסף ויהודה ואז יחרב בהמק\"ד, דבמשכן כתיב ואהי' מתהלך באהל משכן שהי' עראי, אבל בהמק\"ד הוא קבע שלא יהיה שינוים, דמאיר מבחי' אני הוי' לא שניתי, אבל כד יתחלקון אזי יחרב כו', ולכן הכל הבל.",[["944","4","<b>דהנה נק' ע\"ש יוסף</b>: כ\"ה בגוכי\"ק. ובד\"ה זה תר\"ל: דהנה עשרת השבטים נק' ע\"ש יוסף."],["945","5","<b>יש ב' מיני המשכות א' בסוד שרש. . ויש סוד תוס'</b>: ראה גם אוה\"ת לך לך (כרך ד) תשטז, ב. דברים ע' כ. תרל\"ד ע' ו. וש\"נ."],["946","6","<b>יוסף הוא ל' תוספת. . יהודה הוא הודאה</b>: ראה גם תו\"א ויגש מד, א. סה\"מ מלוקט ח\"ב ע' רכא ואילך. וש\"נ."],["947","7","<b>מודים דרבנן. . הודאה על הודאה</b>: ראה לקמן ח\"ב ד\"ה מזמור לתודה. וש\"נ."],["948","8","<b>שכל מה שאפשר. . צריכים] </b>[דצריכים. . וצריכים]<b> להודות</b>: בצידי הגליון נרשם בגוכי\"ק: ב' נוסחאות. [ור\"ל שהבא בין חצאי ריבוע הם ב' נוסחאות]. וראה ד\"ה וראיתי אני תר\"ל שם: שא\"א להשיג עצמות אוא\"ס בבחי' השגה גמורה רק בבחי' הודאה כו' דהיינו שהשגה הוא רק בבחי' הודאה."],["949","9","<b>וצ\"ל התחברות יהודה ויוסף אחד באחד יגשו</b>: ראה תו\"א ויגש שם מד, א-ב. ובכ\"מ."]]],[2000460321,"<b>והנה</b> מה שהזהר מפרש זה למעליותא הבלא דעלמא קאים עלי' היינו לגבי העולם הוא בחי' גבוה, אבל לגבי מדריגה שלמעלה ממנו ה\"ז הבל הארה, בה' בראם אתא קלילא דלית בי' מששא, וזהו שלגבי תורה הוא הבל, דהנה תורה הוא אמת דכתי' קרוב הוי' לכל קוראיו לכל אשר יקראוהו באמת, ואין אמת אלא תורה, רק שנק' ואמת הוי' לעולם שנמשך עי\"ז בעולם הרי שנק' אמת אני ראשון ואני אחרון ומבלעדי אין אלקים, דנהרות המכזבים פעם א' בשבוע פסולים לקידוש מי חטאת שאין זה אמת<sup data-n=\"950\">10</sup>, וזהו בזמן דעכשיו, ובזמנים הקודמים כתי' גבי חבקוק למה תכזב בשפחתך<sup data-n=\"951\">11</sup> הגם שהולד נולד מ\"מ מאחר שאינו מתקיים כמו חיי האדם ה\"ז כזב, לכן נק' התורה אמת שהוא קיום נצחי קיום עולמי. וזהו שתורה הוא חיי עולם ותפלה חיי שעה, דתפלה הוא רפאנו ברך עלינו שהוא חיי שעה, ותורה הוא חיי עולם שנק' אמת. וכמו\"כ כאן מאחר שאינו קיום נצחי לכן הוא הבל. וז\"ש תנא בשם ר\"מ כו' הרי מחדש שלגבי תורה נק' זה הבל.\n<b>וזה</b> שאמר שזה כיתרון אור מן החושך, הנה צלה\"ק תחילה מ\"ש יוסף לפרעה ועתה ירא פרעה איש חכם ונבון, וצ\"ל מי שמו ליועץ שקרא לו לפתור חלומו, ומה קאמר לו ועתה כו', דלכאורה אינו שייך זה לזה כלל. אך כמו שמפרש המגיד משרים להב\"י את החלום<sup data-n=\"952\">12</sup> יובן זה ג\"כ, דז' פרות הטובות הם ז' מדות הטובות, וז' פרות הרעות הנה זלעו\"ז עשה אלקים הם ז' מדות הרעות, ותאכלנה כו' דהנה השתל' המדות הרעות מהטובות הוא כן דמאהבה לאלקות נשתלשל אהבה זרה ומיראה נשתלשל כעס, ותאכלנה כו' ולא נודע כי באו אל קרבנה שנשכחת האהוי\"ר, וצריכים לתקן זה. וזהו שאמר לו ועתה ירא כו' איש חכם ונבון, דהנה שרשם מז\"ת דשם ס\"ג, והבל הוא מילוי שם ס\"ג שנפלה בשבה\"כ ואפשר להיות מזה מדות רעות, וע\"י חכמה מתקנין זה דימותו ולא בחכמה, וזהו ועתה ירא פרעה איש חכם ונבון.\n<b>והנה</b> זהו להפי' דיתרון לחכמה על כו' אבל להפי' יתרון חכ' מן הסכלות<sup data-n=\"953\">13</sup> כמ\"ש בפסוק צ\"ל הפי' כן בההבלים, דהנה [אורייתא מחכמה נפקת] וכתיב שבעה שבועות תספר לך ז' פעמים ז' וכתיב תספרו חמשים שיום החמשים בא ממילא והוא",[["950","10","<b>דנהרות המכזבים. . שאין זה אמת</b>: בהבא לקמן ראה בארוכה הוספות לאוה\"ת בראשית (כרך ב) תלב, א. סה'\"מ תרכ\"ט ע' קסב. [ובהמ\"מ שם]. תרל\"ב ח\"א ע' ערה. ועוד."],["951","11","<b>כתי' גבי חבקוק למה תכזב בשפחתך</b>: בד\"ה זה תר\"ל: בהשונמית כתי' אל נא תכזב בשפחתך. וראה זח\"ב מד, סע\"ב (אודות בן השונמית): ודא הוא חבקוק נביאה כד\"א את חובקת בן. וראה גם הוספות לאוה\"ת בראשית שם תלב, רע\"ב."],["952","12","<b>כמו שמפרש המגיד משרים להב\"י את החלום</b>: הובא ונת' בביאוה\"ז להצ\"צ שם ע' תתסג."],["953","13","<b>זהו להפי' דיתרון לחכמה על כו', אבל להפי' יתרון חכ' מן הסכלות</b>: ב' הפי' נתבארו לעיל בד\"ה ואל משה אמר עלה אל ה'. [ראה בהנסמן לעיל בתחילת המאמר]. — וראה ד\"ה זה תר\"ל שם: והוא לפי' הא' שיתרון האור הוא על החושך, והנה לפי פי' השני שיתרון האור הוא מן החושך עכצ\"ל גם כאן שיתרון לדברי תורה הוא דוקא מן ההבלים."]]],[2000460322,"שער הנו\"ן דבינה שבו התגלות עתיק, ושבועות הי' מ\"ת, בשעה שאמרו ישראל נעשה ונשמע ירדו מלאכי השרת וקשרו להם ב' כתרים א' כנגד נעשה וא' כנגד נשמע והם ב' מדרי' שבכתר, וזהו דוקא ע\"י בירורים דעוה\"ז עי\"ז דוקא נעשה יתרון, דכלום אדם רואה מן הלבן שבעין אלא מן השחור כמו\"כ ע\"י החושך עי\"ז דוקא היתרון אור."],[2000460323,"<h3>יהודה בן תימא כו' עז כנמר</h3>\n<b>ש\"פ תצוה ט\"ל, לפ\"ק.</b>\n<b>יהודה</b> בן תימא אומר<sup data-n=\"954\">1</sup> הוי עז כנמר וקל כנשר כו', וצ\"ל מהו המעלה מה שיהי' עז כנמר והלא עז פנים לגיהנום. והענין דכמו שיש עז בלעו\"ז כמו\"כ יש עז בקדושה והו\"ע הגזירות וסייגים שלא יבוא לאיסור תורה. והנה כל הגזירות והסייגים היו בבית שני ולא בבית ראשון.\n<b>והענין</b> דהנה כתיב סוב דודי<sup data-n=\"955\">2</sup> ודמה לך לצבי או לעופר האילים על הרי בתר, בתר הוא טורי דפרודא<sup data-n=\"956\">3</sup> גלו לבבל שכינה עמהם, הגם שאינו נמשך גילוי אלקות היינו לינקא אבל לאגנה עליהו נמשך, וכתיב ושמתי כסאי בעילם, בשושן הבירה אשר בעילם המדינה, השכינה נק' לפעמים בשם שושן כשושנה בין החוחים, ובשושן גופא יש מדריגות והעיר שושן נבוכה, והעיר שושן צהלה ושמחה שנמשך גילוי אלקות.",[["954","1","<b>יהודה בן תימא אומר</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב, ונרשם בקיצור. מאמר זה מיוסד על ד\"ה זה להצ\"צ בס' בש\"ו (מס' 1063 שכד, א) שנדפס לקמן בהוספות. מאמר הצ\"צ (מלבד ההתחלה) מיוסד על ד\"ה להבין למה לעתיד יתבטלו כל הנביאים בהוספות לתו\"א מג\"א קטז, ג ואילך. ובשינויים בס' מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע פט ואילך. נו\"א שם ח\"ב ס\"ע תרצב ואילך. ובתוס' הגהות באוה\"ת מג\"א (הוצאת תש\"נ) ע' רל ואילך. רנד ואילך. וקיצורים והגהות ע\"ז שם ע' רכז-ח. רמז ואילך. רנ-נא. רנב ואילך. רס ואילך.\nתוכן המאמר נמצא בשינויים בד\"ה ביום השני הקריב (פרקים א-ג) בסה\"מ תרכ\"ז ע' רה ואילך.\nלעניני המאמר ראה גם ד\"ה היושבת בגנים גו' ברח דודי: בס' מאמרי אדה\"ז תק\"ע ע' נד ואילך. אוה\"ת שה\"ש (כרך ב) ע' תשע ואילך. תשעט ואילך. תשפב ואילך. שם (כרך ג) ס\"ע א'טז ואילך. המשך מים רבים תרל\"ו פקל\"ב-ד (ס\"ע קמא ואילך. וראה גם סה\"מ תרל\"ו ח\"ב ע' תעב). סה\"מ תרס\"ה ע' רלב. הוספות להמשך תרס\"ו (הוצאת תנש\"א) ע' תקצז ואילך. סה\"מ מלוקט ח\"ב ע' רכט ואילך. תשי\"ז. תשל\"ח ע' קסג ואילך."],["955","2","<b>והענין דהנה כתיב סוב דודי</b>: בהבא לקמן ראה הוספות לתו\"א מג\"א שם קטז, ג ואילך. ובד\"ה היושבת בגנים הנסמן לעיל."],["956","3","<b>הרי בתר. . הוא טורי דפרודא</b>: ראה בכ\"ז [נוסף להדרושים שנסמנו לעיל] לקו\"ת דרושים לשבת שובה סה, ג."]]],[2000460324,"<b>והנה</b> במרכבה יש כמה מדריגות, יש מרכבה דסוסים כמ\"ש כי תרכב על סוסיך<sup data-n=\"957\">4</sup> מרכבותיך ישועה וקאי על מ\"ת, דסוסים הם אותיות שע\"י נמשך גילוי אלקות, כמו הסוס שמוליך את הרוכב עליו, והוא מפני שסוס הוא בגי' ב\"פ ס\"ג ששם שוין מעלה ומטה. ויש מרכבה אחרת כמארז\"ל בלילה מה עבד קוב\"ה רוכב על כרוב קל ושט בח\"י אלף עלמין. ובמ\"ת הי' מרכבה דסוסים, דכדי שיומשך בגשמיות ציצית בצמר גשמי תפילין בקלף גשמי זהו דוקא ע\"י מרכבה דסוסים שהוא מרכבה לאדם, דהנה כתיב ועל דמות הכסא דמות כמראה אדם עליו מלמעלה, והלא אין לו דמות הגוף ואין לו גוף אלא שהוא בחי' תורה כמ\"ש זאת התורה אדם.\n<b>וזהו</b> שאמר סוב כו' ודמה לך לצבי כו', הנה צבי אי אפשר להיות מרכבה לאדם כ\"א לבחי' דמה לך, דהנה אדם הוא אדמה לעליון, ודמה לך עצומ\"ה זהו דוקא ע\"י צבי שהולך במרוצה, דכדי שיומשך מבחי' זו על הרי בתר טורי דפרודא שאפי' לטורי דפרודא יומשך ג\"כ הוא דוקא ע\"י צבי, וזהו מלמעלמ\"ט. וכמו\"כ יש מלמטלמ\"ע וכמ\"ש סוב דודי ודמה לך לצבי ולעופר אילים על הרי בשמים דהוא העלאה, דבשמים הוא דבר שהנשמה נהנית ממנו ולא הגוף, דזה גורם שיהי' לאגנה עליהו שהוא למעלה מהתחברות אורות בכלים, דע\"י אכילה נעשה חבור נשמה עם הגוף והוא בחי' תורה שנק' לחם כמ\"ש לכו לחמו בלחמי, את קרבני לחמי, ובשמים הוא דבר שהנשמה נהנה ממנו ולא הגוף והוא העלאה מלמטה למעלה.\n<b>וזהו</b> יהודה בן תימא אומר הוי עז כנמר, דהנה אמרז\"ל ערבים עלי דברי סופרים יותר מיינה של תורה, דיינה של תורה הוא [רמ\"ח מ\"ע ושס\"ה ל\"ת] אבל ערבים עלי דברי סופרים שהם הגזירות והסייגים שלא יבואו לאיסור תורה וזה נק' עז, כמ\"ש כי עם קשה עורף וסלחת מפני שעם קשה עורף לכן וסלחת<sup data-n=\"958\">5</sup>, דענין העקשות הוא הגם שמבין בשכלו מ\"מ מתעקש, כמו\"כ כאן הוא בחי' עז כנמר. וזהו שקונן דוד את שאול ויהונתן מנשרים קלו ומאריות גברו שהוא בחי' עז כנמר וקל כנשר.\n<b>וזהו</b> אתה גבור לעולם אד' מחי' מתים אתה, מתים הם הניצוצות שנפלו בשבה\"כ מז' מלכין דמיתו. והנה אמרז\"ל לא גלו אלא בכדי שיתוסף עליהם גרים, וצ\"ל והלא אמרז\"ל קשים גרים לישראל כספחת לבשר חי. והענין דהנה גרים הם ניצוצות",[["957","4","<b>והנה במרכבה יש כמה מדריגות. . כי תרכב על סוסיך</b>: בהבא לקמן ראה גם לק\"ת שה\"ש יא, סע\"ב ואילך. סה\"מ תרל\"ד ע' שנג. שנט ובמקומות שנסמנו לעיל בתחילת המאמר."],["958","5","<b>מפני שעם קשה עורף לכן וסלחת</b>: ראה שמו\"ר פמ\"ב, ט: והנה עם קשה עורף הוא כו' אתה סבור שהוא לגנאי ואינו אלא לשבח כו' (שאינו רוצה להמיר דתו) — הובא בלקו\"ת בלק סז, ד. האזינו עג, רע\"ב. וראה גם תו\"א תצוה פה, סע\"א. פה, ג-ד. הוספות לתו\"א מג\"א קכג, ב-ג. לקו\"ת בלק עא, ב. סה\"מ תרל\"ג ח\"ב ע' שלו. תער\"ב-ע\"ו ע' קכב."]]],[2000460325,"והאדם מברר אותם ע\"י מה שאוכל ומברך תחילה וסוף ולומד ומתפלל מברר אותם, וזהו מחי' בגי' ס\"ג שההעלאה הוא בשם ס\"ג, וזהו א\"תה ג\"בור ל\"עולם א\"ד' שם אגל\"א שהוא נותן כח שיוכל לברר, וזהו רב להושיע כל רב מבבל וכל רבי מא\"י, רבי ביו\"ד הוא שמאיר מבחי' חכ'<sup data-n=\"959\">6</sup> ורב הוא טורי דפרודא, (הג\"ה והתנא והאמורא רב שנז' בכמה מקומות, אפ\"ל לכן נק' רב מפני שמברר טורי דפרודא עכ\"ה), ורב להושיע שאפי' בבחי' רב יומשך ג\"כ ישועה.\n<b>ועפ\"י</b> זה יובן מ\"ש ויהי בימי אחשורוש<sup data-n=\"960\">7</sup>, וצ\"ל והאיך אסתר שהיא מל' נישאת לאחשורוש. והענין דכמו שיש אחשורוש בלעו\"ז כמו\"כ יש בקדושה ג\"כ, אחש הוא [ל' מהירות] מל' חושן המשפט<sup data-n=\"961\">8</sup> (הג\"ה לא זכיתי להבין מה שייך חושן המשפט למהירות עכ\"ה), וחש עתידות, בעתה אחישנה, ורוש הוא כמו ענבימו ענבי רוש<sup data-n=\"962\">9</sup>. עוי\"ל רוש ארעמקייט דבקרבנות יש קרבן דלות ודלי דלות, וזהו ההפרש בין רו\"ש לדלו\"ת, דלו\"ת יש בו יו\"ד, משא\"כ רו\"ש, דהנה במחצית השקל כתיב העשיר לא ירבה והדל לא ימעיט, מעשר, א\"כ גם בדלו\"ת יש יו\"ד, משא\"כ ברו\"ש, וזהו שאפי' לרו\"ש יומשך מבחי' אחש, ולכן נישאת לו אסתר שזה שייך לה.\n<b>אך</b> צ\"ל האיך גדל המלך את המן, והענין דהנה הקב\"ה הראה לאברהם בברית בין הבתרים שהוא [לשון] הרי בתר את הג' גליות וכתיב אימה חשיכה גדולה, אימה הוא גלות מצרים, חשיכה הוא גלות בבל, גדולה הוא גלות אדום, ע\"ש גדל המלך שמקבל מגדולה מעולם התהו שקדם לעולם התיקון, ולכן נדון בסנהדרי גדולה דלאחר הדברים האלה עד מפלת המן יש ע' פסוקים, ועד והנחש הי' ערום ג\"כ ע' פסוקים ששניהם נדונו בסנהדרי גדולה, פי' סנהדרין שדנים את הגדולה, לכן אחר בימים ההם שנברא הרפואה גדל המלך שיהי' לו מפלה. עוי\"ל שלכן גדל המלך כדי שיהי' מה ראו על ככה ומה הגיע אליהם, דהנה יש כה וככה<sup data-n=\"963\">10</sup>, כה הוא כדמותינו, וככה הוא למטה יותר והוא בחי' רוש, והנה כתי' וקבל היהודים את אשר החלו לעשות, במ\"ת הי' ההתחלה הדר קבלוה בימי אחשורוש שע\"י שהיו במס\"נ כל השנה",[["959","6","<b>כל רב מבבל וכל רבי מא\"י רבי ביו\"ד. . חכ'</b>: ראה בארוכה הוספות לתו\"א מג\"א שם קיז, ג ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' צד ואילך. סה\"מ תרל\"ג ח\"ב ע' תכז-ח. ועוד."],["960","7","<b>ועפ\"י זה יובן מ\"ש ויהי בימי אחשורוש</b>: בהבא לקמן ראה הוספות לתו\"א מג\"א שם קיח, א ואילך."],["961","8","<b>אחש הוא </b>[ל' מהירות]<b> מל' חושן המשפט</b>: ראה אוה\"ת תצוה ר\"ע א'תרמט: חשן י\"ל לשון חוש ומהירות שיומשך ההשפעה במהירות כו', ונק' חושן המשפט ע\"ד לעשות משפט עמו ישראל כו' ורש\"י פי' ע\"פ ועשית חשן משפט בירור דברים. וראה עד\"ז באוה\"ת משפטים ע' א'קד. סה\"מ תרל\"ג ח\"א ע' קסד. קסו. תרנ\"ג ע' קעט. קפא."],["962","9","<b>ורוש הוא כמו ענבימו ענבי רוש</b>: ראה פירש\"י עה\"פ (האזינו לב, לד): ענבי רוש, עשב מר. וראה הוספות לתו\"א מג\"א שם."],["963","10","<b>שיהי' מה ראו על ככה ומה הגיע אליהם. . יש כה וככה</b>: ראה הוספות לתו\"א מג\"א שם קיח, ג-ד. וראה גם תו\"א מג\"א צט, סע\"ב-ג. סה\"מ תר\"מ ח\"א ע' קעז-ח."]]],[2000460326,"המשיכו ממ\"ה לככה, וזהו מה ראו על ככה ומה הגיע עליהם (הג\"ה, וע' בבוך השמים ואשא בד\"ה ומקנה רב בהג\"ה<sup data-n=\"964\">11</sup> מה שיך מ\"ה וככה למס\"נ עכ\"ה).",[["964","11","<b>וע' בבוך השמים ואשא בד\"ה ומקנה רב בהג\"ה</b>: הכוונה לד\"ה ומקנה רב תרל\"ח שהוא חלק מהמשך ד\"ה ואשא אתכם תרל\"ח (שהוא הגהות לד\"ה השמים כסאי שבתו\"א) — נדפס בסה\"מ תרל\"ח ע' תמג-ד. וראה גם שם ע' רלד."]]],[2000460327,"<h3>חייב אינש לבסומי</h3>\n<b>פורים ט\"ל, לפ\"ק.</b>\n<b>חייב</b> אינש<sup data-n=\"965\">1</sup> לבסומי בפוריא עד דלא ידע בין ארור המן לברוך מרדכי, וצ\"ל מה שייך לבסומי לעד דלא ידע בין כו'. והענין דהנה דהנה כתיב וחכך כיין הטוב<sup data-n=\"966\">2</sup> הולך למישרים דובב שפתי ישנים, וצ\"ל והלא יין גורם שינה וכאן אמר שיעורר שינה דובב שפתי ישנים.\n<b>והענין</b> דהנה כל הנס של פורים הי' מה שבלילה ההוא נדדה שנת המלך<sup data-n=\"967\">3</sup> ואי' בילקוט דבזמן שאין ישראל ערש\"מ עושה עצמו כאילו הוא ישן ובזמן שישראל עושין רש\"מ אז לא ינום ולא יישן. ובגמ' בסוף סוטה אי' ג\"כ יוחנן כה\"ג ביטל את המעוררים, וצ\"ל למה ביטל את המעוררים. והענין דבאמת אין צריכים למעוררים, והענין דהנה הגלות נמשל לשינה<sup data-n=\"968\">4</sup>, כמו בעת [השינה] אז מסתלקים כחות הנפש, כמו\"כ למעלה הגם דהמחדש בטובו בכ\"י תמיד מע\"ב וכתי' ואתה מחי' את כולם א\"ת מחי' אלא מהוה זהו רק בחי' חיצונית אבל פנימיות נסתלק, דכמו שבעת",[["965","1","<b>חייב אינש</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב, ונרשם בקיצור. המאמר מיוסד על ד\"ה זה באוה\"ת מג\"א (הוצאת תש\"נ) ע' רצג ואילך. מאמר האוה\"ת מיוסד על ביאוה\"ז לאדהאמ\"צ סז, א ואילך [ע\"פ: דובב שפתי ישנים]. ובשינויים והגהות בביאוה\"ז להצ\"צ ח\"א ע' שכה-ו. [וראה סה\"ש תרצ\"ו ע' 128 שיסוד המאמר הוא מד\"ה חייב אינש לאדה\"ז. עיי\"ש. וראה תורת מנחם התוועדויות תשי\"ז ח\"ב ע' 178].\nתוכן המאמר נמצא בשינויים בד\"ה בלילה ההוא בסה\"מ תרל\"ב ח\"א ע' רנג ואילך. ד\"ה חייב אינש: בסה\"מ עטר\"ת ע' רצט ואילך. תרפ\"א ע' קעט ואילך. תש\"ח ע' 107 ואילך. ד\"ה בלילה ההוא בסה\"מ ה'ש\"ת ע' 5 ואילך. ד\"ה אני ישינה בסה\"מ תש\"ג ע' 114 ואילך. ד\"ה בלילה ההוא בסה\"מ: תש\"מ ע' צט ואילך. תשמ\"ג ע' קב ואילך. תשד\"מ (סה\"מ מלוקט ח\"ב ע' רסה ואילך). תשמ\"ו ע' קכ ואילך.\nהמאמר שלאח\"ז ד\"ה וקבל היהודים הוא המשך למאמר זה."],["966","2","<b>כתיב וחכך כיין הטוב</b>: בהבא להלן ראה ביאוה\"ז לאדהאמ\"צ ולהצ\"צ שם."],["967","3","<b>כל הנס של פורים הי' מה שבלילה ההוא נדדה שנת המלך</b>: ראה גם סה\"מ תרל\"ב ח\"א שם ע' רנג. וש\"נ."],["968","4","<b>והענין דהנה הגלות נמשל לשינה</b>: בהבא לקמן ראה [נוסף לדרושים שנסמנו לעיל בתחילת המאמר] תו\"א וארא נה, א. סה\"מ תרל\"א ע' קכח. [ובמקומות שנסמנו שם]."]]],[2000460328,"השינה מ\"מ הגוף חי, ולכן נמשל לשינה דהנה המשכת אוא\"ס בעולמות הוא כמו ירידת הנשמה בגוף, דהנה לבושין תקינת לון דמנייהו כו' חסד דרועא ימינא גבו' דרועא שמאלא כו', דכמו שהגוף אין לו ערך להנשמה ופעולת הנשמה הוא ע\"י אמצעית הגוף, כמו\"כ כדי שיומשך להעולם הוא ע\"י חסד דרועא ימינא גבו' דרועא שמאלא, מ\"מ אינו דומה לירידת הנשמה בגוף שיש בהנשמה שינוי, דאין שייך לומר דעצם הנשמה אינה מתלבשת בגוף כלל, והלא הנשמה היתה תחילה בג\"ע והיתה מופשטת מגשמיות ואח\"כ נתלבשה בגוף, משא\"כ למעלה אינו שייך שום שינוי כמ\"ש כי נשגב שמו לבדו, שאפי' נשגב שהוא סוכ\"ע הוא רק שם והארה בעלמא שאינו נוגע לעצמיות, הודו על ארץ ושמים אפי' על ארץ ושמים רק זיו והארה בעלמא, וירם קרן לעמו רוממות הקרן<sup data-n=\"969\">5</sup> הוא לעמו, דהנה ישראל לי ראש כמו שבראש הוא עיקר החיות ומשם נמשך לכל האברים, כמו\"כ השראת אוא\"ס הוא העיקר בישראל ואח\"כ נמשך לכל המדריגות. וזהו כארבע רוחות השמים פרשתי אתכם, וארז\"ל כשם שא\"א לעולם בלא רוחות<sup data-n=\"970\">6</sup> כך א\"א לעולם בלא ישראל, לכן אומרים בק\"ש ג\"כ תחילה ה' אלקינו שהוא היחוד עם ישראל<sup data-n=\"971\">7</sup> ואח\"כ ה' אחד שהוא ז' רקיעים וארץ וד' רוחות העולם. וא\"כ צ\"ל מהו\"ע הגלות.\n<b>והענין</b> דהנה מה שהראש ראש היינו בזמן שהוא ער, אבל בזמן שהוא ישן [אין יתרון בראש על הגוף], דהנה בעת השינה אז הסתלקות החיות למקורו ושרשו [ושם הם באופן אחר], דהנה המוח הוא קר ולח ויסוד האש הוא בלב והם מנגדים זל\"ז ואיך אפשר שיהיו שניהם, והנה בעת שהם מלובשים בגוף אז הם כל אחד בכלי מיוחד אך איך הם בנפש אלא שם הם באופן אחר<sup data-n=\"972\">8</sup>, כמו\"כ למעלה מצד [שרשם] יכולים שניהם לקבל<sup data-n=\"e20\">*</sup> דאם צדקת מה תתן לו ורבו פשעיך מה תעשה לו אם חטאת מה תפעול בו ומה מידך יקח.\n<b>והנה</b> בחי' שינה למעלה הוא ע\"י שינה למטה, וזהו מסירת המן ישנו עם אחד, הגם שהוא אחד כד אמליכתי' למעלה ולמטה כו' אך הוא בבחי' שינה,",[["969","5","<b>כמ\"ש כי נשגב שמו לבדו. . וירם קרן. . רוממות הקרן</b>: ראה בכ\"ז לעיל ד\"ה הללוי' גו' במרומים. וש\"נ."],["970","6","<b>וארז\"ל כשם שא\"א לעולם בלא רוחות</b>: ראה לקמן ח\"ב ד\"ה מי זאת הנשקפה. [ובהמ\"מ שם]."],["971","7","<b>לכן אומרים בק\"ש. . ה' אלקינו. . היחוד עם ישראל</b>: ראה תו\"א בראשית ו, רע\"ב. לקו\"ת אחרי כו, א. ועוד."],["972","8","<b>והם מנגדים זל\"ז. . בנפש. . הם באופן אחר</b>: ראה סה\"מ תרכ\"ט ע' ריט-כ. תרל\"ב ח\"א שם ע' רנה. וש\"נ."],["e20","*","הג\"ה שאל ר\"ד* תומארקין מכ\"ק אאמו\"ר שליט\"א מאחר ששניהם מקבלים משם בשוה מהו\"ע השליטה, והשיב לו דאחר מיתה גדילים שערות וצפרנים יותר מעת שהוא חי, עכ\"ה)."]]],[2000460329,"וזהו היינו כחולמים<sup data-n=\"973\">9</sup> כמו שבחלום אפשר להתחבר שני ענינים נפרדים כמו\"כ בשעת התפילה הוא בטל לאלקות ואח\"כ חולף ועובר ועוסק במו\"מ וניכר שהביטל לא הי' ביטול אמיתי, מפוזר ומפורד בין העמים הם המח\"ז מהבלי עוה\"ז ועי\"ז גורמים למעלה שינה, אבל כשהי' צ\"ל גאולה אז נדדה שנת המלך מבחי' לא ינום ולא יישן כדי שיהי' גאולה.",[["973","9","<b>וזהו היינו כחולמים</b>: ראה בכ\"ז תו\"א וישב כח, ג. ועוד."]]],[2000460330,"<h3>וקבל היהודים</h3>\n<b>פורים ט\"ל, לפ\"ק.</b>\n<b>וקבל</b> היהודים<sup data-n=\"974\">1</sup> את אשר החלו לעשות, במ\"ת הי' רק התחלה והדר קבלוה בימי אחשורוש. הנה הגם שנת\"ל שבעת השינה אז הסתלקות החיות<sup data-n=\"975\">2</sup>, מ\"מ נשאר אור [מצומצם] גם בהכלים והם יכולים לקבל גם מאור זה מאחר שנסתלק הפנימיות, אלא שרוצים לקבל ממדריגה גבוה מאחר שאור זה הוא מצומצם.\n<b>וזהו</b> יעשו עץ גבוה חמישים אמה הוא שער הנו\"ן דבינה<sup data-n=\"976\">3</sup> שם אינו שייך השגה, שאפילו משה לא השיג בחי' זו רק בעת הסתלקותו, וזהו\"ע ספה\"ע כשסופרים מ\"ט יום אז בשבועות יום החמישים ממילא<sup data-n=\"977\">4</sup>, ודוקא כשסופרים תחילה המ\"ט יום.\n<b>והנה</b> עיקר הנס הוא מה שנדדה שנת המלך כו' ספר הזכרונות דברי הימים, ימים הם ששת ימי בראשית, ולא נא' בששת ימים עשה אלא ששת<sup data-n=\"978\">5</sup> ימים עשה שהששת ימים גופא עשו, כל יומא ויומא עביד עבדתי', והם שית אלפי שני דהוה עלמא, דיומא של הקב\"ה אלף שנה, וצריכים להמשיך בהימים, ודברי הימים היינו חיבור דברי עם ימים. וזהו בלילה ההוא, הוא בחי' עלמא דאתכסי' בחי' לאה, ישכב עמי הלילה, ההוא וכמ\"ש ועבד הלוי הוא שהיו אומרים שירה על היין והמשיכו מעלדאכ\"ס. וזהו כמו שיהי' לע\"ל ואמר ביום ההוא הנה אלקינו זה שמבחי' הוא יהי'",[["974","1","<b>וקבל היהודים</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב, ונרשם בקיצור. — מאמר זה הוא המשך להמאמר שלפנ\"ז, וראה בהנסמן שם לכללות המאמר. וראה גם סה\"מ תרל\"ב ח\"א ע' רנז-ח."],["975","2","<b>שנת\"ל שבעת השינה אז הסתלקות החיות</b>: לעיל בד\"ה חייב אינש."],["976","3","<b>וזהו יעשו עץ גבוה חמשים אמה. . שער הנו\"ן דבינה</b>: ראה תו\"א מג\"א צג, ד. אוה\"ת שמות (כרך ז) ע' ב'תקצז. מג\"א (הוצאת תש\"נ) ע' קי. [ובדרושים שנסמנו בהמאמר שלפנ\"ז בתחילתו]."],["977","4","<b>וזהו\"ע ספה\"ע. . מ\"ט יום. . יום החמישים ממילא</b>: ראה בארוכה לקו\"ת במדבר יב, א ואילך."],["978","5","<b>ולא נא' בששת. . אלא ששת</b>: ראה גם סה\"מ תרל\"ד ע' נד. וש\"נ."]]],[2000460331,"בחי' זה, אז נדדה שנת המלך כמו דובב שפתי ישנים דיין גורם שינה, אך זה גורם שיהי' דובב שפתי ישנים והוא יין המשמח שמחת הנפש באלקות כו', שהוא מדריגה אחרת ביין<sup data-n=\"979\">6</sup>. ולכן יוחנן כה\"ג ביטל את המעוררים שא\"צ לזה מאחר שע\"י היין נעשה פעולה זאת. ועוי\"ל ענין היין הוא כמו חמר טב דאי' בזהר דשקיט ושכיך על דורדיא והוא בחי' מו\"ס שמלובש בו גבו' דעתיק, וזהו עיקר הנס מה שנדדה שנת המלך, הגם שהי' בקשת אסתר, מ\"מ עיקר הנס הי' מה שנדדה שנת המלך.\n<b>וזהו</b> וקבל היהודים את אשר החלו לעשות, במ\"ת הי' רק ההתחלה ואח\"כ בימי אחשורוש הי' גמר ההתחלה, דהנה השקיפה ממעון קדשך מן השמים וברך את עמך ישראל, שמים הוא שם מים בחי' תורה, דכדי שיומשך גילוי אלקות זהו ע\"י תורה, ובמ\"ת הי' רק ההתחלה והדר קבלוה בימי אחשורוש שהי' גמר הקבלה.",[["979","6","<b>יין המשמח. . שהוא מדריגה אחרת ביין</b>: ראה בארוכה תו\"א מקץ לא, א. תו\"ח מקץ עב, ב ואילך."]]],[2000460332,"<h3>וידבר גו' זאת חוקת</h3>\n<b></b><b>ש\"פ כי תשא, פ' פרה ט\"ל לפ\"ק</b>\n<b>וידבר</b> ה' אל משה ואהרן לאמר זאת חוקת<sup data-n=\"980\">1</sup> התורה אשר צוה ה' לאמר, וצ\"ל מהו\"ע ב\"פ הוי' והל\"ל כמו בכל התורה וידבר ה' אל משה כו' זאת חוקת התורה. והענין דהנה בחוקה יש ג' פירושים<sup data-n=\"981\">2</sup>, הא' דהנה כתי' מגיד דבריו ליעקב חוקיו ומשפטיו לישראל, דבמצות יש ב' מדריגות חוקים ומשפטים, משפטים הם דיני ממונות שהם ע\"פ השכל וחוקים הם למעלה מהשכל, ופרה אדומה הוא חוקה שלמעלה מהשכל. הב' כמו חוקה חקקתי חוקות שבהם חקקתי שמים וארץ. הג' ל' חוק כמו הטריפני לחם חוקי, כי חוק הוא לישראל, ואכלו את חוקם. וכל הג' פי' ישנם בפרה.\n<b>והענין</b> דהנה כללות תושב\"כ הוא אש שחורה ע\"ג אש לבנה, דכתיבה היא בדיו על הקלף שהוא חבור ב' ענינים נפרדים הדיו והקלף שמתחברים ע\"י הכתיבה, וחקיקה הוא מיני' ובי'<sup data-n=\"982\">3</sup>. והנה (הג\"ה אפ\"ל וביאור הענין דהנה עכ\"ה)",[["980","1","<b>וידבר ה' גו' זאת חוקת</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מן ד\"ה זה הנדפס לעיל ע' צו. ראה בהנסמן בארוכה בהמ\"מ לעיל בתחילת המאמר שם."],["981","2","<b>דהנה בחוקה יש ג' פירושים</b>: ראה גם לקו\"ת ר\"ה נד, ד. עטרת ראש נז, ב. אוה\"ת חוקת ע' תשסו ואילך. שם בהוספות (הוצאת תשנ\"ח) ע' 38. אוה\"ת תצא ע' תתקס-סא."],["982","3","<b>וחקיקה הוא מיני' ובי'</b>: ראה לקו\"ת בחוקותי מה, א. מה, ד ואילך. חוקת נו, א. נט, ג-ד. ובכ\"מ."]]],[2000460333,"אמרז\"ל קיים אברהם את כל התורה כולה עד שלא ניתנה, וצ\"ל והלא יש מצות שתלוים בארץ, ותפילין שכ' בהם יצ\"מ והאיך קיים אותם. והענין הוא דהנה האבות קיימו המצות ברוחניות, [דתורה] הוא רצו\"ש<sup data-n=\"983\">4</sup> [וכמ\"ש<sup data-n=\"984\">5</sup> מימינו אש דת למו, אש הוא גבו' שהוא רצוא ומימינו הוא מים שוב<sup data-n=\"985\">6</sup>] ובאברהם כתיב הלוך ונסוע הנגבה. וענין הרצוא הוא בכל לבבך שלימות הלב. דהנה כתיב ראה נתתי לפניך את החיים<sup data-n=\"986\">7</sup> ואת הטוב את המות ואת הרע והעצה ובחרת בחיים, מות ורע הם תענוגי עוה\"ז, וטוב הוא השפעת אלקות בג\"ע, וחיים הוא מקור ההשפעה, ובחרת בחיים שנבחר באוא\"ס, והשוב הוא בתורה והו\"ע בכל נפשך בג' לבושי הנפש מחדו\"מ שיקשר מח' במח' דתורה ודיבור בדיבור דתורה ומעשה במעשה המצות, ועי\"ז יהי' והחיות רצו\"ש.\n<b>ובפרה</b> יש ג\"כ רצו\"ש רק שהרצו\"ש דפרה הוא למעלה יותר מהרצו\"ש דכללות התורה. דהנה הרצוא דכללות התורה הוא בכל לבבך בכל הלב, אבל רק כמו הלב ולא יותר, ובהתבוננות הוא ג\"כ ובחרת בחיים לאהבה את ה' אלקיך כי הוא חייך, שהוא התלבשות אורות בכלים, אבל כאן הרצוא הוא בכל מאדך שיוצא מהגבלת הכלי, דכתיב ועמך לא חפצתי, כל מה שעמך לא חפצתי, כי עמך מקור חיים אפי' מקור החיים ומקור התענוגים כל מה שעמך זה לא חפצתי, כ\"א באוא\"ס עצומ\"ה, ועי\"ז והחיות רצו\"ש<sup data-n=\"987\">8</sup> שהחיות אלקי [יומשך בנבראים ובנאצלים], והשוב הוא מים חיים אל כלי שהוא ג\"כ מדריגה גבוה.\n<b>והנה</b> ענין הפרה אי' בזוהר פרה דקבילת משמאלא<sup data-n=\"988\">9</sup> ומאן איהו משמאל הה\"ד פני שור מהשמאל, וצ\"ל והלא כל הקרבנות הם תקון קו שמאל דמשמאל אפ\"ל רישא דעשו בעיטפא דיצחק, ומהו דוקא פרה. והנה אמרז\"ל על ג' דברים העולם עומד על תורה ועבודה וגמ\"ח, תורה הוא קו האמצעי, גמ\"ח קו הימין, עבודה קו השמאל. והנה להבין ענין עבודה קו השמאל<sup data-n=\"989\">10</sup> צריכין להבין תחילה ענין תורה קו האמצעי, דהנה ע\"י תורה נמשך המשכת אלקות בעולמות לבד למוד התורה, הנה הוא מצוה. ובמצוה יש ב' פי', הא' ל' ציווי כפשוטו, הב' ל' צוותא וחבור<sup data-n=\"990\">11</sup> [שמחבר",[["983","4","<b>האבות קיימו המצות ברוחניות. . רצו\"ש</b>: ראה תו\"א יתרו עג, ד. מג\"א צו, ג. ועוד."],["984","5","<b>דתורה. . [וכמ\"ש</b>: מוסגרים אלו מופיעים כן בגוכי\"ק. ועד\"ז כ\"פ לקמן במאמר. פעמים רבות הוספות אלו שבתוך המוסגרים הם מה שאמר כ\"ק אדמו\"ר מהר\"ש פעם ב' בעת חזרת המאמר."],["985","6","<b>מימינו אש דת. . ומימינו הוא מים שוב</b>: ראה הלשון לעיל במאמר ע' צז, ובנסמן שם."],["986","7","<b>דהנה כתיב ראה נתתי לפניך את החים</b>: ראה בכ\"ז תו\"א תשא פה, ג-ד. לקו\"ת ואתחנן יא, ד. תצא לה, ג-ד. נצבים מו, ג. האזינו עב, ב. ועוד."],["987","8","<b>ועי\"ז והחיות רצו\"ש</b>: ראה לעיל בהמאמר ע' צז-צח. וש\"נ."],["988","9","<b>אי' בזוהר פרה דקבילת משמאלא</b>: ראה בכ\"ז לקו\"ת חוקת נו, ג. נח, ג. ביאוה\"ז לאדהאמ\"צ צו, ד ואילך. אוה\"ת חוקת ע' תשע ואילך. תשפ ואילך. סה\"מ תרכ\"ט ע' קא ואילך."],["989","10","<b>והנה להבין ענין עבודה קו השמאל</b>: להבא להלן — ראה בנסמן לעיל בהמאמר ס\"ע צח."],["990","11","<b>ובמצוה יש ב' פי'. . צוותא וחבור</b>: ראה לקו\"ת חוקת נז, א. פינחס עו, א. מסעי צב, ג. לקו\"ש ח\"ז ע' 30 ואילך. ובכ\"מ."]]],[2000460334,"שיומשך בעולמות]. דהנה כתיב רבות עשית אתה ה' אלקי<sup data-n=\"991\">12</sup> נפלאותיך ומחשבותיך אלינו אין ערוך אליך, רבות עשית הם ריבוי הנבראים נפלאותיך הם מבחי' נפלאותיך כמ\"ש בס\"י בל\"ב נתיבות פליאות חכמה ועי\"ז בהנפעלים ג\"כ יש חכ' כמו בגלגלים, ול\"ב הם ך\"ב אותיות ועשרה מאמרות, ונפלאותיך ומחשבותיך הם רק אלינו אבל אין ערוך אליך וכדי שיומשך בעולמות זהו ע\"י תורה, וזהו שאמרז\"ל תנאי התנה הקב\"ה במע\"ב אם יקיימו ישראל תורתי מוטב וא\"ל אחזיר את העולם לתהו ובוהו שהעיקר נמשך ע\"י התורה, ואי' [במדרש] ובזוהר עשרה עשרה הכף בשקל הקודש עשרת הדברות מכוון כנגד עשרה מאמרות<sup data-n=\"992\">13</sup> שעשרת הדברות נותנים כח בהע\"מ, ואמרז\"ל ע\"פ אלה תולדות השו\"א בהבראם אלה בשביל מי הם נבראו ובזכות מי הם עומדים שיהיו חזקים כיום הבראם בזכות אלה שמות בנ\"י, ואלה בזכות מי נבראו ובזכות מי הם עומדים בזכות אלה העדות והחוקים והמשפטים, שעיקר ההמשכה הוא ע\"י תורה.\n<b>ועבודה</b> הוא קו השמאל שהוא העלאה, וצ\"ל והאיך ע\"י קרבן שמקריב בהמה נכפר החטא והלא הבהמה לא חטא. והנה ענין הקרבן בקצרה, דבהמה שרשה מבהמה רבה ונמשך בבהמה דרביעא על אלף טורין<sup data-n=\"993\">14</sup> עד שנמשך למטה בהמה גשמי, לכן כשמעלין אותה לשרשה מכפרת<sup data-n=\"994\">15</sup>. ועכשיו תפלה במקום קרבנות תקנו, דנה\"ב שרשו ג\"כ מבחי' זו וע\"י התפלה מעלים אותו, וזהו דכתיב הגו סיגים מכסף ויוצא לצורף כלי, דקודם הצירוף הכסף אינו טוב וגם הפסולת אינו גרוע שמעורבים אבל כשמבררים דוחין את הפסולת לחוץ ונשאר הכסף, כמו\"כ כתי' מצרף לכסף וכור לזהב איש לפי מהללו, לפ\"ע הצירוף שעושה בנפשו בתפלה ע\"י ההילול ושבח, הוא כלי להשראת אוא\"ס וזהו איש לפי מהללו. וזהו שאומרים בתפלה סלח לנו אבינו כי חטאנו<sup data-n=\"995\">16</sup> ולכאורה הול\"ל זה קודם התפלה, אך קודם התפלה דרך איש ישר בעיניו שלא עשה עבירה ולמד תורה, אבל בתפלה בהתבוננות דק\"ש ח„פט ער זיך<sup data-n=\"996\">17</sup> אז אומר סלח לנו אבינו כי חטאנו, וזהו הבירור וההעלאה דנה\"ב.",[["991","12","<b>דהנה כתיב רבות עשית אתה ה' אלקי</b>: ראה גם תו\"א מקץ לא, ג. לקו\"ת צו יב, ד. שה\"ש מ, ב. סה\"מ תרכ\"ז ע' רמח. ובכ\"מ."],["992","13","<b>ואי' </b>[במדרש]<b> ובזוהר עשרה עשרה הכף. . מכוון כנגד עשרה מאמרות</b>: ראה לקו\"ת חוקת שם נז, ג-ד. אוה\"ת תשא ע' א'תתנא. חוקת ע' תשסח ואילך. סה\"מ תרכ\"ז ע' רמח ואילך. תרל\"ב ח\"ב ע' תמ. תרפ\"ט ס\"ע 74 ואילך. [ובכל מקומות הנ\"ל אלו מצויין ע\"ז: זוהר ויקרא די\"א ע\"ב ואילך. אבל ראה גם במד\"ר במדבר פי\"ד, יא: כנגד עשרה מאמרות שנברא בהם העולם וכנגד עשרת הדברות כו']."],["993","14","<b>ונמשך בבהמה דרביעא על אלף טורין</b>: ראה במ\"מ לעיל בהמאמר ע' ק."],["994","15","<b>לכן כשמעלין אותה לשרשה מכפרת</b>: ראה גם לקו\"ת שה\"ש כח, ג. סה\"מ תרכ\"ז ע' קלד, ואילך. תרכ\"ט ע' סט ואילך וע' קי ואילך. ובכ\"מ."],["995","16","<b>וזהו שאומרים בתפלה סלח לנו אבינו כי חטאנו</b>: ראה גם לקו\"ת בהעלותך ל, ב. תצא לה, ב. דרושים לש\"ש סה, ג. סה\"מ תרכ\"ז ע' רנ-נא וע' תלג. ובכ\"מ."],["996","17","<b>ח„פט ער זיך</b>: לעיל בהמאמר (ע' ק) הלשון: אזי הוא מבין שנמצא בו פסולת ג\"כ. [וראה בס' תורת מנחם התוועדויות ח\"י ע' 102 (וש\"נ) אודות מה שנמצא לפעמים בתוך מאמרים ביטויים בלשון אידיש, שהוא כשרוצים לדבר על ענין פנימי שיחדור בפנימיות אז מדברים בלשון המורגל]."]]],[2000460335,"<b>ועוד</b> עבודה הי' בקרבנות תרומת הדשן<sup data-n=\"997\">18</sup> דכתיב ולבש הכהן מדו בד ומכנסי בד והרים את הדשן, וצ\"ל מה צריכין לזה לבושים גבוהים כ\"כ. והענין דבמרירות יש ב' מדריגות<sup data-n=\"998\">19</sup>, הא' שפלות שהוא מדריגה גבוה כמ\"ש מרום וקדוש אשכון את דכא ושפל רוח, דענוה גדולה מכולם, הב' עצבות והוא אסקופה הנדרסת לכל החטאים. ובאמת הוא מקור לכל החטאים. וזהו\"ע תרומת הדשן שהטוב הי' נבלע במקומו והמותר הי' שופך לשפך הדשן, והו\"ע העצבות.\n<b>וכמו\"כ</b> יובן בפרה שהי' אפר הפרה ועשן המערכה כמו בכל הקרבנות, אלא שבכל הקרבנות הי' העיקר העשן המערכה ובפרה העיקר האפר. וענין העשן הוא כמ\"ש והר סיני עש\"ן כולו הוא ר\"ת עולם שנה נפש<sup data-n=\"999\">20</sup>, עולם הוא מקום, ושנה הוא זמן, ונפש הוא חיות המקום וזמן<sup data-n=\"1000\">21</sup>, וזהו ויעל עשנו כעשן הכבשן. אך צ\"ל דהנה כתיב והרשעה בעשן תכלה<sup data-n=\"1001\">22</sup>, וכתיב ואוהבי ה' כיקר כרים כלו בעשן כלו, ומה שייך שם עשן. והענין דהנה בפשעים יש ב' דברים, הא' עצם החטא, הב' הרהור ודיבור החטא<sup data-n=\"1002\">23</sup>. והנה הדיבור וההרהור א\"א לעלות, ועצם החטא אפשר לעלות ע\"י תשובה דאין לך דבר שעומד בפני התשובה ועי\"ז בא לבכל מאדך. והנה בכל דבר יש ד' יסודות ארמ\"ע, והנה אש רוח מים יוצאים בעשן<sup data-n=\"1003\">24</sup> והעפר נשאר שהוא העיקר בכל היסודות דהכל הי' מהעפר, וזהו\"ע האפר שהוא עצם החטא, לכן פרה מטהר את הטמאים אפי' רשעים שבחייהם קרוים מתים פרה מטהר אותם.\n<b>וזהו</b> דאי' במדרש כשהוא רוצה קוראו פר וכשהוא רוצה קוראו פרה, פר דכתיב פר החטאת, פרה זאת חוקת הפרה, וצ\"ל והלא גבי אהרן הי' דוקא פר וגבי פרה אדומה דוקא פרה, וכמו שהי' בכל הקרבנות פרים וגם נקבות. והענין דהנה פר הוא ק\"נ ופרה הוא גקה\"ט לגמרי<sup data-n=\"1004\">25</sup>, וזהו\"ע פרה אדומה שהוא [הבירור] מגקה\"ט לגמרי.",[["997","18","<b>ועוד עבודה הי' בקרבנות תרומת הדשן</b>: ראה בהמ\"מ לעיל בהמאמר ס\"ע ק."],["998","19","<b>דבמרירות יש ב' מדריגות</b>: ראה תניא פל\"א (לט, ב)."],["999","20","<b>כמ\"ש והר סיני עש\"ן כולו הוא ר\"ת עולם שנה נפש</b>: ראה במאמרי אדה\"ז על פרשיות התורה ח\"א ע' א וע' שז. מאמרי אדהאמ\"צ בראשית ע' נו ואילך. במדבר ח\"ב ע' שלב ואילך. שלז ואילך. אוה\"ת יתרו ע' תתטז וע' תתכג. סה\"מ תרכ\"ז ע' צט-ק. וש\"נ. שם ע' קלח. תרכ\"ח ע' קמד. תרל\"ח ע' יט-כ וע' מג. ועוד."],["1000","21","<b>ונפש הוא חיות המקום וזמן</b>: ראה בהמ\"מ לעיל בהמאמר ע' קא."],["1001","22","<b>כתיב והרשעה בעשן תכלה</b>: : כ\"ה הלשון גם בלקו\"ת דרושים לשמע\"צ צא, ב. והוא בנוסח תפילת ר\"ה ויוהכ\"פ. [וגם ע\"ז שייך לשון ”כתיב\" — עי' ”הערות ותיקונים\" שבסו\"ס התניא לדף מו, ב]."],["1002","23","<b>הא' עצם החטא, הב' הרהור ודיבור החטא</b>: ראה לקו\"ת חוקת שם נו, ג-ד. דרושים לר\"ה סא, ב. ובכ\"מ."],["1003","24","<b>והנה אש רוח מים יוצאים בעשן</b>: ראה אגה\"ק סי' טו (קכא, ב). לקו\"ת חוקת שם נו, ג. נח, ג. ס, ב. סה\"מ תרכ\"ט ע' קסג. וראה גם המשך תער\"ב ח\"ג ע' א'תמב. ועוד."],["1004","25","<b>דהנה פר הוא ק\"נ ופרה הוא גקה\"ט לגמרי</b>: ראה בהמ\"מ לעיל בהמאמר ע' קב."]]],[2000460336,"<b>והשוב</b> הוא ונתן מים חיים אל כלי, מים חיים הם המים כמו שנובעים מהמקור והוא כמו מי שממציא איזה שכל ומתענג ממנו והוא מפני שהוא קרוב להמקור [עדיין]. אל כלי שיומשך לכלים מכלים שונים. וכ\"ז מרומז בפ' ראשונה דק\"ש, בכל לבבך הוא הרצוא דכללות התורה, ובכל נפשך הוא השוב, בכל מאדך הוא הרצוא דפרה אדומה ואח\"כ והיו הדברים האלה בד\"ת הכתוב מדבר הוא השוב, ואח\"כ הלימוד והשנון דתורה, ואח\"כ וקשרתם כו' תפילין דהוקשה כל התורה לתפילין שיומשך בכלים מכלים שונים.\n<b>וזהו</b> וידבר ה' כו' ב' שמות הוי', דהנה ע\"י גלות מצרים נמשך שם הוי' דלעילא דוקא ע\"י הבירור דמצרים, דהנה כתיב וארא אל אברהם<sup data-n=\"1005\">26</sup> ואל יצחק ואל יעקב באל שדי ושמי הוי' לא נודעתי להם, פי' ידיעה והכרה לא הי' בשם הוי' גבי ג' אבות העולם, אבל ע\"י בירור דמצרים כתיב לכן אמור לבנ\"י אני הוי' שמאיר משם הוי' דלעילא. וזהו שאמר ריש מתיבתא אעא דלא שליט בי' נורא<sup data-n=\"1006\">27</sup> מבטשין לי' גופא דלא שליט בי' נהורא דנשמתא מבטשין לי'. והנה אי' במדרש ויקחו אליך פרה זו מצרים<sup data-n=\"1007\">28</sup> שנא' עגלה יפיפיה, אדומה זו בבל דכתיב אנת הוא רישא דדהבא, תמימה זו מדי דמלכי מדי תמימים היו כו', ועי\"ז מאיר משם הוי' דלעילא הוי' דעתיקא. והנה סדר הכתוב כך, וידבר הוי' הוא הוי' דז\"א אל משה יסוד ז\"א<sup data-n=\"1008\">29</sup> לאמר שיומשך במל' זאת כו' אשר צוה הוי' הוא הוי' דעתיקא לאמר חכ'. וענין אומרו זאת חוקת כו', הנה כתיבה בדיו על הקלף הדיו משחיר הרי מעלים אותו מקום, וחקיקה הוא מני' ובי', והוא מדריגה גבוה ולכן אפשר שיומשך משם שיהי' חוקה שלמעלה מהשכל, וגם חוקה ל' חוק כמ\"ש הטריפני לחם חוקי, שלא יהי' שינוי דחוק הוא מל'<sup data-n=\"1009\">30</sup> שאפי' במל' לא יהי' שינוים וכמ\"ש ברוך כבוד הוי' ממקומו שהוי' יומשך ממקומו וכמ\"ש וימלא כבוד הוי', וכמו שביקש יעקב ברוך שם כבוד מלכותו<sup data-n=\"1010\">31</sup> לעולם ועד, שאפי' בבחי' זו יומשך מבחי' לעלם ולעלמי עלמיא, וזהו זאת חוקת התורה שמבחי' חקיקה יומשך שיהי' בחי' חוק אפי' במל' בלא שינוי.",[["1005","26","<b>דהנה כתיב וארא אל אברהם</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' מט. צד ואילך. וש\"נ."],["1006","27","<b>וזהו שאמר ריש מתיבתא אעא דלא שליט בי' נורא</b>: ראה גם תניא פכ\"ט (לה, סע\"ב)."],["1007","28","<b>והנה אי' במדרש ויקחו אליך פרה זו מצרים</b>: ראה גם לקו\"ת חוקת סא, ב. אוה\"ת חוקת ע' תשעז. ובכ\"מ."],["1008","29","<b>אל משה יסוד ז\"א</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["1009","30","<b>דחוק הוא מל'</b>: ראה בהמ\"מ לעיל במאמר ע' קד."],["1010","31","<b>וכמ\"ש וימלא כבוד הוי'. . ברוך שם כבוד מלכותו</b>: ראה סה\"מ תקס\"ט ע' קפה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרכח. אוה\"ת שלח ע' תקיא ואילך. דרמ\"צ קעח, א ואילך. סה\"מ תרל\"ד ע' רמג ואילך."]]],[2000460337,"<h3>החודש הזה</h3>\n<b></b><b>בס\"ד ש\"פ ויק\"פ, החודש, ט\"ל לפ\"ק</b>\n<b>החודש</b> הזה לכם<sup data-n=\"1011\">1</sup> ראש חדשים ראשון הוא לכם לחדשי השנה, וצ\"ל ענין ראשון הוא לכם, דהנה כתיב גבי שלמה ויקהלו העם אל המלך שלמה<sup data-n=\"1012\">2</sup> בירח האתנים בחג הוא החודש השביעי ותרגם דעתיקייא קראו לי' ירחא קדמאה וכען הוא ירחא שביעאה, דעתיקייא קראו לי' ירחא קדמאה דבך\"ה באלול נברה\"ע ותשרי הוא ראש וכמ\"ש והיו לאותות ולמועדים לימים ולשנים, וכען הוא ירחא שביעאה דניסן הוא ראשון לחדשי השנה, וכדאי' במדרש משבחר הקב\"ה בעולמו קבע להם ר\"ח ושנים ומשבחר ביעקב ובניו קבע להם חודש של גאולה בו נגאלו ובו עתידים להגאל כמ\"ש כימי צאתך מארץ מצרים אראנו נפלאות, והוא כר' יהושע שסובר בניסן עתידים להגאל.\n<b>והנה</b> צ\"ל תחילה ענין יצ\"מ שצריכים להזכיר ערב ובוקר פעמים בכל יום, דהנה כתיב לכן אמור לבנ\"י<sup data-n=\"1013\">3</sup> אני הוי' והוצאתי אתכם מתחת סבלות מצרים, דכשמאיר בחי' הוי' אז והוצאתי כו'. והענין דהנה כתיב מה יפית<sup data-n=\"1014\">4</sup> ומה נעמת אהבה בתענוגים, למעלה נק' כנס\"י אהבה בתענוגים, ולמטה בעבודה הוא שמחה של מצוה. והענין דהנה כתיב תחת אשר לא עבדת<sup data-n=\"1015\">5</sup> את ה' אלקיך בשמחה וטוב לבב מרוב כל, כל הוא העמוד המחבר געה\"ע וגעה\"ת, כמ\"ש כי כל בשמים וארץ, שמים וארץ הם געה\"ע וגעה\"ת ופי' בתרגום דאחיד בשמיא וארעא שהוא העמוד המחבר שמים וארץ, ואמרז\"ל יפה שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב, כל שהוא חיי עוה\"ב, עוה\"ב הוא ג\"ע, וזהו מרוב כל מריבוי המדריגות שיש בכל, הגם שהם רק ב' מדריגות געה\"ע וגעה\"ת אבל [בפרט] יש ריבוי מדריגות כמ\"ש ילכו מחיל אל חיל, דאברהם אבות ומשה שהם כ\"כ שנים בג\"ע הרי הם מתעלים ממדריגה למדריגה, וזהו מרוב כל מריבוי המדריגות. והענין דהנה כתיב כי נשגב שמו לבדו, כמו שם האדם<sup data-n=\"1016\">6</sup> שאינו נוגע לעצמותו כמו\"כ למעלה השם אינו נוגע לעצמיות, וכתיב בי\"ה הוי' צור עולמים שכללות ברה\"ע הי' רק בב' אותיות, ומה תופסים ב' אותיות לגבי כללות הדיבור ומכ\"ש לגבי עצמיות, ובאמת כי נשגב שמו",[["1011","1","<b>החודש הזה לכם</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מן ד\"ה זה הנדפס לעיל ע' קה. ראה בהנסמן בארוכה בהמ\"מ לעיל בתחילת המאמר שם."],["1012","2","<b>ויקהלו העם אל המלך שלמה</b>: ראה בכ\"ז אוה\"ת נ\"ך (כרך א) ע' סא. לעיל בספר זה בד\"ה ויקהלו. וש\"נ."],["1013","3","<b>דהנה כתיב לכן אמור לבנ\"י</b>: ראה בכ\"ז בתו\"א וארא נז, ב ואילך. ובהנסמן ע\"ז עוד לעיל בהמאמר ע' קה-ו."],["1014","4","<b>דהנה כתיב מה יפית</b>: ראה תו\"א וארא שם. אוה\"ת שה\"ש (כרך ב) ע' תריג ואילך. סה\"מ קונטרסים ח\"א קמז, ב. קנא, א-ב."],["1015","5","<b>דהנה כתיב תחת אשר לא עבדת</b>: ראה גם תו\"א תצוה פא, ב-ג."],["1016","6","<b>דהנה כתיב כי נשגב שמו לבדו כמו שם האדם</b>: ראה תו\"א תרומה עט, ג. לקו\"ת בהר מא, ג. בלק סז, ג. ובכ\"מ. לקמן ד\"ה הללוי' גו' מן השמים פ\"ב. וש\"נ."]]],[2000460338,"שאפי' השם ג\"כ נשגב ואינו מאיר ממנו רק הארה הודו על ארץ ושמים, שמים וארץ הם געה\"ע וגעה\"ת<sup data-n=\"1017\">7</sup> רק הודו וזיוו מאיר, אבל עצם השם הוא נשגב, אך מפני שהוא הארה משם לכן העונג הוא עונג נפלא עד אין קץ דכדאי כל יסורי גיהנום כו' מפני שהוא עונג נפלא, אבל מ\"מ הוא רק הארה משם, אבל מצות הם מצותיו, דהקב\"ה מניח תפילין הקב\"ה מתעטף בציצית, ושבת הוא שבת להוי', מועדי הוי', וגבי צדקה כתי' אני מדבר בצדקה, מדבר פי' מנהיגם כמו ידבר עמים, ונמשך מבחי' אני, ונק' מצות הוי' שממשיכים לש' הוי', הרי שהוא מדריגה גבוה שהם מצותיו, דג\"ע הוא רק הארה משם ומצות הם מצותיו.\n<b>וע\"י</b> ההתבוננות זו יבוא לבחי' שמחה של מצוה שהוא פנימיות המצוה, דיש באברים חיצוניות האבר ופנימיות האבר שהוא חיות האבר, כמו\"כ כשעושה המצוה בקרירות דרך מצות אנשים מלומדה הוא בחי' חיצוניות, אבל כשעושה אותה בשמחה הוא פנימיות. ושרש השמחה הוא מבינה דהוא אם הבנים<sup data-n=\"1018\">8</sup> שמחה, וכמ\"ש כי אם לבנים תקרא, בנים הם ז\"א ובינה נק' אם הבנים.\n<b>וזהו</b> לכן אמור לבנ\"י אני הוי', כשמאיר הוי' שהוא גילוי התורה אז והוצאתי אתכם מתחת סבלות מצרים. דהנה מצרים הוא מיצר הגרון שהוא מקום הדחוק שבאדם, דהנה הקנה הוא מחבר שיומשך ממוחין למדות, קנה חכ' קנה בינה, שממשיך ממוחין למדות, אך מיצר הגרון הוא שאינו נמשך ממוחין למדות, ושם ג' שרי פרעה קנה וושט ורידין<sup data-n=\"1019\">9</sup> הם שר הטבחים שר המשקין שר האופים והוא שנמשך אחר תענוגי עוה\"ז ויש לו שמחה מזה. והוצאתי אתכם מתחת סבלות מצרים שמאיר ממוחין למדות. וזהו שמצינו שמצרים [ויצ\"מ] הם עיבור ולידה, דעיבור הוא העלם ולמעלה הוא משארז\"ל בשעה שאתה מתמלא עליהם עברה כאשה עוברה ואז דינים שורה, ולידה הוא גילוי, ובשעת יציאת הולד יוצא דם הוא שיוצאים הדינים.\n<b>והנה</b> נת\"ל דמצרים הוא מיצר הגרון<sup data-n=\"1020\">10</sup>, וכתיב נחר גרוני שאינו מאיר הקול, דהקול ממשיך ממוחין למדות, אך נחר גרוני שאין הקול מאיר, וכתיב נאלמתי דומי' החשיתי שאין הדיבור מאיר, והוצאתי אתכם מתחת סבלות מצרים שע\"י הקול יומשך ממוחין למדות ולא יפסק, וכמ\"ש קול גדול ולא יסף<sup data-n=\"1021\">11</sup> ופי' בתרגום ולא פסק. דהנה כתיב קול דודי הנה זה בא מדלג, הנה זה בא שתמיד נמשך אך הוא בחי' מדלג, וזהו",[["1017","7","<b>שמים וארץ הם געה\"ע וגעה\"ת</b>: ראה תו\"א וארא שם נו, ג."],["1018","8","<b>ושורש השמחה הוא מבינה. . אם הבנים</b>: ראה מאמרי אדהאמ\"צ במדבר ח\"ג ס\"ע תתקסח-ט. אוה\"ת נ\"ך ע' תקמז ואילך. ובכ\"מ."],["1019","9","<b>ושם ג' שרי פרעה קנה וושט ורידין</b>: ראה תו\"א ויחי קב, ג ואילך. סה\"מ תרל\"ג ח\"א ע' נד ואילך. וע' רכו ואילך."],["1020","10","<b>דמצרים הוא מיצר הגרון</b>: ראה תו\"א ויצא כא, ג. כב, ב. וארא נח, ד. נט, א-ב. ובכ\"מ."],["1021","11","<b>וכמ\"ש קול גדול ולא יסף</b>: ראה לקו\"ת שה\"ש טו, א-ב. מא, ג. אוה\"ת מג\"א (הוצאת תש\"נ) ע' רנב ואילך. סה\"מ תרכ\"ז ע' ריא-ב. סה\"מ תרנ\"ט ע' קעט."]]],[2000460339,"כדי שיומשך ממוחין למדות זהו ע\"י קול התורה. וענין קול גדול הוא כמ\"ש גבי אברהם משתה גדול, גדול העולמים הי' שם, והוא בחי' גדול הוי' דע\"י שם הוי' אזי והוצאתי אתכם כו'.\n<b>והבאתי</b> אתכם אל הארץ אשר נשאתי את ידי וזה קאי על תושבע\"פ שנק' ארץ הצבי<sup data-n=\"1022\">12</sup>, דעיקר רצה\"ע הוא בתושבע\"פ<sup data-n=\"1023\">13</sup>, דכל המצות בתושב\"כ הם בקיצור כמו תפילין בתושב\"כ הוא בקיצור ובתושבע\"פ הוא באריכות שיהיו מרובעים ותפורים בגידים וריבוי פרטי דינים, הרי עיקר רצה\"ע הוא בתושבע\"פ, וזהו אשר נשאתי את ידי כמו שנושאין היד למעלה מהראש. עוי\"ל שנק' ארץ הצבי דהנה כתיב מכנף הארץ זמירות שמענו צבי לצדיק ואמרז\"ל ביקש הקב\"ה<sup data-n=\"1024\">14</sup> לעשות את חזקיהו משיח כו' וצ\"ל מהו\"ע ביקש כו' (ר\"ל מה שייך זה לצבי לצדיק). והענין דהנה גבי מ\"ת כתי' כי תרכב על סוסיך<sup data-n=\"1025\">15</sup>, דהגם שיש מרכבה דשרפים חיות ואופנים זה אינו מספיק אלא צריכים לזה מרכבה דסוסים כדי שיומשך למטה, וכדי שיומשך בתושבע\"פ שצריך להמשיך למטה יותר, דצריכים לברר גם טענות שקרים, כמו שנים אוחזים בטלית זה אומר כולה שלי וזה אומר כולה שלי שא' בודאי טוען שקר, וכמו המחליף פרה בחמור, וצריך לברר את זה ג\"כ, וצריכים מרכבה דצבי שרץ במהירות והוא א\"א להיות מרכבה לאדם. וזהו צבי לצדיק דהנה אחשורוש הוא אחש ורוש<sup data-n=\"1026\">16</sup> שצ\"ל מהירות וזהו לאגנאה עלייהו, וכדי שיהי' חזקי' משיח שהוא אחישנה צ\"ל ע\"י מרכבה דצבי דוקא.\n<b>ועפ\"ז</b> יובן המדרש משבחר הקב\"ה בעולמו<sup data-n=\"1027\">17</sup> כו', דהנה כתיב אנכי הוי' אלקיך אשר הוצאתיך מארץ מצרים וצ\"ל למה אינו אומר אשר בראתי שמים וארץ<sup data-n=\"1028\">18</sup> שהוא יותר חדוש, דיצ\"מ הוא יש מיש דממים נהפך לדם, ומים יבשה, שהוא יש מיש, אבל ברה\"ע הוא דבר מלא דבר. אך הענין הוא דהנה ברה\"ע הוא ע\"י עשרה מאמרות וכמ\"ש בי\"ה הוי' צור עולמים, והלא במאמר אחד יכול להבראות, והוא כדי שיהי' בין הארץ לרקיע מהלך ת\"ק שנה בין כל רקיע ורקיע מהלך ת\"ק שנה שהוא גבול",[["1022","12","<b>וזה קאי על תושבע\"פ שנק' ארץ הצבי</b>: ראה תו\"א וארא שם. סה\"מ תרל\"ד ע' קפח ואילך."],["1023","13","<b>דעיקר רצה\"ע הוא בתושבע\"פ</b>: ראה תו\"א וארא שם נט, א-ב. אגה\"ק סי' כ\"ט (קנ, ב ואילך)."],["1024","14","<b>דהנה כתיב מכנף הארץ. . צבי לצדיק וארז\"ל ביקש הקב\"ה</b>: ראה בנסמן ע\"ז בהמ\"מ לעיל בהמאמר ע' קח."],["1025","15","<b>דהנה גבי מ\"ת כתיב כי תרכב על סוסיך</b>: ראה תו\"א בשלח סג, א. סג, ד. לקו\"ת דרושים ליוהכ\"פ סט, ג. שה\"ש ב, ד. ג, א. לג, ג. סה\"מ תרכ\"ז ע' רו. תרל\"ד ע' שנג וע' שנט."],["1026","16","<b>דהנה אחשורוש הוא אחש ורוש</b>: ראה תו\"א בהוספות קי, א. סה\"מ תרכ\"ז ע' רט."],["1027","17","<b>ועפ\"ז יובן המדרש משבחר הקב\"ה בעולמו</b>: בכל הבא להלן, ראה גם אוה\"ת נ\"ך (כרך א) ע' סא ואילך. סה\"מ תרל\"ד ע' קסח ואילך."],["1028","18","<b>וצ\"ל למה אינו אומר אשר בראתי שמים וארץ</b>: ראה גם סידור עם דא\"ח רפד, ב. מאמרי אדהאמ\"צ ויקרא ח\"א ע' תב וע' תפד. שער האמונה לאדהאמ\"צ יא, ב ואילך. אוה\"ת יתרו ע' תתקנ ואילך וע' תתקטו. אוה\"ת פ' ראה ע' תשכט. אוה\"ת סידור ע' קט. יהל אור לתהלים ע' קי. סה\"מ תרכ\"ז ע' רלג ואילך. וש\"נ. תרכ\"ט ע' רכ ואילך."]]],[2000460340,"[ומיצר] דקדושה, אבל כדי שיצא מגבול זהו דוקא ע\"י אנכי הוי' אלקיך שמאנכי יומשך שהוי' יהי' בבחי' אלקיך אז הוצאתיך מארץ מצרים, הרי שזה רבותא יותר ולכן אמר אשר הוצאתיך מאמ\"צ ולא אשר בראתי כו'.\n<b>וכמו\"כ</b> יובן דעתיקייא קרו לי' ירחא קדמאה<sup data-n=\"1029\">19</sup>, דבהנהגת העולמות בריאה יש מאין תשרי ראש, דמזונותיו של אדם קצובין לו מר\"ה, וכען הוא ירחא שביעאה דניסן הוא ראשון לחדשי השנה. והענין דהנה י\"ב חדשים מקבלים מי\"ב בקר והם ד' מחנות שכינה, ושרשם מהים עומד עליהם מלמעלה שהוא בחי' שמו י\"ב צרופי אד'<sup data-n=\"1030\">20</sup>, ולמעלה מהם יש בחי' י\"ב צרופי הוי', ובתחילה מאיר שם הוי' ככתבו ואח\"כ נתחלף ה' ליו\"ד ועוד חילופים, ולכן בניסן שמאיר שם הוי' ככתבו<sup data-n=\"1031\">21</sup> הוא ראש לחדשי השנה, ובו נגאלו ממצרים כמ\"ש מוציא אסירים בכושרות שקאי על יצ\"מ, והוא חודש של גאולה, והוא מ\"ש מביא גואל לבני בניהם למען שמו באהבה, דהנה גלו לבבל שכינה עמהם וכמ\"ש אנכי ארד עמך מצרימה והוא גואל שמו.\n<b>ור\"א</b> אומר בניסן נגאלו ובתשרי עתידים להגאל, דניסן הוא ראשון וא\"כ תשרי שביעי וכל השביעין חביבין, נמצא יש לתשרי ב' מעלות, הא' שבהנהגת העולמות תשרי ראש, הב' דהוא שביעי. ור\"י אומר בו נגאלו ובו עתידים להגאל, כמ\"ש כימי צאתך מארץ מצרים אראנו נפלאות. ויש ע\"ז ריבוי טעמים<sup data-n=\"1032\">22</sup>, א' ע\"פ פשוט דתשרי הוא חודש המשפט, ולכן אין אומרים מועדים לשמחה בר\"ה מפני שהוא משפט<sup data-n=\"1033\">23</sup>, ולכן א\"א להיות הגאולה בתשרי כ\"א בניסן. ב' דמטעם ר\"א דבתשרי עתידים להגאל מפני שהוא שביעי אומר ר\"י דבניסן עתידים להגאל, דאף דכל השביעין חביבין מ\"מ יש מעלה לראשון<sup data-n=\"1034\">24</sup> וכמו משה שהוא דור שביעי לאברהם מ\"מ יש מעלה באברהם, דכשרצה משה לדמות עצמו לאברהם ואמר הנני א\"ל אל תקרב הלום שיש מעלה באברהם וא\"ל במקום גדולים אל תעמוד, כמו\"כ יש מעלה בניסן על תשרי. ג' דהנה יצ\"מ הי' אתעדל\"ע משל עצמו ולכן מצה נק' לחם עוני, והנה על משיח אמרז\"ל עני ורוכב על החמור שהוא אתעדל\"ע שאין אתעדל\"ת מגעת לשם ובניסן",[["1029","19","<b>וכמו\"כ יובן דעתיקייא קרו לי' ירחא קדמאה</b>: ראה בכ\"ז גם סה\"מ תרס\"ה ע' קיח. תרפ\"ו ע' רמב-ג. סה\"מ קונטרסים ח\"א קלד, א-ב."],["1030","20","<b>מי\"ב בקר והם ד' מחנות שכינה. . י\"ב צרופי אד'</b>: ראה ביאוה\"ז לאדהאמ\"צ פה, א ואילך. ולהצ\"צ ח\"א ע' תנא ואילך. סה\"מ תרל\"ד שם ע' קעד. וש\"נ."],["1031","21","<b>ולכן בניסן שמאיר שם הוי' ככתבו</b>: ראה סה\"מ תרל\"ד שם ע' קעח ואילך. סה\"מ תרע\"ח ע' רכו ואילך. לקו\"ש חכ\"ב ע' 243. הגש\"פ עם לקוטי טעמים ומנהגים (הוצאת תשנ\"ב) ע' תשי וע' תשסא. וש\"נ."],["1032","22","<b>ובו עתידים להגאל. . ויש ע\"ז ריבוי טעמים</b>: ראה אוה\"ת בא ס\"ע ער ואילך (בנוסחא הא'). ובהנסמן ע\"ז לעיל בהמאמר ס\"ע קט ואילך."],["1033","23","<b>ולכן אין אומרים מועדים לשמחה בר\"ה מפני שהוא משפט</b>: ראה בהנסמן ע\"ז לעיל במאמר ע' קי."],["1034","24","<b>דאף דכל השביעין חביבין מ\"מ יש מעלה לראשון</b>: ראה גם סה\"מ מלוקט ח\"א ע' ד-ה."]]],[2000460341,"הוא ג\"כ אתעדל\"ע משל עצמו (כנ\"ל) לכן בו עתידים להגאל. ד' דאמרז\"ל לא זז מחבבה<sup data-n=\"1035\">25</sup> עד שקראה בתי לא זז מחבבה עד שקראה אחותי לא זז מחבבה עד שקראה אמי, נמצא יש ג' מדריגות בתי אחותי אמי, והם נגד ג' מועדים<sup data-n=\"1036\">26</sup>, בת הוא פסח, אחותי שבועות, אמי סוכות, ולכן א' ר\"א דבתשרי עתידים להגאל כסדר המדריגות, ור\"י אומר בניסן עתידים להגאל דסוכות הוא בעטרה שעטרה לו אמו שאמו עוטר העטרה, אבל העטרה היא מלמעלה יותר<sup data-n=\"1037\">27</sup>, וזהו נמשך דוקא בבחי' בת כמ\"ש רני ושמחי בת דשרש המל' מכתר. וזהו החודש הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה, ראשון הוא כמ\"ש אני ראשון ואני אחרון שמבחי' זו מאיר, וזהו שניסן נק' ראשון שהוא אתדל\"ע משל עצמו.",[["1035","25","<b>ג' דהנה יצ\"מ הי' אתעדל\"ע. . ד' דאמרז\"ל לא זז מחבבה</b>: ראה לעיל במאמר (ע' קי) ב' טעמים אלו בשינוי הסדר."],["1036","26","<b>נמצא יש ג' מדריגות בתי אחותי אמי והם נגד ג' מועדים</b>: ראה אוה\"ת בא ע' רנח. רסג. שם (כרך ח) ע' ב'תקטז ואילך. נשא ע' רעג. דרושים לשמע\"צ ע' א'תשעג ואילך."],["1037","27","<b>אבל העטרה היא למעלה יותר</b>: ראה לעיל במאמר ע' קי. וש\"נ."]]],[2000460342,"<h3>לריח שמניך</h3>\n<b>ש\"פ ויקרא ט\"ל לפ\"ק</b>\n<b>לריח</b> שמניך<sup data-n=\"1038\">1</sup> טובים שמן תורק שמך ואי' במדרש כל המצות שעשו האבות ריחות היו אבל רמ\"ח מ\"ע ושס\"ה מל\"ת הם שמן תורק. והענין דהנה כתי' ששים המה מלכות ושמונים פלגשים ועלמות עד אין מספר אחת היא יונתי ואמרז\"ל ששים המה מלכות הם ששים מסכתות, ושמונים פלגשים הם ברייתות, ועלמות אין מספר הלכות התורה, אחת היא יונתי קאי על כנס\"י, משמע מזה דכנס\"י הם למעלה מתורה. וצ\"ל דהנה בזוהר אי' להיפך דתלת קשרין מתקשראין דא בדא ישראל מתקשראין באורייתא ואורייתא בקוב\"ה, הרי תורה למעלה מישראל. והנה צ\"ל תחילה מ\"ש וארא אל אברהם ואל יצחק ואל יעקב באל שדי ושמי הוי' לא נודעתי להם, וצ\"ל מה זה תשובה על טענתו שא' אד' למה הרעות לעם הזה ומה משיב לו ע\"ז וארא כו', וגם צ\"ל איך אומר לו למה הרעות כאחד שאומר אליו כנגד (קעגין). ואי' במדרש שא' נטלתי ס' בראשית והסתכלתי בו מעשה דור המבול ודור הפלגה ובדין הי' ומעשה סדום ובדין הי', ופי' במת\"כ דין אמת הי', אבל גלות מצרים אלו מה חטאו. וכן אי' לקמן במדרש פ' וארא ע\"פ ופניתי אני לראות חכמה והוללות וסכלות כי מה האדם שיבוא אחרי המלך את אשר כבר עשוהו, ודרש זה על משה ושלמה, על שלמה שרצה להתחכם נגד חכמת התורה<sup data-n=\"1039\">2</sup>, ועל משה כנ\"ל, כי",[["1038","1","<b>לריח שמניך</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ששים המה מלכות הנדפס לעיל ע' קיא. וע\"ש בהמ\"מ בתחילת המאמר. וראה לקמן הנחה נוספת ממאמר זה."],["1039","2","<b>על שלמה שרצה להתחכם נגד חכמת התורה</b>: במד\"ר שם (פ\"ו, א): לא ירבה לו סוסים וכסף וזהב כו' עמד שלמה המלך והחכים על גזירתו של הקב\"ה כו' אני ארבה ולבי לא יסור כו'."]]],[2000460343,"מה האדם שיבוא אחרי המלך את אשר כבר עשוהו להרהר אחר מדותיו של הקב\"ה.\n<b>והנה</b> להבין זה צ\"ל תחילה מ\"ש ושמי הוי' לא נודעתי להם והלא מצינו שם הוי' גבי האבות דגבי אברהם כשנק' אברם כתי' גבי' הוי' ויאמר הוי' אל אברם לך לך וכתי' וירא הוי' אליו וכתי' והוי' אמר המכסה אני מאברהם ואיך אמר ושמי הוי' כו'. והענין דהנה כתי' ויקרא הוי' הוי' פסיק טעמא בינייהו<sup data-n=\"1040\">3</sup> דבין הב' שמות הוי' פסיק טעמא ואי' בזהר שהוא כמ\"ש יהי רקיע ויהי מבדיל בין מים למים, והנה שם נא' ב' הבדלות יהי רקיע ויהי מבדיל, וכתי' ויעש אלקים את הרקיע ויבדל<sup data-n=\"1041\">4</sup> והוא מ\"ש והבדילה הפרוכת לכם<sup data-n=\"1042\">5</sup> בין קדש ובין קדש הקדשים וההבדלה בין קודש וחול, הגם שהי' ז' הבדלות אך בכלל הי' ב' הבדלות הבדלה בין קדש לחול והבדילה הפרוכת לכם בין קדש ובין קדה\"ק.\n<b>והנה</b> צ\"ל מה שם הוי', דשם אלקים הוא ע\"ש דיין שכן דיין נק' אלקים וכן למעלה יש מדריגה שנק' דיין, אל ע\"ש הכח והיכולת, שדי שא' לעולמו די אבל הוי' כו'<sup data-n=\"1043\">6</sup>. והענין דהנה הוי' הוא ל' מהווה<sup data-n=\"1044\">7</sup> שמהווה עולמות בי\"ע, לכן שם הוי' הוא י' ה' ו' ה', י' צמצום דכדי שיתהווה עולמות בראת יצרת אף עשיתיו אפי' עולמות העליונים צ\"ל צמצום, ה' התפשטות<sup data-n=\"1045\">8</sup> ו' המשכה עד שנמשך בה' אחרונה שהוא התפשטות, מ\"מ שם הוי' הוא קדוש ומובדל מעולמות דהוא סדר השתל' ובריאה הוא יש מאין, דהנה מה שהקב\"ה מחי' העולם אינו כמו הנשמה שמחי' את הגוף דמתפעלת ממקרי הגוף<sup data-n=\"1046\">9</sup> אבל הקב\"ה שממלא את העולם אינו כן, מ\"מ הוא מקור כל ההויות, וזהו הוי' מהווה, אבל יש שם הוי' דלעילא שהוא עד שלא נברה\"ע הי' הוא ושמו בלבד שהוא בעצמותו, דמצד שעלה ברצונו נעשה, אך הוא בעצמותו והוא כמו דיבור ומח', דדיבור הוא לזולתו שיכול זולתו לעשות אבל קודם שדיבר צריך לחשוב תחילה וכמו שהוא במח' זהו כמו שהוא בעצמותו. והנה שם הוי' דהאבות זהו שם הוי'",[["1040","3","<b>והענין דהנה כתי' ויקרא הוי' הוי' פסיק טעמא בינייהו</b>: ראה תו\"א בשלח סא, ד. תצוה פג, ג. פד, א. לקו\"ת חוקת נז, ג. דרושים לר\"ה נט, א. ובהנסמן עוד לעיל במאמר שם ע' קיב."],["1041","4","<b>והנה שם נא' ב' הבדלות יהי רקיע ויהי מבדיל. . ויבדל</b>: ראה בארוכה לקו\"ת ואתחנן יא, ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רמד ואילך. ח\"ב ע' תקטז ואילך. אוה\"ת ואתחנן ע' ריח ואילך. ועוד."],["1042","5","<b>והוא מ\"ש והבדילה הפרוכת לכם</b>: ראה לעיל ד\"ה כרמי גו' האלף לך שלמה. ולעיל במאמר ע' קיב. וש\"נ."],["1043","6","<b>שדי שאמר לעולמו די אבל הוי' כו'</b>: לעיל במאמר ע' קיב: ושם שד\"י שאמר לעולמו די אבל שם הוי' אין לו פירוש כו'. וע\"ש בהמ\"מ."],["1044","7","<b>הוי' הוא ל' מהווה</b>: ראה שעהיחוה\"א פ\"ד (עט, רע\"א). ובכ\"מ."],["1045","8","<b>שם הוי'. . י' צמצום. . ה' התפשטות</b>: ראה בכ\"ז לקו\"ת דרושים לשמע\"צ צב, ד. ובארוכה תו\"ח שמות (כת\"י הר\"ש סופר) רט, א ואילך. סה\"מ תרכ\"ט ע' קכו."],["1046","9","<b>הנשמה שמחי' את הגוף דמתפעלת ממקרי הגוף</b>: ראה גם תניא פמ\"ב (ס, ב). ת\"א וירא יג, ג. מאמרי אדה\"ז תקס\"ו ע' ל. ובכ\"מ."]]],[2000460344,"דלתתא אבל לא שם הוי' דלעילא. וזהו שכ' לא נודעתי ולכאורה לפי הסיפור דתורה הו\"ל הודעתי ואומרו נודעתי שקאי על עצמותו<sup data-n=\"1047\">10</sup>, וע\"י גלות מצרים האיר ש' הוי' דלעילא וכמ\"ש לכן אמר לבנ\"י אני הוי'.\n<b>וביאור</b> הענין דהנה כתי' עם לבן גרתי ופירש\"י ותרי\"ג מצות שמרתי ואמרז\"ל קיים כל התורה כולה עד שלא ניתנה<sup data-n=\"1048\">11</sup>, וצ\"ל האיך קימו כל התורה, דהנה מצות תפילין שהוא מצוה גבוה ויש בה ד' פרשיות וכתי' בהם יצי\"מ, וקודם שהי' שעבוד מצרים איך אפ\"ל יצ\"מ. אך הענין דהנה רמ\"ח פקודין רמ\"ח אברים דמלכא, והלא אין לו דמות ולא גוף, אלא כמו אברים הם כלים להשראת החיות כמו\"כ מצות כלים להשראת אוא\"ס, וזהו\"ע ציור אדם למטה, דבאדם יש ראש גוף ורגל, ראש הוא חב\"ד גוף חג\"ת רגל נה\"י בכלל ובפרט הם רמ\"ח אברים, כמו\"כ למעלה כתי' בצלם אלקים עשה את האדם שיש בחי' חב\"ד חג\"ת נה\"י, ובפרט הם רמ\"ח דז\"א בעל ט\"ס טפ\"ט פ\"א רת\"ס רמ\"ג ה\"ח<sup data-n=\"1049\">12</sup> המגדילים רמ\"ח, והנה האבות הם המרכבה, והנה [כמו] שגבי ד' חיות המרכבה כתי' ועל דמות הכסא<sup data-n=\"1050\">13</sup> דמות כמראה אדם עליו מלמעלה ומגביהים הכסא והאדם שעל הכסא אך הוא על דמות הכסא דמות כמראה אדם מפני שהוא בבריאה אבל באצי' דבריאה לגבי אצי' אינו בערך, דבריאה הוא בריאה יש מאין ואצי' הוא הפרשת<sup data-n=\"1051\">14</sup> האור מא\"ס, שם הוא בחי' אדם, ואבות הן המרכבה ממשיכים בחי' אדם שהוא מ\"ש נעשה אדם בצלמינו והוא ע\"י הביטל שלהם ומס\"נ שהי' עד שלא ניתנה תורה דעשרה נסיונות נתנסה אברהם אבינו הם נגד עשר כחות הנפש, ובכלל אברהם בחי' חסד יצחק גבו' יעקב כלול משניהם, וזהו כי יעקב בחר לו יה ישראל לסגולתו והוא כמ\"ש והייתם לי סגולה מכל העמים דענין סגולה הוא שאינו מובן<sup data-n=\"1052\">15</sup> אלא שהוא פעולה כמו\"כ המצות כמו מצות תפילין דממשיכים ד' מוחין וה\"ה אינו יודע האיך ממשיכי' זה אלא שניתן כח מלמעלה שיומשך ד' מוחין, וזהו ישראל לסגולתו, ויעקב בחר לו יה יש ב' פי'<sup data-n=\"1053\">16</sup> הא' דיעקב בחר בחי' יה, הב' יה בחר את יעקב. וזהו יעקב בחר לו יה כדי שיהי' ישראל לסגולתו. וזהו וארא אל אברהם כו' ושמי הוי' לא נודעתי להם, דגבי האבות הי' שם",[["1047","10","<b>ואומרו נודעתי שקאי על עצמותו</b>: ראה במ\"מ לעיל במאמר שם ע' קיג."],["1048","11","<b>ואמרז\"ל קיים כל התורה כולה עד שלא ניתנה</b>: ראה בכ\"ז תו\"א לך לך יא, ד. יתרו סח, א ואילך. לקו\"ת במדבר יב, ג. שלח לח, ב. שה\"ש ט, סע\"ב. סה\"מ תרכ\"ז ע' י ואילך. תרכ\"ט ע' כא ואילך."],["1049","12","<b>בעל ט\"ס טפ\"ט פ\"א רת\"ס רמ\"ג ה\"ח</b>: בעל ט' ספירות, ט' פעמים ט' עולה מספר פ\"א, ראש תוך סוף (ג' פעמים פ\"א) עולה רמ\"ג, וה' חסדים כו'. ראה בכ\"ז תו\"א מקץ לז, ד ואילך. ויחי מז, ד. יתרו סח, ג ואילך. עב, ב. עג, ג. דרושים למג\"א צז, ב. לקו\"ת בשלח ב, ד. שלח מה, ד. ובכ\"מ."],["1050","13","<b>כתי' ועל דמות הכסא</b>: בהבא להלן ראה בארוכה תו\"א יתרו עא, סע\"ג ואילך. עב, ב ואילך. עב, ד ואילך. סה\"מ תרל\"ב ח\"א ע' יב ואילך וע' טו ואילך."],["1051","14","<b>דבריאה הוא בריאה יש מאין ואצי' הוא הפרשת</b>: ראה סה\"מ תרל\"ב ח\"א ע' מב. וש\"נ. תרל\"ג ח\"ב ע' תקב ואילך. וש\"נ."],["1052","15","<b>דענין סגולה הוא שאינו מובן</b>: ראה גם לקו\"ת שה\"ש יב, ד."],["1053","16","<b>ויעקב בחר לו י\"ה יש ב' פירושים</b>: ראה אוה\"ת תבוא ע' תתרסח."]]],[2000460345,"הוי' (דלעילא) דלתתא, דהנברא אינו יכול להגיע רק אל המקור<sup data-n=\"1054\">17</sup> המהווה, אבל ע\"י מצות ניתן כח שממשיכים שם הוי' דלעילא וזה הי' במ\"ת, ולכן הוא מת\"ן תורה שהוא מתנה<sup data-n=\"1055\">18</sup>, ועוד מפני שעשי' לעילא<sup data-n=\"1056\">19</sup> שמפני שהוא בגשמיות נמשך מבחי' היותר גבוה, וכמ\"ש והוי' פקד את שרה ואח\"כ ויעש הוי' לשרה, והוי' הוא וב\"ד, ואח\"כ ויעש הוי' ואי' בזהר איהו בלחודוהי, וכמו\"כ כתי' לע\"ל עדן עין לא ראתה אלקים זולתך יעשה למחכה לו, יעשה כו' וכמו שאנו רואין באדם כשהוא בדיבור אינו כו' אבל כשעושה [עושה בעצמו].\n<b>וביאור</b> הענין דהנה כתי' הללויה הללו עבדי הוי' הללו שם הוי' וכן מצינו כ\"פ ל' הללויה, וכן הללויה הללו את שם הוי' הללו עבדי הוי', וכתי' מי כמוך<sup data-n=\"1057\">20</sup> הוי' מי כמוך נאדר בקודש נורא תהלות יראים להללו. והענין דהנה אנו רואין מי שהוא חכם ה\"ז אצלו בהעלם וע\"י שמשבחים אותו מוציאין מהעלם אל הגילוי<sup data-n=\"1058\">21</sup>, וכמו\"כ מי שהוא חסדן או נדבן, וזה שייך באדם שהוא בעל מדות אך למעלה דלאו מכל אינון מדות איהו כלל, וזהו ויאמר אלקים אל משה ויאמר אליו אני הוי', אלקים והוי' הם מדות החסד ומדות הדין אבל בחי' לאו מכא\"מ איהו כלל ומשם יומשך זהו ע\"י ההילול והשבח וזהו הללויה הללו עבדי הוי' הללו שם הוי', הללויה היינו שיומשך [שיהי'] י\"ה<sup data-n=\"1059\">22</sup> הללו שם הוי' שיומשך גם ו\"ה וזהו ע\"י עבדי הוי' שיהי' עבודה, וזהו שם הוי' דלתתא אך שם הוי' דלעילא שם אינו שייך הילול ושבח אלא הודאה שמודים לבחי' זו. וזהו דכתיב גבי חנוכה וקבעו בהלל והודאה<sup data-n=\"1060\">23</sup>, הלל היינו לשם הוי' דלתתא, והודאה היינו שם הוי' דלעילא ובבחי' זו יראים להללו.\n<b>וזהו</b> וארא אל אברהם ואל יצחק ואל יעקב באל שדי ושמי הוי' לא נודעתי להם, שגבי האבות הי' שם הוי' ע\"י שם שדי שא' לעולמו די אבל ע\"י מצות מאיר שם הוי' דלעילא. וזהו לריח שמניך טובים, כל המצות שעשו האבות ריחות שאינו עצמיות, דלגבי איסורי מאכל ריחא לאו מילתא, אבל אנו שמן תורק שמך דבר שמריקין מכלי לכלי, שע\"י המצות ממשיכים מש' הוי' דלעילא.",[["1054","17","<b>דהנברא אינו יכול להגיע רק אל המקור</b>: ראה סה\"מ תרכ\"ט ע' ריא. תרל\"ב ח\"א ע' קיז. וש\"נ."],["1055","18","<b>מתן תורה שהוא מתנה</b>: ראה אוה\"ת תשא ע' א'תתקסו ואילך. סה\"מ תרכ\"ז ע' קס ואילך. וש\"נ."],["1056","19","<b>מפני שעשי' לעילא</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' כה ואילך. על מארז\"ל ע' קפט ואילך וע' קצט ואילך. ביאוה\"ז לאדהאמ\"צ יא, ב ואילך. אוה\"ת וירא (כרך ב) תשנד, א ואילך."],["1057","20","<b>דהנה כתיב הללויה הללו עבדי ה'. . וכתיב מי כמוך</b>: ראה גם אוה\"ת בשלח ע' תתקמח-ט. ע' תקנג ואילך. סה\"מ תרכ\"ו ע' יח-ט. תרכ\"ז ע' תפח."],["1058","21","<b>וע\"י שמשבחין אותו מוציאין מהעלם אל הגילוי</b>: ראה בהנסמן בכ\"ז לעיל במאמר ס\"ע קיד ואילך."],["1059","22","<b>הללוי' היינו שיומשך </b>[שיהי']<b> י\"ה</b>: כ\"ה בגוכי\"ק. וראה גם תו\"א וישב ל, א. שערי אורה יט, א."],["1060","23","<b>וזהו דכתיב גבי חנוכה וקבעו בהלל והודאה</b>: ראה תו\"א וישב ל, א. שערי אורה כא, ב ואילך. אוה\"ת חנוכה (כרך ה) תתקלט, ב. תתקמ, א."]]],[2000460346,"<h3>ששה המה מלכות</h3>\n<b>ש\"פ צו ט\"ל, לפ\"ק.</b>\n<b>ששים</b> המה מלכות<sup data-n=\"1061\">1</sup> שמונים פלגשים ועלמות אין מספר אחת היא יונתי תמתי, משמע מזה דכנס\"י למעלה מתושבע\"פ דששים המה כו' ס' מסכתות, שמונים כו' ברייתות, עלמות כו' הלכות התורה. ובזהר אי' ישראל מתקשרין באורייתא ואורייתא בקוב\"ה הרי שהם מתקשרי' ע\"י אמצעות התורה. והענין דהנה נת\"ל דשמי הוי' לא נודעתי להם היינו הוי' דלעילא ולכן א' נודעתי, אבל שם הוי' דלתתא האיר גבי האבות, וע\"י מצות ממשיכים הוי' דלעילא. וצ\"ל מהו התשובה על טענתו שא' אלה למה כו', נטלתי ספר בראשית והסתכלתי בו מעשה כו' בדין הי' דין אמת הי' אבל אלו מה חטאו. והענין דכדי שיהי' מ\"ת צ\"ל תחילה מצרים שהוא אבן בוחן. והנה אי' במדרש ע\"פ זית רענן יפה פרי תואר קרא ה' שמך שישראל נמשלו לזית, וצ\"ל והלא יש אילנות נעים ומשובחים יותר שישראל נמשלים להם ולמה נמשלו לזית, אלא מה הזית מגרגרין אותו וכותשין אותו כו' כך ישראל כו' עושין תשובה כמ\"ש ויאנחו בנ\"י מן העבודה ויזעקו ותעל שועתם אל אלקים, וכתי' בצר לך ומצאוך, ובקשתם את ה' אלקיך, כי אל רחום ה' אלקיך, הה\"ד זית רענן יפה כו'. והענין דהנה אי' בפע\"ח דאותם שנשתעבדו במצרים הם דור הפלגה<sup data-n=\"1062\">2</sup> דכתי' ותהי להם הלבנה לאבן והחמר לחמר, ולכן נשתעבדו במצרים והזיכוך הי' בחומר ולבנים. וי\"ל ע\"ז מהמשנה דדור הפלגה אין להם חלק לעוה\"ב<sup data-n=\"1063\">3</sup>, והענין דהנה עוה\"ב שהוזכר במשנה כאן הוא עולם התחי' שיתלבשו נשמות בגופים וזה אין להם כו' אך תיקון נשמתם יש להם.\n<b>והענין</b> דהנה כתי' וירד ה' לראות העיר והמגדל אשר בנו בני האדם ואי' במדרש אמר ר' ברכי' וכי בני חמריא וגמליא אינון אלא בני דאדם קדמאה והם נשמות גבוהות שנפלו בשבירה (הגה נר' שהם אותן נשמות שנולדו באותן ק\"ל שנה עכ\"ה<sup data-n=\"1064\">4</sup>) וכמו פני ארי' שבמרכבה שהוא מדריגה גבוה ולמטה הוא חי' טמאה טורף ודורס והיינו מה שנפל בשבירה<sup data-n=\"1065\">5</sup>. וענין העיר והמגדל צ\"ל בקדושה דעיר הוא קבוץ מבתים הרבה ומקבוץ אבנים הרבה נעשה בית, אבנים הם אותיות, שני אבנים בונות",[["1061","1","<b>ששים המה מלכות</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ”אך הנה כדי שיוכלו לקבל התורה\" לעיל בהספר ע' קטז. והוא המשך מאמר ד\"ה לריח שמניך שלפני זה. לקמן נד' ג\"כ הנחה נוספת ממאמר זה.\nראה באריכות במ\"מ לעיל בתחילת המאמרים שם ע' קיא וע' קטז."],["1062","2","<b>בפע\"ח דאותם שנשתעבדו במצרים הם דור הפלגה</b>: ראה בארוכה באוה\"ת וארא ע' ב'תקנב."],["1063","3","<b>וי\"ל ע\"ז מהמשנה דדור הפלגה אין להם חלק לעוה\"ב</b>: ראה גם המשך זאת חנוכת המזבח תר\"מ פי\"ד ופי\"ז. סה\"מ תרנ\"ה ס\"ע קג. ובהנסמן ע\"ז עוד לעיל במאמר ע' קיז."],["1064","4","<b>הגה נר' שהם אותן נשמות שנולדו באותן ק\"ל שנה עכ\"ה</b>: ראה במ\"מ לעיל בהמאמר שם."],["1065","5","<b>וכמו פני ארי' שבמרכבה. . שנפל בשבירה</b>: ראה תו\"א וישלח כה, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' סא ואילך. ביאוה\"ז לאדהאמ\"צ ג, ד. אוה\"ת וארא ע' קסד."]]],[2000460347,"שני בתים<sup data-n=\"1066\">6</sup> שלשה אבנים בונות ששה בתים, וזהו גדול הוי' ומהולל מאד בעיר אלקינו אימתי הוא גדול כשהוא בעיר אלקינו [עולם הדיבור] בדבר ה' שמים נעשו, ומגדל הוא מ\"ש מגדל עוז ה' שמו, וזהו נמשך ע\"י ביטול, והם ידעו שצריך לימשך דרך בחי' זו אך לא רצו הביטול ומה עשו ותהי להם הלבנה לאבן, אבן הוא א' ב\"ן<sup data-n=\"1067\">7</sup>, אל\"ף הוא שם מ\"ה הוי' במילוי אלפי\"ן והו\"ע מ\"ה מברר ב\"ן, ותהי להם הלבנה לאבן לבנה הוא מקיף [דנוגה] שמחי' בדרך מקיף והוא כמו השבעת וקבלה מעשיות<sup data-n=\"1068\">8</sup> שהשם פועל אך הוא אינו יודע האיך הוא פועל, והרי החטא גדול מאד לכן אין להם חלק לעוה\"ב. והנה עיר הנדחת ג\"כ אין להם חלק לעוה\"ב, ובזה יש פלוגתא א' אומר לא הי' ולא עתידה להיות אלא דרוש וקבל שכר וא' אומר אני ראיתיה<sup data-n=\"1069\">9</sup>.\n)חסר)",[["1066","6","<b>אבנים הם אותיות שני אבנים בונות שני בתים</b>: ראה בכ\"ז תו\"א ויצא כא, א. כב, א. וארא נו, ב. סה\"מ תרכ\"ז ע' שסה. ובכ\"מ."],["1067","7","<b>אבן הוא א' ב\"ן</b>: ראה שעהיחוה\"א פ\"ז (פד, ב). תו\"א משפטים שם עח, סע\"ב-ג. לקו\"ת ראה כז, ג. ועוד. וראה בהנסמן בכ\"ז בארוכה לעיל בהמאמר."],["1068","8","<b>והוא כמו השבעת וקבלה מעשיות</b>: ראה גם תו\"א נח י, ב. אוה\"ת וארא ע' ב'תקסח. מטות ע' א'רפט. סה\"מ תרל\"ב ח\"ב ע' תקצו. המשך זאת חנוכת המזבח תר\"מ פי\"ז."],["1069","9","<b>אני ראיתיה</b>: ע\"כ נרשם. וראה ההמשך לעיל בהמאמר ס\"ע קיח ואילך. ולהלן בהנחה נוספת."]]],[2000460348,"<h3>ואכלתם אותו בחפזון</h3>\n<b></b><b>בס\"ד חג הפסח ט\"ל לפ\"ק, ליובאוויטש</b>\n<b>ואכלתם</b> אותו בחפזון<sup data-n=\"1070\">1</sup>, כי בחפזון יצאת מארץ מצרים, ואי' במדרש יצ\"מ בחפזון הי' שנא' בחפזון יצאת מארץ מצרים אבל לעתיד כי לא בחפזון תצאו ובמנוסה לא תלכו, משל לסוחר שבא לשרות בפונדק עמד כל היום, בלילה נטל כל אשר לו והלך לו, בבוקר עמדה הפונדקית ואמרה הפרקמטוטוס (הוא הסוחר ע\"ש פרקמטיא) הזה נטל כל אשר לי והלך לו, אמר הפרקמטוטוס מי גרם לי זאת שיצאתי בלילה נשבע אני שלא אצא עוד בלילה, כך ישראל הכינו עצמן לצאת בהשכמה לאחר כמה ימים וירדפו מצרים אחריהם שנטלו כל אשר להם, הגם שבאמת נטלו כל אשר להם, כמ\"ש וינצלו את מצרים, ושאלה אשה משכנתה, שעשאוה כמצולה כו', אך אי' החשבון בגמ' דשכר דס' ריבוא איש שעשו זמן כזה עולה הרבה יותר ממה שנטלו וא\"כ נטלו שלהם, אמר הקב\"ה מי גרם לכם זאת שיצאתם בחפזון לעתיד כי לא בחפזון תצאו. והוא כמ\"ש בזהר ע\"פ כי ימכור איש את בתו לאמה לא תצא כצאת העבדים שקאי על גאולה דלעתיד שלא תצא כצאת העבדים גאולת מצרים. עוד אי'",[["1070","1","<b>ואכלתם אותו בחפזון</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה וככה תאכלו אותו, לעיל בהספר ע' קלח. ולקמן נדפסה ג\"כ הנחה נוספת של המאמר.\nראה המ\"מ באריכות לעיל בתחילת המאמר שם."]]],[2000460349,"במדרש לשעבר הוא וב\"ד<sup data-n=\"1071\">2</sup> שנא' וה' הולך לפניהם, ולעתיד הוא לבדו שנא' כי הולך לפניכם ה' ומאספכם אלקי ישראל. עוד אי' במדרש לשעבר הי' נס בלילה והוא נס עובר, אבל לעתיד הלילה יהי' יום שנא' והי' אור הלבנה כאור החמה הרי שאור הלבנה יהי' כאור החמה, ולא ההפרש בין לילה ויום בלבד אלא מה שהלילה יהי' יום.\n<b>נמצא</b> יש כאן ג' חלוקים לילה, ומה שהלילה יהי' יום, והוא וב\"ד, והוא לבדו, וחפזון, ולא בחפזון. וכל זה תלוי בהוא וב\"ד, כשהוא וב\"ד, ב\"ד היינו אלקים<sup data-n=\"1072\">3</sup> דב\"ד שלמטה נק' אלקים כמ\"ש אשר ירשיעון אלקים וכמו\"כ ב\"ד שלמעלה נק' אלקים ואז צ\"ל בחפזון ובלילה, אך לעתיד כשיהי' הוא לבדו אז יהי' לא בחפזון והלילה יעשה יום.\n<b>והנה</b> עוד חלוק יש בין גאולה דלעתיד לגאולה דמצרים ואפי' גאולת בבל, דהנה אי' במדרש תהלים ע\"פ כי עמך מקור חיים<sup data-n=\"1073\">4</sup> באורך נראה אור, משל הוה עובדא ההוא שהלך בדרך והדליק את הנר וכבה והדליק וכבה אמר עד שאני מתייגע להדליק אמתין עד שיאיר לי השמש, כך במצרים נגאלו ע\"י משה ואהרן וחזרו ונשתעבדו בבבל ונגאלו ע\"י חנני' מישאל ועזרי', וחזרו ונשתעבדו בגלות מוקדון ונגאלו ע\"י מתתי' בן יוחנן כה\"ג חשמונאי ובניו, וחזרו ונשתעבדו, אמרו ישראל עד שאנו מתייגעים נמתין שיגאל אותנו הקב\"ה שנא' אל ה' ויאר לנו. והוא כמ\"ש חבל תחבול שלמת רעיך עד בא השמש תשיבנו לו ואי' במדרש שמש זה משיח כמ\"ש שמש צדקה מרפא כנפי', שאין המשכנתא לעולם אלא בבא השמש תשיבנו לו, והוא חלוק בין נר לשמש. עוד יש חילוק דכל שירה הוא ל' נקבה כמ\"ש אז ישיר משה השירה הזאת וכתי' וידבר דוד את דברי השירה הזאת, אבל לעת\"ל כתי' ביום ההוא יושר השיר הזה ל' זכר, והוא משל כמו אשה שמתעברת ויולדת וחוזרת ומתעברת ויולדת, ענין עיבור ולידה הוא גאולה וגלות<sup data-n=\"1074\">5</sup>, לידה הוא גאולה כמ\"ש חלה וגם ילדה ציון את בני', ועיבור הוא גלות בכל פרשת העיבור יהי' צרכיהם לפניך, אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה יהיו צרכיהם לפניך, והנה נקבה מתעברת וחוזרת ומתעברת, אבל לע\"ל ביום ההוא יושר השיר הזה ל' זכר שאינו שייך עוד עיבור ולידה.\n<b>נמצא</b> יש כאן ה' הפרישים, א', ל' זכר ול' נקבה, ב', נר ושמש, ג', לילה ומה שהלילה יהי' יום, ד', הוא וב\"ד והוא לבדו, ה', חפזון ולא בחפזון, וכל זה תלוי בהוא וב\"ד אז צ\"ל ההנהגה באופן כזה, אבל לעת\"ל שיהי' הוי' אז יהי' באופן אחר.",[["1071","2","<b>במדרש לשעבר הוא וב\"ד</b>: ראה אוה\"ת וירא (כרך ד) תשנה, א."],["1072","3","<b>ב\"ד היינו אלקים</b>: ראה לעיל במ\"מ לעיל שם ע' קלט."],["1073","4","<b>אי' במדרש תהלים ע\"פ כי עמך מקור חיים</b>: ראה גם לעיל שם ע' קכה וע' קלט. וש\"נ."],["1074","5","<b>ענין עיבור ולידה הוא גאולה וגלות</b>: ראה תו\"א וארא נה, א ואילך. נז, ג-ד. ועוד."]]],[2000460350,"<b>דהנה</b> על הוי' כתיב אני ה' לא שניתי שלא יש שום שינוי שנק' אמת<sup data-n=\"1075\">6</sup>, כמו אמת ה' לעולם, ורש\"י פי' על ושמי ה' לא נודעתי להם לא ניכרתי במדת אמיתית שלי. והגם שכל השמות אמת, אך באמת גופא יש מדריגות, אמת לאמיתו ושפת אמת ואמת סתם, ושם הוי' הוא אמת, דענין אמת הוא היפך הכזב, כזב נק' דבר שנחסר כמארז\"ל נהרות המכזבים אחת לשבוע<sup data-n=\"1076\">7</sup> פסולים לקדוש מי חטאת שהוא נק' כזב וכמ\"ש גבי יחזקאל ואני בתוך הגולה על נהר כבר שהי' שם מים<sup data-n=\"1077\">8</sup> אך עכשיו לא יש שם מים דכתיב ונהר יחרב ויבש יחרב בבית ראשון יבש בבית שני, והוא מצד יחוד ו\"ה שהוא לפרקים אבל יחוד י\"ה זווגייהו תדיר מבוע דלא פסיק מימיו לעלמין. וזהו שכ' הר\"ש וברטנורא דכשמכזבין א' ליובל כשרים שהוא בחי' ועל יובל ישלח שרשיו יחוד י\"ה דהם תרין ריעין דלא מתפרשין, מבוע דלא פסיק מימיו לעלמין. וזהו שתורה נק' חיי עולם, וחיי עולם נטע בתוכנו, דאורייתא מחכ' נפקת ושם אינו שייך שינוי, אבל תפלה נק' חיי שעה<sup data-n=\"1078\">9</sup> שהוא יחוד ו\"ה לפרקים. ושרש הענין ושם הגדולה לאה ושם הקטנה רחל, שם ה' גדולה לאה<sup data-n=\"1079\">10</sup> ושם ה' קטנה רחל, ה' גדולה לאה שהיא גדולה במתנותי' כהונה לעולם מלכות בית דוד לעולם, כהונה לעולם דכתי' ברית מלח עולם, דכל דבר יפסד לבד מלח שאינו נפסד, אדרבה כשמולחין איזה דבר במלח מקיימים אותו דבר, לכן כתי' על כהונה ברית מלח עולם, מלכות בית דוד לעולם דכתי' ועבדי דוד נשיא עליהם לעולם, רחל קטנה במתנותי' יוסף לפי שעה, שאול לפי שעה, משכן שילה לפי שעה.\n<b>דהנה</b> אמרז\"ל שאול באחת ועלתה לו<sup data-n=\"1080\">11</sup> דוד בשתים ולא עלתה לו לרעה, דהנה מלכות שאול הי' ע\"פ החכ' ע\"פ טו\"ד, וזהו דכתי' ומשכמו ומעלה גבוה מכל עם, שכם הם מדות כתפין, והמדות שלו היו גבוהים מהראש ומוחין דכלללות ישראל, לכן גזרה חכמתו שהוא יהי' מלך, וכשחטא גזרה חכמתו שלא יהי' מלך. והוא ע\"ד שארז\"ל שאלו לחכ' נפש החוטאת במה תתכפר<sup data-n=\"1081\">12</sup> וא' חטאים תרדוף רעה, שאלו לנבואה וא' נפש החוטאת תמות, וצ\"ל למה החמיר הנבואה יותר מחכ', דחכ' היינו חכ' תתאה, ואנו רואין שכל שלמעלה יותר מקיל יותר, והראי' דשאלו לתורה וא' יביא אשם שאלו להקב\"ה וא' יעשה תשובה, ולמה נבואה מחמיר יותר. אך הנה נבואה הוא נו\"ה, וחכם עדיף מנביא דידוע דידיעת המציאות מלמעלה במדריגה טוב",[["1075","6","<b>כתיב אני ה' לא שניתי שלא יש שום שינוי שנק' אמת</b>: ראה גם לקו\"ת מסעי צג, ב."],["1076","7","<b>כמארז\"ל נהרות המכזבים אחת לשבוע</b>: ראה גם סה\"מ תרכ\"ט ע' קסב. תרל\"ב ח\"א ע' ערה. לקו\"ש ח\"ו ע' 92. וש\"נ."],["1077","8","<b>על נהר כבר שהי' שם מים</b>: ראה אוה\"ת בלק ע' א'לד. נ\"ך (כרך א) ע' שצ ואילך. סה\"מ תרס\"ה ע' קצב. וראה ס' השיחות תנש\"א ח\"א ע' 151."],["1078","9","<b>וזהו שתורה נק' חיי עולם. . אבל תפלה נק' חיי שעה</b>: ראה סידור עם דא\"ח עג, ג ואילך. שערי תשובה ח\"ב כו, א ואילך. סה\"מ תרכ\"ז ע' רצב ואילך. וש\"נ. שלג. שלט. שפט ואילך. תרכ\"ט ע' רמד. וש\"נ."],["1079","10","<b>ושם הגדולה לאה. . שם ה' גדולה לאה</b>: ראה גם סה\"מ תרכ\"ז שם ע' רצב-ג. ס\"ע שפט-שצ."],["1080","11","<b>דהנה ארז\"ל שאול באחת ועלתה לו</b>: ראה בהמ\"מ לעיל בהמאמר ע' קמא."],["1081","12","<b>שאלו לחכ' נפש החוטאת במה תתכפר</b>: ראה גם סה\"מ תרל\"ג ח\"ב ע' תקיח. וש\"נ."]]],[2000460351,"יותר מהשגת המהות מבחי' שלמטה במדריגה, עוי\"ל<sup data-n=\"1082\">13</sup> דה' בחכ' יסד ארץ, שבחי' ארץ הוא מבחי' חכ', אבא יסד ברתא, ולכך חכ' מקיל יותר. ולכך כשחטא גזרה חכמתו שלא יהי' מלך, ולכך רוח רעה מבעתהו, ודוד בב' ולא עלתה לו, דהנה רמה קרני ולא רמה פכי, דוד שנמשח בקרן נמשך מלכותו שאול שנמשח בפך לא נמשך מלכותו, דהנה מלכות דוד הי' מצד בחי' רמה רוממות, ואתה מרום לעולם ה' וכמ\"ש בתפלה כי הוא לבדו מרום וקדוש פועל גבורות כו', כי הוא לבדו עצמותי, מרום כתר, קדוש חכ', פועל גבורות בינה, עושה חדשות חסד, בעל מלחמות גבורה כו' ויש כאן ע\"ס, הרי שמרום הוא כתר והוא מקום שאינו שייך שם שינוי לכן לא עלתה לו. ומפני מה זכה לזה מפני קרן, שהנה יש עוד פי' בקרן ל' קרן זוית<sup data-n=\"1083\">14</sup> דהקרן הוא מחבר ב' כותלים כמו מזרח וצפון, והנה כמה שנמשך מזרח הכל מזרח וכמה שנמשך צפון הכל צפון הנה הקרן בעצמו אינו מציאות והוא מורה על ביטול וזהו דוד שא' אנכי תולעת ולא איש, כי עני ואביון אני, לכן זכה לבחי' רמה, לכן כשרצה דוד לבנות הבהמ\"ק א\"ל הקב\"ה אתה לא תבנה בית לשמי שאם יבנה אותו לא יחרב, ורצה דוד שהוא יבנה, א\"ל הקב\"ה גלוי וידוע לפני שעתידים ישראל לחטוא מוטב שאשפוך חמתי על עצים ועל אבנים ולא אכלה את ישראל, וזהו מפני שדוד הי' בחי' רמה גם במעשה ידיו לא הי' שינויים ואם הי' בונה בהמק\"ד לא הי' נחרב. והנה בזהר נק' בחי' זו עץ חיים אתר דלא אשתני, דכתי' פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם, משמע שאפי' לאחר שאכל מעה\"ד מ\"מ אם הי' אוכל מעה\"ח הי' חי לעולם, ולא רצה זה מפני שהי' קיום גם אל הרע, דהנה ע\"י חטא עה\"ד נתערב הרע והטוב, ולכן ויגרש אותו, שגרש אותו מג\"ע כדי שלא יהי' קיום להרע והוא אתר דלא אשתני, הגם שעה\"ח הוא ת\"ת אך ידוע דת\"ת עולה עד הכתר, ועה\"ד הוא מל', לא שמל' הוא עה\"ד אלא מפני שמל' מברר עה\"ד לכן נק' עה\"ד.\n<b>וזהו</b> ההפרש בין נר לשמש, דהנה גאולת מצרים הי' ע\"י בשר ודם ששייך בו מיתה [שהוא מצד עה\"ד], ואפי' אותן שמתו בעטיו של נחש אינו קיום ואפי' משה לא נמלט מזה, לכן חזרו ונשתעבדו, הגם שבמצרים הי' הוא וב\"ד דבמקום א' אי' אני ובית דיני ובמ\"א אי' הוא ובית דינו וא\"כ הי' גם בחי' הוא, וכמ\"ש לכן אמור לבנ\"י אני הוי', ובמצרים האיר שם הוי' בשם אלקים לא כמ\"ש שמש ומגן הוי' אלקים כמו שהמגן מכסה ומסתיר על ש' הוי' כמו\"כ שם אלקים מכסה ומסתיר על ש' הוי' אבל במצרים א\"א לומר שהרי הי' ניסים שיוצאים מדרכי הטבע לגמרי, דשמש ומגן הוי' אלקים הנה אלקים בגימ' הטבע דעולם כמנהגו נוהג הגם שהוא ג\"כ ניסים תכופין אבל במצרים הי' ניסים שיוצאים מדרכי הטבע לגמרי, אך הוא שילוב הוי' באד' דההתגברות דשם אד', אבל לע\"ל יאיר שם הוי', הגם דבשם הוי' יש מדריגות הוי' הנראה הוי' דסוכ\"ע והוי' דממכ\"ע, מ\"מ הוא שם הוי'.",[["1082","13","<b>עוי\"ל</b>: תיבה זו אינה ברורה בגוכי\"ק."],["1083","14","<b>עוד פי' בקרן ל' קרן זוית</b>: ראה ביאוה\"ז לאדהאמ\"צ קמד, ב ואילך. ולהצ\"צ ע' תסד ואילך. אוה\"ת נ\"ך ע' קלו ואילך. סה\"מ תרכ\"ז ע' קעו. תרכ\"ט ע' לח. רפט. תרל\"ב ח\"א ע' רסח. ח\"ב ע' תקנא."]]],[2000460352,"<b>אך</b> צ\"ל האיך יכולים לקבל שם הוי' והלא זהו ההפרש בין אלקים לכל השמות דכתי' בי' אלקינו, והענין דהוא שילוב אד' בהוי' דההתגברות דשם הוי' ומקבלים זה ע\"י שם אד'. עוי\"ל דהנה אמרז\"ל עתידים צדיקים שיקראו על שמו של הקב\"ה<sup data-n=\"1084\">15</sup> שיהי' שמם הוי', וא\"כ אינו צריכים לצמצום דשם אלקים. וזהו ההפרש בין גאולת מצרים לגאולה דלעתיד, שבמצרים הי' ע\"י שם אלקים, וזהו אור לארבעה עשר<sup data-n=\"1085\">16</sup> בודקין את החמץ לאור הנר שיצ\"מ הוא בחי' נר, אבל לעתיד יהי' בחי' הוי'.",[["1084","15","<b>דהנה אמרז\"ל עתידים צדיקים שיקראו על שמו של הקב\"ה</b>: ראה גם אוה\"ת בראשית (כרך ו) תתרנה, א. דברים ע' י. סה\"מ תרכ\"ט ע' קטו. וש\"נ. תרל\"ב ח\"ב ע' שצב. וש\"נ. תרל\"ח ע' כו. וש\"נ. לקמן ד\"ה ובראשי חדשיכם. וש\"נ."],["1085","16","<b>אור לארבעה עשר</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה והנה יצ\"מ (המשך לד\"ה וככה תאכלו אותו) הנדפס לעיל ע' קמד. וראה בהמ\"מ בתחילת המאמר שם ע' קלח. וראה לקמן הנחה נוספת ממאמר זה."]]],[2000460353,"<h3>אור לארבעה עשר</h3>\n<b>שבת חוה\"מ של פסח ט\"ל</b>\n<b>אור</b> לארבעה עשר בודקין את החמץ לאור הנר. דהנה נת\"ל דיצ\"מ הוא בחי' נר שהוא בחי' אתר דאשתני ולכן הי' ע\"י ב\"ו, והנה צ\"ל דגבי יצ\"מ כתי' עד שנגלה עליהם מלך מלכי המלכים הקב\"ה וגאלם, מלכים הוא ז\"א ומל' דאצי', מלכי המלכים הוא חו\"ב, מלך מלכי המלכים הוא כתר מל', והאיך אומרים שהוא בחי' נר. אך הענין הוא דהנה גבי מצות כתי' כי נר מצוה<sup data-n=\"1086\">1</sup> ותורה אור, נק' מצות נר ותורה נק' אור, וצ\"ל ג\"כ דהלא תרי\"ג מצות דאורייתא וז' מצות דרבנן הם תר\"ך עמודי אור והאיך אומר שהוא בחי' נר, ולכן לע\"ל מעשה גדול<sup data-n=\"1087\">2</sup> מפני שהם תר\"ך עמודי אור. והנה אמרז\"ל את זו דרש ר' מנחם ב\"ר יוסי מאי דכתיב כי נר מצוה ותורה אור המשיל מצוה לנר ותורה לאור מה נר לפי שעה כך מצות אינו מגין אלא לפי שעה, ומה אור לעולם כך תורה מגינה לעולם, דהנה אמרז\"ל שכר מצוה בהאי עלמא ליכא, מה דשכר מצוה מצוה זה אינו בעוה\"ז, ומשארז\"ל אלו שאוכלין פירותיהן בעוה\"ז זה רק פרטי מצות אבל כל המצות השכר בעוה\"ב, משא\"כ תורה כנגד כולם בעוה\"ז.\n<b>ד\"א</b> עבירה מכבה מצוה ואין עבירה מכבה תורה, אינו שייך לומר שמה שמכבה מצוה היינו עצם המצוה<sup data-n=\"1088\">3</sup>, שאינו מכבה כלל, דמי שיש לו מחצה מצות ומחצה",[["1086","1","<b>כי נר מצוה</b>: ראה גם לעיל ע' קכג ואילך."],["1087","2","<b>לע\"ל מעשה גדול</b>: ראה סה\"מ תרכ\"ט ע' כד. תרל\"ג ח\"ב ע' תפד. תרל\"ד ע' פט. לעיל ד\"ה ושננתם. סה\"מ מלוקט ח\"ד ע' קיא וע' קיט. וש\"נ."],["1088","3","<b>אינו שייך לומר שמה שמכבה מצוה היינו עצם המצוה</b>: ראה גם לקו\"ת פ' ראה כ, א. כב, א. דרך חיים לאדהאמ\"צ קי, ג. אוה\"ת ראה ע' תרפא."]]],[2000460354,"עבירות ה\"ה מניח לו עוה\"ב אלא שמענישין אותו קודם הרי שאין עבירה מכבה עצם המצוה, אך הענין דהנה מהמצוה נעשה מקיף שמקרב את הנפש לאלקות, דהנה אנו אומרים המלך המרומם לבדו מאז<sup data-n=\"1089\">4</sup>, שהוא מרומם ונשגב מגדר עולמות ואינו שייך שיהי' מקור לעולמות, והעולמות הם רק מבחי' מלכותך מלכות כל עולמים, מלך שמו נקרא עליהם, ואח\"כ אומרים אדון עוזינו צור משגבינו מגן ישענו משגב בעדינו ד' מדריגות, דהנה תחילה אומרים ברחמיך הרבים רחם עלינו דהנה כללות העולמות הם משם והארה בעלמא והנשמה היא חלק ה' עמו וירדה למטה ומעורר ר\"ר עלי' וזהו ברחמיך הרבים רחם עלינו, אדון עוזינו היינו שמקבל עליו עול מלכות שמים וכמארז\"ל קבלו מלכותי ואח\"כ קבלו גזרותי, ואח\"כ אומרים ג' מקיפים פרטים צור משגבינו מגן ישענו משגב בעדינו<sup data-n=\"1090\">5</sup> והם ג' עולמות בי\"ע ג' לבושים מחדו\"מ וג' מדריגות נר\"ן שבנפש, ולכן במצות יש מצות שהם במח' כוונות המצות אם כיוון לבו יצא, ויש שהם בדיבור ורוב מצות הם במעשה, והמקיף פועל שיהי' מצוה גוררת מצוה שיעשה עוד מצוה, וזהו דכתי' והלך לפניך צדקיך וכבוד ה' יאספך, כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו כי נשמור לעשות כל המצוה הזאת, וכבוד ה' יאספך פי' שכבוד ה' מאסף ומקרב הנפש אל אלקות (הגה נראה שב' דברים פועל המקיף שגוררת עוד מצוה ומאסף הנפש אל אלקות עכ\"ה) וזהו עבירה מכבה מצוה עצם המצוה אינו מכבה אלא מכבה המקיף, אבל תורה אפי' המקיף אינו מכבה.\n<b>עוי\"ל</b> עבירה מכבה מצוה כו' דהנה מה שהמצות נק' נר דרמ\"ח מצות ותרין דרועין נק' נר<sup data-n=\"1091\">6</sup> והוא אהוי\"ר והו\"ע באתעדל\"ת אתעדל\"ע אבל תורה הוא אתעדל\"ע שאינו תלוי באתעדל\"ת ולכן עבירה מכבה מצוה אבל תורה אינו מכבה, דהנה כתי' אותי עזבו ותורתי לא שמרו ואמרז\"ל הלואי אותי עזבו ותורתי שמרו המאור שבה מחזיר למוטב, הרי לא די מה שאינו מכבה אלא מחזיר למוטב והוא אור תורה ומה שהוא מאור זה מחזיר למוטב<sup data-n=\"1092\">7</sup>. וזהו שהמצות נק' נר הגם שהם תר\"ך עמודי אור זהו השרש שלהם אבל עצם המצות הם מצות המלך וכמאמר קבלו מלכותי ואח\"כ קבלו גזרותי, והנה האדם מדליק את הנר וצריכים להמשיך בתוכו שמן ואור ופתילה, שמן חכ' אור כתר ופתילה יסוד והוא יחוד ו\"ה.\n<b>ועתה</b> צ\"ל ענין החפזון<sup data-n=\"1093\">8</sup> דכתיב ואכלתם אותו בחפזון, כי בחפזון יצאת מארץ מצרים, מהו המעלה דחפזון ולעתיד לא בחפזון תצאו. והענין דהנה במצרים",[["1089","4","<b>דהנה אנו אומרים המלך המרומם לבדו מאז</b>: ראה בכ\"ז גם לקו\"ת שלח לח, ד ואילך. ובכ\"מ."],["1090","5","<b>ואח\"כ אומרים ג' מקיפים פרטים צור משגבינו מגן ישענו משגב בעדינו</b>: ראה לקו\"ת שלח שם. בהר מד, ב. נצבים מח, ג. אוה\"ת סידור ע' קכב ואילך."],["1091","6","<b>דרמ\"ח מצות ותרין דרועין נק' נר</b>: ראה לקו\"ת פ' ראה שם כ, א."],["1092","7","<b>ומה שהוא מאור זה מחזיר למוטב</b>: ראה בכ\"ז סה\"מ תרכ\"ט ע' רצ. ועוד."],["1093","8","<b>ועתה צ\"ל ענין החפזון</b>: ראה גם לעיל ע' קכח ואילך."]]],[2000460355,"הי' בלילה וכמשנת\"ל בעוה\"ז נס בלילה כו' וכמ\"ש ויהי בחצי הלילה. והנה הלילה נק' ליל שמורים ל' רבים מפני שיש ב' פי', א' ל' שימור דמדת לילה צריכה שמור, דלילה הוא בחי' מל' שהוא מקור דבי\"ע ששם יש רע דעשי' רובו רע ויצי' מחצה על מחצה ובריאה רובו טוב, וצריכה שמירה, אבל מדת יום<sup data-n=\"1094\">9</sup> א\"צ שמירה דבאצי' לא יש רע דלא יגורך רע, הגם שיש קליפה נגד אצי' מעמדה בבריאה<sup data-n=\"1095\">10</sup>, וזהו ג' אשמורות הוה לילה ראשונה חמור נוער שני' כלבים צועקים וזה מורה על קליפות<sup data-n=\"1096\">11</sup>, וזהו דאי' בזוהר אית תליסר עלין דסחרין לשושנה והו\"ע השמירה וה' עלין תקיפין לאגנאה דמל' צריכה שימור. וזהו דבברכות אירוסין ברכה ראשונה אינה חותמת בברוך<sup data-n=\"1097\">12</sup> ושני' פותח בברוך וחותם בברוך, מפני שהוא אדם וחוה יום ולילה כמ\"ש יום ליום יביע אומר ולילה ללילה יחוה דעת, לכן חותם בברוך מפני שצריך שמירה יותר. וכמו\"כ הו\"ע תושב\"כ ותושבע\"פ דהנה כתי' ויהי שם עם ה' ארבעים יום וארבעים לילה ואי' בילקוט מנין ידע אימתי יום ואימתי לילה והלא נהורא עמי' שרא אלא כשלמד ד' עמו מקרא ידע שהוא יום<sup data-n=\"1098\">13</sup> וכשלמד עמו משנה ידע שהוא לילה, ולכן משנה צריך שמירה יותר, דכשלומד פ' חומש לא יתגאה מזה אבל כשלומד פוסקים ומשנה יש מזה גסות ולהתייהר לכן צריך שמירה יותר, וזהו שמור זו משנה, וזהו ליל שמורים.\n<b>ב'</b> כמו ואביו שמר את הדבר, פי' המתין, ובגמ' נמצא ג\"כ הל' משתמרת לביאה, דהנה כתי' עד שנגלה עליהם מלך מלכי המלכים הקב\"ה וגאלם והו\"ע שנמשך מסוכ\"ע בממכ\"ע, וזהו ליל שמורים שממתנת על היחוד, וזהו מצה שמורה שממתנת שיומשך בה מבחי' סוכ\"ע, וזהו שנק' לחם עני לחם עוני כמו העני ממתין על העשיר לקבל ממנו כמו\"כ המצה ממתין שיומשך בה מסוכ\"ע, וזהו דכורא זמין לאתחברא עמה<sup data-n=\"1099\">14</sup> שומרת על היחוד, וזהו זכור לדכורא שמור לנוק'<sup data-n=\"1100\">15</sup>.\n<b>והנה</b> ב' הפי' עולים בקנה א' דכשיש זווג ממכ\"ע עם סוכ\"ע אז הקנאה גדול מאד וצריכים שמירה, ע\"ד דאי' בזהר ועד בחילופי אתוון אחד דלא תשלוט בו עין הרע, דאחד הוא יחוד דיחו\"ע ושם אינו שייך ע\"ה אבל ועד הוא מ\"ש כגוונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד ושייך ע\"ה לכן",[["1094","9","<b>דלילה הוא בחי' מל'. . אבל מדת יום</b>: ראה תו\"א מקץ לז, א ואילך. לז, ד ואילך. ובכ\"מ."],["1095","10","<b>הגם שיש קליפה נגד אצי' מעמדה בבריאה</b>: ראה סה\"מ תרכ\"ט ע' קלט. וש\"נ."],["1096","11","<b>ג' אשמורות הוה לילה. . וזה מורה על קליפות</b>: ראה גם סה\"מ תרכ\"ו ע' שכד. תרכ\"ט ע' קמב. תרל\"ב ח\"א ע' כד וע' לא. וש\"נ."],["1097","12","<b>וזהו דבברכות אירוסין ברכה ראשונה אינה חותמת בברוך</b>: ראה בארוכה תו\"א בראשית ו, ב ואילך. סה\"מ תרל\"ח ע' קפה ואילך."],["1098","13","<b>ואי' בילקוט. . כשלמד ה' עמו מקרא ידע שהוא יום</b>: ראה גם יהל אור ע' סב ואילך. סה\"מ תרל\"ב ח\"א ע' עדר. ובכ\"מ."],["1099","14","<b>וזהו דכורא זמין לאתחברא עמה</b>: בזח\"ב לח, ב: ואע\"ג דכתיב בי' שמורים דכר הוה זמין לאתחברא עמה."],["1100","15","<b>וזהו זכור לדכורא שמור לנוקבא</b>: ראה תו\"א יתרו עא, ג-ד. סה\"מ תרכ\"ז ע' קל."]]],[2000460356,"ועד בחילופי אתוון שמכסה על היחוד כדי שלא תשלוט בו ע\"ה. וגם כדאי' במשנה בעשרה ניסים שהי' במקדש שלא אירע קרי לכה\"ג ביוהכ\"פ וצ\"ל מהו החידוש והלא הכה\"ג הי' אדם גדול בישראל והי' מפרישין אותו ז' ימים ומזרזין אותו ובמקדש וביוהכ\"פ שכל ישראל<sup data-n=\"1101\">16</sup> [עושים תשובה] ומהו החידוש, אלא זהו החידוש שכה\"ג במקדש וביוה\"כ שהקנאה גדולה מאד מ\"מ לא ראה כו' זהו הנס. וזהו כי ברח העם ואי' בתניא<sup data-n=\"1102\">17</sup> למה הי' להם לברוח והלא אם היו אומרים לפרעה שיניחם לעולם הי' מניחם שהרי הי' מוכרח, אלא שישראל היו משוקעים במ\"ט שערי טומאה וצריכים לברוח מהרע שלא יומשך אחר הרע ח\"ו. והבריחה הוא בתורה וכמ\"ש פנו וסעו לכם צפונה וכ' במדרש הצפינו עצמכם בד\"ת, וזהו דרך שלשת ימים נלך הוא לקשר ג' לבושי מחדו\"מ בתורה.\n<b>וזהו</b> שאמרז\"ל בראתי יצה\"ר בראתי תורה תבלין, אם פגע בך מנוול זה משכהו לבהמ\"ד אפילו אם אבן הוא נמוח וכתי' אם רעב שונאך האכילהו לחם, שונאך הוא היצה\"ר, ומנוול פירש\"י יצה\"ר, האכילהו לחם היינו תורה. וזהו ענין החיפזון לברוח מהרע, ובשל\"ה הקשה מהו המעלה דחפזון<sup data-n=\"1103\">18</sup> ועכשיו מתורץ מפני שצריכים לברוח מהרע. מ\"מ כשאינם צריכים להחפזון הוא מעלה היותר גבוה, דהנה ענין החפזון הוא כמ\"ש על בני גד ובני ראובן נחלה מבוהלת בראשונה, דבארץ כנען יותר טוב והם בחרו בעבר הירדן וזהו שא' יהושע טמאה ארץ נחלתכם, והנה העיקר החטא דאדה\"ר הי' מה שנחפז להזדווג קודם השבת שאם הי' ממתין עד השבת הי' כל פריו קדש, אך אינו דומה דשם החטא שנחפז בזמן שאינו צריכין להחפזון, דאשר פריו יתן בעתו הוא עונת ת\"ח, והוא נחפז להזדווג קודם זהו החטא, אבל כשצריכים חפזון הרי יש מעלה בחפזון שבורח מהרע, אבל לעתיד כתיב ואת רוח הטומאה אעביר מן הארץ ולא יהי' חפזון<sup data-n=\"1104\">19</sup>, ולכן חסידים הראשונים היו שוהין תשע שעות בתפלתן שעי\"ז יש קיום להאהוי\"ר. ובכלל הוא ההפרש בין צדיק לבינוני<sup data-n=\"1105\">20</sup> דבינוני שיש בו רע צ\"ל חיפזון לברוח מהרע אפי' בתפלה מפני מח\"ז והבריחה הוא להתקשר בתורה, אבל צדיק גמור כמו חסידים הראשונים שאין בו רע א\"צ חפזון, הגם שאמרז\"ל זריזים מקדימין למצות היינו שהזריזות צ\"ל קודם המצוה אבל עצם המצוה צ\"ל במתון ובישוב הדעת.\n<b>והנה</b> לע\"ל הוא העלי' מחיצוניות הלב לפנימיות הלב או מבחי' כמים הפנים לאהבה דבכל מאדך, וזהו ומל ה' אלקיך את לבבך דהנה כתי' ומלתם את",[["1101","16","<b>שכל ישראל </b>[עושים תשובה]: כ\"ה בגוכי\"ק עם חצאי מוסגרים. [וראה בהמ\"מ לעיל ד\"ה וידבר גו' חוקת, קרוב לתחילתו]."],["1102","17","<b>וזהו כי ברח העם ואי' בתניא</b>: פל\"א (מ, ב)."],["1103","18","<b>ובשל\"ה הקשה מהו המעלה דחפזון</b>: ראה בכ\"ז גם לעיל ע' קלא ואילך. וע' קכט ואילך."],["1104","19","<b>אבל לעתיד כתיב. . ולא יהי' חפזון</b>: ראה גם לקו\"ש חכ\"ט ע' 341 ואילך."],["1105","20","<b>ובכלל הוא ההפרש בין צדיק לבינוני</b>: ראה תניא פ\"י ופי\"ב."]]],[2000460357,"ערלת לבבכם<sup data-n=\"1106\">21</sup>, ערלה הוא רע, דבערלה יש אותיות רע, וצריכים למול את ערלת לבבכם, אבל ומל ה' כו' שם לא נמצא רע שאין שם רע וזה א\"א להיות ע\"י האדם וכמ\"ש ומל ה' אלקיך כו', וזהו\"ע גאולה דלעתיד לא בחפזון שהוא מבחי' אתר דלא משתני.",[["1106","21","<b>וזהו ומל ה' אלקיך. . דהנה כתי' ומלתם את ערלת לבבכם</b>: ראה אגה\"ק ס\"ד (קה, ב ואילך). לקו\"ת פ' ראה יח, ג-ד. סה\"מ תרל\"ג ח\"ב ע' שצט ואילך. וע' תמט ואילך. ובכ\"מ."]]],[2000460358,"<h3>אז ישיר משה</h3>\n<b>שביעי ש\"פ ט\"ל</b>\n<b>אז</b> ישיר משה<sup data-n=\"1107\">1</sup> ובנ\"י את השירה הזאת לה' ויאמרו לאמר אשירה להוי' כי גאה גאה סוס ורכבו רמה בים, ואי' בילקוט כל פרקמטי' דמשה הי' באז, קנטורי' באז שנא' ומאז באתי אל פרעה שירתו באז שנא' אז ישיר משה, וצ\"ל מהו המעלה דאז דקאמר שירתו באז. והנה מה שיש לדקדק בפסוק זה הוא אומרו ישיר מאחר שחשיב משה ובנ\"י הו\"ל ישירו, שאם הי' חושבם כא' ניחא אומרו ישיר וכמו אז ישיר ישראל עלי באר ענו לה אבל מאחר שחושבם נפרדים הול\"ל ישירו. ועוד צ\"ל אומרו ויאמרו לומר מהו הכפל ל' והול\"ל ויאמרו אשירה לה' כו'. והענין דהנה אמרז\"ל<sup data-n=\"1108\">2</sup> על ג' דברים העולם עומד<sup data-n=\"1109\">3</sup> על תורה ועל עבודה ועל גמ\"ח, תורה דכתי' אם לא בריתי יומם ולילה חוקות שמו\"א לא שמתי הרי שהתורה נק' בריתי, עבודה דכתיב לנטוע שמים וליסוד ארץ דעבודה הוא קרבנות וכתי' והנה סולם מוצב ארצה וראשו מגיע השמימה סולם דא כבש המזבח מוצב ארצה שריחו עולה לשמים הרי שהקרבנות נק' [שמים]<sup data-n=\"1110\">4</sup>, גמ\"ח דכתי' וחסד ה' מעולם עד עולם, וצ\"ל מהו\"ע העולם עומד. והנה צ\"ל ענין עבודה וגמ\"ח, דהנה עבודה הוא קרבנות והיו מקריבין בהמה ע\"ג המזבח והי' יורד אש מלמעלה ואוכל הקרבן והוא המשכה מלמעלה, ובזהר אי' ארי' דאכיל קורבנין<sup data-n=\"1111\">5</sup> שהאש הי' בדמות ארי' והוא בחי' חסד, והוא ג\"כ ענין מ\"ש וחסד ה' מעולם עד עולם, ועכשיו תפלה במקום קרבנות תקנו [הו\"ע] אה\"ר הבאה מלמעלה, דהנה ענין התפלה הוא הקרבת הנה\"ב ונמשך מלמעלמ\"ט, והיכן מרומז ההמשכה בתפלה הוא מה שאומרים ברוך אתה הוי' הוא ההמשכה מלמעלמ\"ט, וכמו ברוך הוי' מעולם",[["1107","1","<b>אז ישיר משה</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה זה הנדפס לעיל ע' קנב. וע\"ש בהמ\"מ בתחילת המאמר. וראה לקמן הנחה נוספת ממאמר זה."],["1108","2","<b>והענין דהנה ארז\"ל</b>: לעיל במאמר (ס\"ע קנב, וכן לקמן בהנחה ב') נוסף כאן עוד קושיא ”הנה ענין קי\"ס הי' בכדי שידעו מצרים כי אני ה' וצ\"ל דהלא כתיב ולא נשאר בהם עד אחד\". ובמאמר שם לא נת' תירוץ על שאלה זו (וע\"ש בהמ\"מ). ואפשר מטעם זה לא נרשמה שאלה זו בהנחה כאן."],["1109","3","<b>דהנה ארז\"ל על ג' דברים העולם עומד</b>: ראה ד\"ה אז ישיר בתו\"א בשלח סב, ב."],["1110","4","<b>הרי שקרבנות נק' </b>[שמים]: כ\"ה בגוכי\"ק בתוך מוסגרים, ועד\"ז כל המוסגרים לקמן במאמר."],["1111","5","<b>ובזהר אי' ארי' דאכיל קורבנין</b>: ראה לקו\"ת במדבר יא, א."]]],[2000460359,"ועד עולם הוא המשכה מעלמא דאתכסייא לעלמדאת\"ג כמו\"כ ברוך אתה ה' הוא המשכה מעלדאת\"כ לעלדאת\"ג.\n<b>והנה</b> עלמא דאתכ' ועלדאת\"ג הוא ים וארץ<sup data-n=\"1112\">6</sup>, דכל מה שיש ביבשה יש בים, אלא ברואים שבים הם מובלעים במי הים וברואים שביבשה אינם מובלעים בה, דהנה ברואים שבים הים מכסה עליהם וברואים שביבשה הם נראים ונגלים, מכוסה הוא עלדאת\"כ ונראה ונגלה הוא עלדאת\"ג, ובקבלת החיות ברואים שבים הם מובלעים במי הים וכשפורשים מהים הם מתים, וברואים שביבשה אף שהם מקבלים חיות מהארץ כמו צומח שהוא שייך ליבשה יותר משאר כל הדברים היינו עד שנגדל אבל אח\"כ א\"צ להארץ כלל, ומכ\"ש חי ומדבר הגם שהם מקבלים חיות מהארץ וכמ\"ש ארץ ממנה יצא לחם מ\"מ הם חיים כשהם באויר או שטים ע\"פ המים, ובאדם הוא ענין מחשבה ודבור, דיבור הוא גילוי לזולתו שזולתו מבין מזה ונראה כאילו הוא נפרד, אבל מחשבה הוא גילוי העלם העצמי לגבי עצמו הגם שהוא גילוי אך הוא לגבי עצמו, וכמו שהוא בעצמותו הוא בחי' עלדאת\"כ. והנה משה הי' מעלדאת\"כ<sup data-n=\"1113\">7</sup> שנא' מן המים משיתיהו רק ירד<sup data-n=\"1114\">8</sup> [ירד: נפל] לעלמא דאתגלייא, ולכן אמר כבד פה וכבד לשון מפני שהי' מעלדאת\"כ, הגם שירד לעלדאת\"ג אך מפני שהוא עלדאת\"כ לא הי' יכול להיות בדיבור. וזהו\"ע עבודת הלוים שהוא בחי' המשכה<sup data-n=\"1115\">9</sup> מעלדאת\"כ לעלמדאת\"ג, אך עבודת הלוים הוא מ\"ש ועבד הלוי הוא, הוא, הוא עלדאת\"כ אך הוא [לארמא קלא] העלאה עלדאת\"ג בעלדאת\"כ, דענין שיר וזמרה הוא עד\"מ מי שמתבונן באיזה התבוננות ומתפעל מזה אך כשהוא משורר נגון ההתפעלות ניכרת יותר<sup data-n=\"1116\">10</sup>, הגם שגם בעת שהתבונן אפי' בלא נגון נתפעל ג\"כ אך ע\"י הנגון ההתפעלות ניכרת יותר, דנגון הוא תנועה וכל תנועה מוליד חום ומוציא ההתפעלות מהעלם אל הגילוי. וזהו כל בעלי השיר יוצאים בשיר<sup data-n=\"1117\">11</sup> וקאי על מלאכים ונשמות, דמלאך כשצריך לצאת מהגוף, דגם מלאכים יש להם גופים<sup data-n=\"1118\">12</sup> כמ\"ש עושה",[["1112","6","<b>והנה עלמא דאתכ' ועלדאת\"ג הוא ים וארץ</b>: ראה תו\"א בשלח שם סב, ב-ג. ביאוה\"ז לאדהאמ\"צ מב, ג ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנה ואילך וע' רסז."],["1113","7","<b>והנה משה הי' מעלדאת\"כ</b>: ראה בארוכה תו\"א שמות נא, ד ואילך. סידור עם דא\"ח קי, ג-ד. סה\"מ תרכ\"ז ע' ב."],["1114","8","<b>ירד</b>: נפל]: כן נכתב בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע בצידי הגליון. ואולי ר\"ל שפעם א אמר כ\"ק אדמו\"ר מהר\"ש: ירד, ובעת חזרת המאמר בפעם ב' אמר: נפל."],["1115","9","<b>וזהו\"ע עבודת הלוים שהוא בחי' המשכה</b>: כ\"ה בגוכי\"ק. ולעיל במאמר ס\"ע קנג (וכן לקמן בהנחה ב'): הכהנים. [דכהנים המשכה, ולויים העלאה]. וראה גם המשך הלשון במאמר כאן. וראה בכ\"ז בהמ\"מ לעיל שם."],["1116","10","<b>אך כשהוא משורר נגון ההתפעלות ניכרת יותר</b>: ראה תו\"א בשלח שם סב, ג. מאמרי אדה\"ז תקס\"ג ח\"א ע' קס. תו\"א מקץ לז, ד. לקו\"ת צו ט, ג. ועוד."],["1117","11","<b>וזהו כל בעלי השיר יוצאים בשיר</b>: ראה בכ\"ז לקו\"ת ברכה צח, א. סידור עם דא\"ח ערה, ד. מאמרי אדה\"ז על מארז\"ל ע' קכ. אוה\"ת בשלח ע' תצד. סה\"מ תרל\"ג ח\"א ע' רסט. וש\"נ."],["1118","12","<b>דגם מלאכים יש להם גופים</b>: ראה לקו\"ת ברכה, וסה\"מ תרל\"ג ח\"א שם. וראה בהמובא ע\"ז בלקו\"ש ח\"ט ע' 405. וש\"נ."]]],[2000460360,"מלאכיו רוחות משרתיו אש לוהט הרי שיש להם גוף רק דיש ד' יסודות דצח\"מ ומלאכים גופם מב' יסודות אש ורוח שהם דקים יותר וגבוהים יותר, ולכן כשצריכים לצאת מהגוף זהו ע\"י שיר, וכמו\"כ נשמות שיושבים בג\"ע ומשיגים השגות ה\"ז הגבלה דכל השגה הוא הגבלה, וכשצריכים לעלות מהשגה זו להשגה שלמעלה ממנה זהו ע\"י שיר, וזהו\"ע שירת הלוים העלאה מעלדאת\"ג לעלדאת\"כ.\n<b>ועתה</b> יובן שירת הים<sup data-n=\"1119\">13</sup> דכתי' אז ישיר משה השירה הזאת וצ\"ל מהו הזאת, והענין דהנה כתי' לזאת יקרא אשה כי מאיש לוקחה זאת, איש זה הקב\"ה כמ\"ש בשירה גופא ה' איש מלחמה, ואשה הוא מה שמקבל מאיש, מאיש לוקחה זאת והוא מל' כנס\"י מקור נש\"י<sup data-n=\"1120\">14</sup>, וצ\"ל מה שייך במל' שירה, במלאכים שנקראים נפרדים שייך שירה לצאת מהגבלת הגוף אבל במל' שהיא ספי' מע\"ס דאצי' מה שייך שירה<sup data-n=\"1121\">15</sup>, ואי' בזהר כ\"פ נהורא תתאה קארי תדיר לנהו\"ע ולא שכיך וכתי' אלקים אל דמי לך אל תחרש ואל תשקוט הרי מצינו ענין זה במל', אך איך שייך זה במל'. והענין דהנה איהו וחיוהי חד איהו וגרמוהי חד, חיוהי הם האורות וגרמוהי כלים<sup data-n=\"1122\">16</sup>, דכל השמות חכ' חסד היינו כלי החכ' כלי החסד דהאור הוא פשוט ושוה בכל הספי'<sup data-n=\"1123\">17</sup>, ופעמים נק' גופים וכמאמר וכד אנת תסתלק<sup data-n=\"1124\">18</sup> מינייהו אשתרו כולהו שמהן כגופא בלא נשמתא [היינו חיות הכלי] כמו חיות הנשמה שמחי' את הגוף בעת השינה נשאר קיסטא דחיותא כמו\"כ למעלה כד אנת תסתלק מינייהו נשאר קיסטא דחיותא. והנה לפי המשל הזה צריכים לומר שהקיסטא דחיותא הוא ג\"כ מהקו, דכמו שאנו רואין בהנפש שבעת השינה הוא מאיר בהגוף אלא שבעת שהוא ער מאיר הנפש בהגוף שיהי' שכל אך בעת שהוא ישן אפשר להתחבר ב' ענינים נפרדים כמו חלומות ודמיונות, אך מה שנשאר הוא מהנפש גופא, כמו\"כ למעלה מה שנשאר בהכלי הוא מהקו. ומוכרח לומר כן דהנה אמרז\"ל ע\"פ והשמותי את מקדשיכם בהכ\"נ שחרב קדושתן עליהם אפי' הם שוממין, דבהכ\"נ הוא מקדש מעט לכן קדושתן כו' דאין דבר שבקדושה נעקר ממקומו לגמרי<sup data-n=\"1125\">19</sup>, וכמו\"כ למעלה אין דבר שבקדושה נעקר כו' וא\"כ מוכרח לומר שהוא ג\"כ מהקו. ומוכרח לומר ממ\"ש בסש\"ב דאיהו מתייחד בגרמוהי לברוא מאין ליש, והנה הבריאה הוא דוקא מאיהו, דגרמוהי הוא רק כדי שיהי' מאין ליש, והנה המחדש בטובו בכ\"י תמיד מע\"ב שבכל עת ובכל רגע נמשך",[["1119","13","<b>ועתה יובן שירת הים</b>: בהבא לקמן, ראה אוה\"ת בשלח שם ע' תצג ואילך."],["1120","14","<b>לזאת יקרא אשה. . מל' כנס\"י מקור נש\"י</b>: ראה סה\"מ תרכ\"ט ע' נא-נב [ובהנסמן שם]."],["1121","15","<b>אבל במל' שהיא ספי' מע\"ס מה שייך שירה</b>: ראה בהמ\"מ לעיל בהמאמר ע' קנה."],["1122","16","<b>חיוהי הם האורות וגרמוהי כלים</b>: ראה אגה\"ק רס\"כ (קכט, א). תו\"א בראשית ג, ב. לקו\"ת ראה כז, ב. שה\"ש נ, ג-ד. סה\"מ תרל\"ג ח\"ב ע' שמו ואילך."],["1123","17","<b>דהאור הוא פשוט ושוה בכל הספי'</b>: ראה בארוכה באוה\"ת ענינים ע' רנט ואילך. וע' רפה. וש\"נ."],["1124","18","<b>וכמאמר וכד אנת תסתלק</b>: ראה סידור עם דא\"ח קסד, ב ואילך. אוה\"ת וירא (כרך ד) תשמב, א ואילך."],["1125","19","<b>דאין דבר שבקדושה נעקר ממקורו לגמרי</b>: ראה אגה\"ק ביאור לסי' ז\"ך (קמז, ב). אוה\"ת לך לך (כרך ב) תרעה. א. וש\"נ. ובהנסמן ע\"ז בארוכה לעיל במאמר ע' קנה."]]],[2000460361,"חיות חדש לחיות נבראים וכשיסתלק רגע א' ישאר אין ואפס, וזהו דוקא מבחי' איהו דהתחלקות הנבראים זהו מבחי' גרמוהי אבל החיות הוא מבחי' איהו, וכשנא' שמ\"ש כגופא בלא נשמתא הוא שלא נשאר כלל א\"כ האיך נמשך החיות אלא מוכרח לומר שנשאר [והוא האור שהי' תחילה].\n<b>וזהו</b> השירה דמל' לעלות מגרמוהי לחיוהי<sup data-n=\"1126\">20</sup>. ועלי' זו למעלה מעליות הלוים שהוא מעלמא דאתגלייא לעלמדאת\"כ אבל עלי' זו הוא מחיוהי לגרמוהי. וזהו מ\"ש אתה הוא ה' לבדך, אתה הוא עבודת הכהנים וכמ\"ש אתה כהן לעולם, והוא, הוא עבודת הלוים, לבדך הוא העלאת גרמוהי לחיוהי, והוא כמ\"ש ונשגב הוי' לבדו ביום ההוא, ובמדריגה זו משה ובנ\"י שוין ולכן קאמר ישיר<sup data-n=\"1127\">21</sup>.\n<b>וזהו</b> אז ישיר משה כו' כל פרקמטייא דמשה הי' באז, שירתו באז, דהנה אז הוא אותיות א' ז' והאלף על הז'<sup data-n=\"1128\">22</sup>, דז' הם ז' ימי בראשית ומפרשים זה הגבה למעלה מאד, ואלף [הוא פלא אלפך חכ' שממשיך לחכ' ו]הוא מ\"ש אז תתענג על הוי'. דהנה בז' ימי בראשית יש שבת ג\"כ שהוא שבת להוי' אבל אז תתענג על הוי' הוא בחי' שלמעלה משבת, ולכן וקראת לשבת עונג שממשיכים עונג בשבת, הגם דכתי' שער החצר הפנימית הפונה קדים סגור יהי' ששת ימי המעשה וביום השבת יפתח הרי שבשבת גילוים מעונג, מ\"מ העונג עצמו למעלה יותר, ובבחי' זו משה ובנ\"י שוים, דמשה הוא עלדאת\"כ וישראל הוא עלדאת\"ג ובחי' זו למעלה מעלדאת\"כ ועלמדאת\"ג דמשם נמשך שעלדאת\"כ יאיר בעלדאת\"ג לכן שוים שם משה ובנ\"י. ובעבודה הנה יש התפעלות ובזה יש חילוקי מדריגות זה מתפעל על אופן וזה על או\"א אבל יש בחי' רעו\"ד שהוא למעלה מהטו\"ד. ויאמרו לאמר דהנה כל עסקא דשבתא כפול, שירה כפול שיר וזמרה, קרבנו כפול, דהנה יש ב' בחי' שבתא דמעלי שבתא ושבתא דיומא, והיינו עלי' אחר עלי' וזה ויאמרו לאמר עלי' אחר עלי'. אשירה להוי' שממשיכים לשם הוי'. סוס ורוכבו רמה בים, רמה הוא ל' השלכה, דהנה כתי' וידעו מצרים כי אני הוי' דהנה מצרים הגביהו א\"ע לקבל ממדריגה גבוה דכחשיכה כאורה אך רק בחי' אחורים דפרעה אותיות העורף אבל הפנים הוא לישראל וכמ\"ש יאר הוי' פניו אליך, שהארת הפנים לישראל דוקא, והנה כתי' אם תגביהי כנשר<sup data-n=\"1129\">23</sup> משם אורידך נאום הוי', וזהו וידעו מצרים כי אני הוי' שאפי' שם יש בחי' הוי' דמשם אורידך, וזהו ע\"י מה שסוס ורוכבו רמה בים ידעו מצרים כי אני הוי'.",[["1126","20","<b>וזהו השירה דמל' לעלות מגרמוהי לחיוהי</b>: בהבא לקמן ראה אוה\"ת בשלח שם ע' תצג ואילך."],["1127","21","<b>ובמדריגה זו משה ובנ\"י שוין ולכן קאמר ישיר</b>: ראה אוה\"ת בשלח שם ע' תצג ואילך וע' תרח-ט. וראה לקו\"ש חל\"א ע' 69 ואילך."],["1128","22","<b>דהנה אז הוא אותיות א' ז' והאלף על הז'</b>: ראה לקו\"ת דרושים לשמע\"צ פח, ב. סה\"מ תרכ\"ט ע' קנ. סה\"מ מלוקט ח\"ד ע' קט. וש\"נ."],["1129","23","<b>והנה כתי' אם תגביהי כנשר</b>: ראה תו\"א ויחי קב, ב ואילך. סה\"מ תרל\"ב ח\"א ע' נג ואילך. ובכ\"מ."]]],[2000460362,"<b>וזהו</b> על ג' דברים העולם עומד על התורה והעבודה וגמ\"ח, והוא מ\"ש כהנים בעבודתם ולוים בדוכנם וישראל במעמדם, כהן איש החסד הוא קו הימין לוים הוא קו השמאל וישראל הוא תורה דכתי' ויקם עדות ביעקב ותורה שם בישראל, הלא ששייך תורה לישראל קו האמצעי, וקרי\"ס הי' הכנה למ\"ת כתי' והמים להם חומה מימינם ומשמאלם<sup data-n=\"1130\">24</sup> הוא קו הימין וקו השמאל וישראל הלכו באמצע ביבשה בתוך הים.",[["1130","24","<b>כתי' והמים להם חומה מימינם ומשמאלם</b>: ראה ג\"כ תו\"א בשלח שם סב, ד."]]],[2000460363,"<h3>להבין מה שיצי\"מ נק' נר</h3>\n<b>אחרון ש\"פ ט\"ל לפ\"ק</b>\n<b>להבין</b> מה שיצ\"מ<sup data-n=\"1131\">1</sup> נק' בשם נר והלא כתי' עד שנגלה עליהם<sup data-n=\"1132\">2</sup> מלך מלכי המלכים הקב\"ה וגאלם הרי הי' גילוים גבוהים ואיך שייך לאמר על הגילוים דמלך מלכי המלכים שהם בחי' נר. והנה צ\"ל תחילה ענין החפזון שהי' במצרים דכתי' ואכלתם אותו בחפזון ע\"ש כי בחפזון יצאת מאמ\"צ ואי' בילקוט בשם המכילתא דהחפזון הי' חפזון דשכינה אעפ\"י שאין ראי' לדבר זכר לדבר שנא' קול דודי הנה זה בא מדלג על ההרים הרי דודי מדלג, וצ\"ל איך שייך בבחי' דודי חפזון דדודי הוא ת\"ת ז\"א מדות דאצי' איך שייך שם חפזון. דשמירה שייך בבחי' מל' שנק' ליל שמורים ונת\"ל ב' טעמים הא' מפני שהוא מקור בי\"ע לכן צריך שמירה הב' שמשתמרת להיחוד ואז הקנאה גדולה מאד וצריכה שמירה אך מדת יום אינו צריך שמירה דלא יגורך רע כתי', הגם שיש קליפה כנגד אצי' מעמדה בבריאה, ומה שייך שם שמירה, דלכן ברכה ראשונה דברכת אירוסין אינה חותמת בברוך מפני שאדם הוא מדת יום א\"צ שמירה והאיך אומר שהחפזון הי' בבחי' דודי.\n<b>אך</b> הענין דהחפזון אינו בשביל עצמו דהנה כתי' אכלו רעים שתו ושכרו דודים, רעים הם או\"א ודודים זו\"ן ואי' בזהר תאיבין דא לדא ולא משתכחין, די\"ה זיווגייהו תדיר דהם תרדל\"מ אבל ו\"ה הזיווג לפרקים דאם יש העלאת מ\"ן נמשך הזיווג ואי אין העלאת מ\"ן אינו נמשך לכן שייך חפזון בדודים שלא למנוע היחוד,",[["1131","1","<b>להבין מה שיצ\"מ</b>: הנחה בגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע מד\"ה ”והנה בילקוט פ' בא\" הנדפס לעיל ע' קמט (והוא המשך להמאמרים ד\"ה וככה תאכלו אותו וד\"ה אור לארבעה עשר שנדפסו לעיל). וראה בהמ\"מ לעיל ריש ד\"ה וככה ע' קלח. לקמן נד' הנחה נוספת ממאמר זה (שם נרשם מאמר זה לפני ד\"ה אז ישיר משביעי של פסח)."],["1132","2","<b>שיצ\"מ נק' בשם נר. . והלא כתיב עד שנגלה עליהם</b>: ראה בכ\"ז גם לעיל ע' קל. סה\"מ תרכ\"ט ע' קלד וע' קמג. וש\"נ."]]],[2000460364,"דעיקר החפזון הוא בשכינה דושכנתי בתוכם גלו לבבל כו' אנכי ארד עמך מצרימה אלא בדודים החיפזון שלא למנוע היחוד, וזהו שאומר קול דודי שהוא בחי' ז\"א אלא שמל' הוא ג\"כ בכלל דודים וכמ\"ש דודים הרי מל' ג\"כ בכלל, ולכן קאמר אעפ\"י שאין ראי' לדבר זכר לדבר שאין ראי' לזה מ\"מ זכר לדבר יש שהוא בחי' ז\"א. אך לע\"ל כי לא בחיפזון תצאו. דהנה כתי' ביום ההוא יהי' הוי' אחד וכ' בלקו\"ת מהאריז\"ל דעכשיו השם הוי' הוא י\"ה ו\"ה לכן שייך חפזון אבל לע\"ל יהי' הו\"ה במעל' ומדריגות י\"ה, וזהו יהיה ב\"פ י\"ה, ולכן לא יהי' אז חפזון. וזהו דיצ\"מ נק' בשם נר והוא נס בלילה שהוא נס עובר והי' בחפזון אבל לע\"ל כי לא בחפזון תצאו. וזהו שתרגם יונתן ע\"פ כי אתה נרי הוי' והוי' יגיה חשכי ארום את מארי' דנהורא דישראל הוי', והוי' יגיה חשכי את יפקינני מחשוכא לנהורא ויחזינני לעלמא דעתיד למיתי לצדיקייא לעלמא דאתי, והוא מפרש ג\"כ כמ\"ש במדרש תהלים בעוה\"ז כו' ובמד\"ר אומר ג\"כ שהי' נס בלילה ובמדר' תלים מפרש פרטים יותר.\n<b>והענין</b> דהנה כתי' עד שנגלה עליהם<sup data-n=\"1133\">3</sup> מלך מלכי המלכים הקב\"ה וגאלם, והענין דהנה כתי' מלכותך מלכות כל עולמים, מלכות כל עולמים היינו בחי' מל' שהוא מקור בי\"ע וכמ\"ש כל הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, ומלכותך הוא כמו שהוא כלול בעצמותו<sup data-n=\"1134\">4</sup> וה\"ה כמו אור השמש כמו שהוא בגוף כדור השמש<sup data-n=\"1135\">5</sup>. דהנה האור שאנו רואין המאיר לארץ ולדרים עלי' הוא אור וזיו השמש, וכמו שהוא כלול בעצמותו אינו תופס מקום כלל, וזהו מלכותך כמו שהוא בעצמותו, והוא בחי' מל' דא\"ס. וזהו מלך מלכי המלכים, מלכים הוא ז\"א<sup data-n=\"1136\">6</sup> ומל' דאצי', מלכי הוא חו\"ב דזיווגייהו תדיר, מלך מלכי המלכים הוא כתר מל', דכ\"ע איהו כתר מל' שבו שורה מל' דא\"ס והוא צריך לימשך ע\"י מדריגות אלו, וזהו שנק' נר הוי' כמ\"ש בת\"י דצ\"ל ע\"י ד' אותיות שם הוי'. והנה בנר יש שמן ופתילה ואור<sup data-n=\"1137\">7</sup>, דנר בלה\"ק הוא כלי המקבל השמן והפתילה והאור, שמן חכ' פתילה יסוד אור כתר, שצ\"ל ע\"י בחי' אלו. הגם שנת' בכ\"ד שיצ\"מ הי' הגלוי שלא ע\"י חו\"ב וז\"א, צ\"ל היינו שלא בדרך התלבשות אבל נמשך בדרך מעביר דשם יש מדה\"ד ואם הי' בדרך התלבשות הי' נגוף ורפוא אבל כשהי' בדרך מעביר הי' נגוף למצרים ורפוא לישראל. והנה משל נר כשמביאים בבית מאיר לא שמהפך את החושך אלא דוחה אותו, דכשנכלה הנר אז חושך בבית והוא מפני שאינו מהפך אותו, ולכן חזרו ונשתעבדו וזהו שאמרו ישראל אינם רוצים עוד בגאולת ב\"ו נמתין עד שיגאלנו הקב\"ה.",[["1133","3","<b>והענין דהנה כתי' עד שנגלה עליהם</b>: בהבא לקמן ראה לקו\"ת שה\"ש יד, ג ואילך. סה\"מ תרכ\"ט שם ע' קלה ואילך. תרל\"ב ח\"א ע' כ ואילך וע' כח ואילך."],["1134","4","<b>ומלכותך הוא כמו שכלול בעצמותו</b>: ראה תו\"א יתרו עג, ד. ועוד."],["1135","5","<b>אור השמש כמו שהוא בגוף כדור השמש</b>: ראה תניא פל\"ג (מב, א). שעהיחוה\"א פ\"ג (עח, א). ובכ\"מ."],["1136","6","<b>וזהו מלך מלכי המלכים, מלכים הוא ז\"א</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' רפז. ועוד."],["1137","7","<b>והנה בנר יש שמן ופתילה ואור</b>: ראה בכ\"ז תו\"א מקץ לג, ב-ג. מ, ב. לעיל ע' קלו. ובכ\"מ."]]],[2000460365,"<b>והנה</b> ההפרש בין גאולת מצרים לגאולת בבל וגאולת מתתי' ב\"י כה\"ג חשמונאי ובניו הוא בין נר לאבוקה, דמצינו שנר נק' אבוקה דארז\"ל בסוטה נזדמנה לו נר ניצול מן הקוצים והברקונים ופירש\"י היינו נר מצוה הרי שאבוקה בכלל נר, והנה נר אינו מאיר אלא במקומו אבל אבוקה מאיר מרחוק, ולכן גאולת מצרים הי' ע\"י משה ואהרן והוא אבוקה ולכן הי' זמן רב עד גלות בבל ערך תשע מאות שנה אבל גאולת בבל כו' הוא נר, אבל לע\"ל הוא בחי' אור היום. דהנה עוד ארז\"ל שם עלה עמוד השחר ניצול עוד מכמה דברים ובנמשל אי' שהוא מ\"ש ותורה אור, דהנה ההפרש בין תורה למצות הוא, דמצות תלוים בזמן, כמו מצה הוא בפסח דוקא ובחגה\"ש אינו מצוה, סוכה הוא דוקא בסוכות, אבל אינו תלוי בזמן<sup data-n=\"1138\">8</sup> שהוא מדריגה שלמעלה מהזמן, ולכן והיו הדברים האלה בד\"ת הכתוב מדבר אשר אנכי מצוך היום שהוא ל' צותא וחיבור היום עם הלילה שלילה כיום יאיר דתורה הוא מעין ודוגמא מלע\"ל לכן ותורה אור לילה כיום יאיר. הגם בפ' שני' גבי מצות כתי' ג\"כ אשר אנכי מצוה אתכם היום, מ\"מ הם תלוים בזמן דמצות תלויים בזמן ומקום וכלים היינו כלי האור. וזהו שלע\"ל יהי' בבחי' אור היום.\n<b>עוד</b> הפרש יש בין גאולת מצרים לגאולה דלע\"ל, דהנה כתי' קומה ה' ויפוצו אויבך<sup data-n=\"1139\">9</sup> וכתי' קומה ה' למנוחתיך. והענין דהנה כתי' וחמושים עלו בנ\"י מארץ מצרים<sup data-n=\"1140\">10</sup> ואי' בירושלמי שהיו בחמשה כלי זיין, סייף קשת תריס אלה רומח, וכן בקי\"ס הי' מלחמה דכתי' ה' ילחם לכם הרי שהי' מלחמה רק ה' ילחם לכם, והוא מפני שהי' עדיין רע וצ\"ל מלחמה, וזהו קומה ה' ויפוצו אויבך וכשיש אויבים צ\"ל מלחמה וכמ\"ש כי תצא למלחמה על אויבך, אבל<sup data-n=\"1141\">11</sup> לע\"ל לא יהי' עוד רע דאת רוח הטומאה אעביר מן הארץ, אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם א', וכתי' וכתתו חרבותם לאיתים וחניתותיהם למזמרות לא ישא גוי אל גוי חרב ולא ילמדו עוד מלחמה, שלא יהי' רע ואינו צריכים מלחמה לכן יהי' מנוחה. וזהו כשדוד רצה לבנות המקדש א\"ל אתה לא תבנה בית לשמי מפני שהי' איש מלחמה, דבפסוק נק' איש הדמים, אלא שלמה שהי' איש מנוחה הוא יבנה בית לשמי. וזהו ענין גאולה דלע\"ל שהוא מ\"ש קומה ה' למנוחתיך.",[["1138","8","<b>דמצות תלוים בזמן. . אבל אינו תלוי בזמן</b>: ראה לקו\"ת במדבר יג, א. סה\"מ תרכ\"ז ע' שלו (בשוה\"ג)."],["1139","9","<b>עוד הפרש. . דהנה כתי' קומה ה' ויפוצו אויבך</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ קלב, א ואילך. ולהצ\"צ ח\"א ע' קא ואילך. ח\"ב ע' תרפז ואילך וע' תרצא ואילך. אוה\"ת ויצא קעז, א ואילך. קפו, א ואילך. לעיל ע' קלב."],["1140","10","<b>דהנה כתי' וחמושים עלו בנ\"י מארץ מצרים</b>: ראה בכ\"ז אוה\"ת בשלח ע' שעד. סה\"מ תרל\"ב ח\"א ע' נב ואילך וע' רכד ואילך."],["1141","11","<b>אבל</b>: אוצ\"ל: אבל תורה."]]],[2000460366,"<h3>כל הולך על גחון</h3>\n<b>ש\"פ שמיני ט\"ל לפ\"ק</b>\n<b>כל</b> הולך על גחון<sup data-n=\"1142\">1</sup> וארז\"ל למה נק' הראשונים סופרים שהיו סופרין אותיות התורה והיו אומרים ו' דוגחון הוא חצי אותיות התורה, והיו סופרים אותיות התהלים והיו אומרים ע' דמיער הוא חצי אותיות בתהלים. וכ' בח\"א<sup data-n=\"1143\">2</sup> ו' דוגחון מפסיק כח הנחש דנחש הקדמוני כתי' בו על גחונך תלך לכן נק' גחון והו' מחליש כחו, וע' דיכרסמנה חזיר מיער דכתי' ואת החזיר כי מפריס פרסה הוא מפסיק כח החזיר. דהנה תהלים מכוון נגד תורה וכמו שיש בתורה חמשה חומשי תורה כמו כן יש בתהלים חמשה ספרים, ולדעה דתורה נחלק לז' ספרים כמ\"ש חצבה עמודי' שבעה כמו\"כ תהלים נחלק לז' ימי השבוע, וצ\"ל למה תורה ותהלים דוקא. והענין דהנה אמרז\"ל כל מי שיש בו תורה ואין בו יר\"ש דומה לגזבר שמסרו לו מפתחות הפנימיות ומפתחות החיצונים לא מסרו לו בהי עייל, תורה הוא מפתחות הפנימיות ותהלים מפתחות החיצוניות, דהנה כל התהלים הוא סיפורי שבחי המקום כמו השמים מספרים כבוד אל, הללויה הללו עבדי ה' הללו שם ה', ולכך בתפלה הרוב הוא פסוקי תהלים שהוא סיפור שבחי המקום ודוד מספר זה. הגם שקודם דוד הי' ג\"כ תהלים מ\"מ לא סיפרו ודוד מספר זה מפני שהוא מרכבה לבחי' זו. וזהו בג' ספרים ברא הקב\"ה את עולמו בספר וסופר וסיפור, ספר וסופר הוא תורה וסיפור הוא תהלים, וע\"פ הקבלה תורה הוא ת\"ת ותהלים הוא מל'. ורבינו ז\"ל פי' מפתחות החיצוניות<sup data-n=\"1144\">3</sup> הוא תהלים מפני שכל ענין תהלים הוא כמו הללויה הללו את השם מן השמים הללוהו במרומים, ואתה מחי' את כולם שהו\"ע הבריאה נק' מפתחות החיצוניות, אבל תורה הוא מפתחות הפנימיות. וצ\"ל איך שייך לומר על ברה\"ע שהוא חיצוניות.\n<b>והענין</b> דהנה ידוע שיש אור ושפע וידוע החילוק ע\"פ חכמי המחקר<sup data-n=\"1145\">4</sup> שפע הוא השפעה ופועל שינוי בהמשפיע שצריך לצמצם א\"ע, וכמו השפעת הרב",[["1142","1","<b>כל הולך על גחון</b>: מאמר זה נדפס כאן מגוכי\"ק אדמו\"ר מוהרש\"ב נ\"ע בס' ההנחות תרל\"ט. ולקמן נד' ג\"כ הנחה נוספת של המאמר. [אך מאמר זה לא נרשם בגוכי\"ק אדמו\"ר מהר\"ש בס' תרל\"ט, ונמצא רק בהנחות].\nבתחילת העמוד בצידו השמאלי ציין כ\"ק אדמו\"ר מוהרש\"ב נ\"ע בגוכי\"ק: יד שמאל נרתע מאד. [ראה פקסימיליא להלן בהוספות ע' שסב].\nהמאמר מיוסד על ד\"ה זה באוה\"ת שמיני ע' רמב ואילך. וראה ד\"ה זה בסה\"מ תרכ\"ו ע' עב ואילך (הוצאת קה\"ת תשמ\"ט). ד\"ה החודש, בסה\"מ תרל\"ב ח\"א ע' רסג ואילך. ד\"ה מהרה ישמע: בסה\"מ תרל\"ב ח\"ב ע' תקמה ואילך (ובס' מאמרי אדמו\"ר מהר\"ש — דרושי חתונה ע' קפו ואילך), וסה\"מ תרל\"ד ע' יח ואילך. וראה ד\"ה ארז\"ל לפיכך נקראו הראשונים סופרים, בסה\"מ תרצ\"ט (ע' 168) ובסה\"מ תשט\"ז."],["1143","2","<b>וכ' בח\"א</b>: בחדא\"ג מהרש\"א (קידושין ל, א). והובא גם באוה\"ת שמיני שם ע' רמ וס\"ע רמב. ובשאר מקומות שנסמנו לעיל."],["1144","3","<b>ורבינו ז\"ל פי' מפתחות החיצוניות</b>: ראה לקו\"ת דברים כב, ד ואילך. וראה אוה\"ת שמיני שם ע' רמג וע' רמו."],["1145","4","<b>דהנה ידוע שיש אור ושפע וידוע החילוק ע\"פ חכמי המחקר</b>: ראה גם סה\"מ תקס\"ב ח\"א ע' רסא. ח\"ב ע' שע. שעח. תכב [ובהמ\"מ לשם]. אוה\"ת ענינים ע' קי ואילך. קמב ואילך. סה\"מ תרכ\"ו ע' רעח ואילך. תרכ\"ז (הוצאת תשנ\"ט) ע' תנו ואילך. תע ואילך. תרנ\"ח ע' סח ואילך. סה\"מ מלוקט ח\"ב ע' רצב ואילך. ועוד."]]],[2000460367,"לתלמיד שצריך לצמצם א\"ע שיוכל המקבל לקבל והיינו בדרך קצרה באופן שיוכל לקבל, הרי יש בו שינוי מקודם ההשפעה לבשעת ההשפעה, אבל אור כשמכניסין נר בבית מאיר בבית ואין בהנר שום שינוי מפני שהוא רק הארה, כמו\"כ חיות הנבראים והיינו מאוא\"ס הוא רק הארה לכן נק' חיצוניות, אבל תורה הוא מפתחות הפנימיות דכתי' אשר אנכי מצוך היום שמחבר עם בחי' אנכי מי שאנכי.\n<b>וביאור</b> הענין דהנה בכלל באדם יש פנימיות וחיצוניות, דמחדו\"מ הם ג' לבושי הנפש ולבוש הוא חיצוני, ובהם מעשה הוא יותר חיצון שבשעת העשי' יוכל לדבר כמו אומן שעושה כלי מ\"מ מדבר בעת העשי', ובמעשה גופא יש פנימיות וחיצוניות<sup data-n=\"1146\">5</sup> דכח הזריקה שבאדם הוא חיצוניות דישנו בבהמה ג\"כ וכמאמר היו צרורות מנתזין מתחת רגלי', אלא שבהמה מזקת ואדם מפני שהוא מורגל שלא להזיק אינו מזיק, אבל מאחר שיש כח זה בבהמה ג\"כ הוא חיצוני. וכתיבה הגם שהוא ג\"כ מעשה מ\"מ יכול לכתוב דבר שכל הוא פנימי, ודיבור לגבי מעשה הוא פנימי אבל לגבי מח' הוא חיצוני שמח' הוא גילוי העלם העצמי לגבי עצמו ודיבור הוא גילוי לזולתו, ובזה גופא יש ג\"כ פנימיות וחיצוניות כשמדבר בעניני העולם הוא חיצוני וכשמדבר בהדיבור דבר תורה<sup data-n=\"1147\">6</sup> הוא פנימי, ומח' הגם שהוא היותר פנימי יש בו ג\"כ פנימיות וחיצוניות סתם מח' הוא חיצוניות ועומק המח' הוא פנימיות, הרי בכלל יש בכולן פנימיות וחיצוניות, והוא שיש בהם חב\"ד חג\"ת נה\"י והוא פנימי חיצוני תיכון, ובכלל הם חיצוניות לגבי השכל והמדות שהם נק' עצם הנפש כמ\"ש בתניא, ופעמים אמר רבינו ז\"ל<sup data-n=\"1148\">7</sup> שהשכל והמדות עצם הנפש<sup data-n=\"1149\">8</sup> אלא הם נק' גופים שאינו כמו לבושים, שיכול לפשוט וללבוש כמו שיש בגדי שבת ובגדי חול אבל הגוף א\"א לפשוט דבע\"כ אתה חי ואינו שייך לחלוק הנשמה מהגוף שזה הנפש וזה הגוף שהנפש מחי' את הגוף לכן מחדו\"מ נק' לבושים אבל שכל והמדות הם גופים לעצם הנפש, ובזהר מחלק זה לד' בחי' נפש רוח נשמה ונשמתא לנשמתא וכמו\"כ באדם הוא ראש וגוף ורגל שהם נשמה רוח נפש, והנפש המחי' את הגוף הוא נשמתא לנשמתא.",[["1146","5","<b>וביאור הענין דהנה בכלל באדם יש פנימיות וחיצוניות. . ובמעשה גופא יש פנימיות וחיצוניות</b>: ראה בכ\"ז לקו\"ת דרושים לש\"ש סו, ב. אוה\"ת שמיני שם ע' רמז. סה\"מ תרל\"ג ח\"א ע' קטז. ח\"ב ע' תקיד [ובמ\"מ בתחילת המאמר שם]."],["1147","6","<b>וכשמדבר בהדיבור דבר תורה</b>: בגוכי\"ק כאן בתחילת ובסוף תיבות אלו, צויינו איזה סימני עיגול, אולם לא נרשמו שום הוספות בצד הגליון."],["1148","7","<b>לגבי השכל והמדות שהם נק' עצם הנפש כמ\"ש בתניא, ופעמים אמר רבינו ז\"ל</b>: ראה תניא פ\"ג (ובהמובא בליקוט פירושים ומ\"מ לשם). וראה בכ\"ז תו\"א וירא יג, ג. לקו\"ת ויקרא ד, ב. סה\"מ תקס\"ב ח\"א ע' קעט. ח\"ב ע' תכב. סה\"מ תקס\"ו (הוצאה ראשונה) ע' כט. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' צח. ס' מאמרי אדה\"ז ענינים ע' רמא. הקצרים ע' שט. סה\"מ תרל\"ב שם ע' רסו (בהמ\"מ)."],["1149","8","<b>ופעמים אמר רבינו ז\"ל שהשכל המדות עצם הנפש</b>: כ\"ה בגוכי\"ק. ולקמן בהנחה שני' הלשון: אך פעם כתב רבינו בדרוש ששכל ומדות ג\"כ אינם עצמי' הנפש כו'. וראה בכ\"ז בנסמן לעיל בהערה הקודמת."]]],[2000460368,"<b>וכמו\"כ</b> יובן למעלה דמחדו\"מ הם בי\"ע<sup data-n=\"1150\">9</sup> דבי\"ה ה' צור עולמים ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שהוא באותיות הדיבור, ואפי' עלמין סתימין דלא אתגליין שהוא בי' נברא העוה\"ב הוא אותיות המח', משא\"כ ע\"ס דאצי' הם נק' גופים, וחכ' למעלה מכולם שבו שורה אוא\"ס, הגם שבכולם שורה אוא\"ס מ\"מ חכ' הוא ראשית ההשתל' ודרך בו נמשך לכולם והוא סדר השתל', ויש למעלה מסדר השתל' וכמו באדם יש שכל ועומק השכל מקור השכל כמו\"כ למעלה אינו שייך בחי' אלו אלא הוא בחי' לית מחשבה תפיסא בי' כלל, ובחי' זו יש בתורה דאורייתא מחכ' נפקת וידוע דחיצוניות שבעליון הוא פנימיות שבתחתון<sup data-n=\"1151\">10</sup>, אבל תורה דמחכ' נפקת יש בה הפנימיות ג\"כ, וה\"ה פנימיות לגבי העולמות שהם מבחי' חיצוניות משא\"כ תורה הוא מפנימיות לכן נק' מפתחות הפנימיות, ולכן נמשך למטה בארץ דוקא וכמ\"ש ועברתי בארץ מצרים אני ולא מלאך דבמצרים אני דוקא<sup data-n=\"1152\">11</sup>, וכמו אותיות החקוקים על האבן טוב מרוב בהירות האבן א\"א לקרות האותיות אבל כשהם על השעוה אז אפשר לקרותם הרי אותן האותיות שהם חקוקים על האבן הם ניכרים על השעוה דוקא, ועוד דנעוץ תחילתן בסופן דוקא.\n<b>ועפ\"ז</b> יובן מ\"ש כי תשמע בקול ה' אלקיך, קול מפרש רבינו ז\"ל שהוא מחבר גשמיות ורוחניות<sup data-n=\"1153\">12</sup> וזהו קול ה' אלקיך שיומשך גם בעשי', בקול היינו מה שבפנימיות הקול והוא הארת הקו וחוט בפנימיות הקול. והענין דהנה תורה אינו ידיעת התורה לבד אלא המשכת אוא\"ס בתורה, וכמו דוד הי' מחבר תורה שלמעלה בהקב\"ה<sup data-n=\"1154\">13</sup> המשכת אוא\"ס בתורה, שע\"י תורה לשמה ממשיכים המשכת אוא\"ס בתורה, וזהו בקול.\n<b>והענין</b> דהנה תורה נק' תורת חסד ויש עונשין שבתורה הוא דין בכלל הן עשין ול\"ת ותורה מחבר ב' בחי' אלו, לכן בכח התורה להחליש כח הנחש. דהנה יניקת החיצונים הוא מקו השמאל הגם דאברהם יצא ממנו ישמעאל זהו קודם שנימול<sup data-n=\"1155\">14</sup> אבל יצחק יצא ממנו כו' אף לאחר שנימול מפני שיניקתם מקו השמאל, ותורה מחבר חו\"ג לכן אין להם יניקה וזהו שמחליש כח הנחש. והוא כמו ענין אהבה ברשפי אש ה\"ה אהבה מ\"מ נולד מזה כעס, הגם שהכעס הוא על ההיפך מ\"מ הוא כעס, אך זהו רק הגבורות לבד אבל עם תורה שהוא לאכללא שמאלא בימינא עי\"ז",[["1150","9","<b>וכמו\"כ יובן למעלה דמחדו\"מ הם בי\"ע</b>: ראה לקו\"ת בלק סז, א ואילך. ובכ\"מ."],["1151","10","<b>וידוע דחיצוניות שבעליון הוא פנימיות שבתחתון</b>: ראה לקו\"ת שה\"ש לט, ד. אוה\"ת שמיני שם ס\"ע רמז."],["1152","11","<b>וכמ\"ש ועברתי בארץ מצרים אני ולא מלאך דבמצרים אני דוקא</b>: ראה לקו\"ת פ' צו יב, ג. טז, א. מאמרי אדה\"ז עה\"ת ח\"א ע' שלט. סה\"מ תקס\"ד ס\"ע פד. ועוד. וראה במ\"מ בס' מאמרי אדמו\"ר מהר\"ש דרושי חתונה שם ס\"ע פה."],["1153","12","<b>קול מפרש רבינו ז\"ל שהוא מחבר גשמיות ורוחניות</b>: ראה סידור עם דא\"ח יט, ג. תו\"א וישב כז, ב. ויחי נד, ג ואילך. לקו\"ת דברים שם כג, סע\"א ואילך. וראה סה\"מ תרל\"ב ע' שנט: יוקדם ענין והצעת דרוש וא\"ו דגחון ל\"ב ולפמשנ\"ת שם קול המחבר רוחניות וגשמיות כו'."],["1154","13","<b>וכמו דוד הי' מחבר תורה שלמעלה בהקב\"ה</b>: ראה גם לקו\"ת שלח מז, ג. נא, א. ועוד."],["1155","14","<b>דאברהם יצא ממנו ישמעאל זהו קודם שנימול</b>: ראה גם בסה\"מ תרל\"ב שם ע' רסט. וש\"נ."]]],[2000460369,"מברר אותם<sup data-n=\"e21\">*</sup>. וזהו אם פגע בך כו' משכהו לבהמ\"ד בראתי יצה\"ר בראתי תורה תבלין. והוא ע\"ד מ\"ש המשל ופחד עמו עושה שלום במרומיו<sup data-n=\"1156\">15</sup> מיכאל שר של מים וגבריאל שר של אש ואינם מכבים, הגם דמים ואש שני הפכים מ\"מ כשמאיר מבחי' שלמעלה משניהם הם בטלים ואינם מכבים זא\"ז, וכמו\"כ תורה הוא מחבר חו\"ג.\n<b>לשמור</b> מצותיו<sup data-n=\"1157\">16</sup> הוא הכלי לאור התורה, דהנה כתי' אל יתהלל כו' כי אם בזאת יתהלל המתהלל השכל וידוע אותי כי באלה חפצתי עושה חסד ומשפט וצדקה, השכל הוא תורה וידוע אותי הוא אוא\"ס שבתורה, חסד הוא קו הימין משפט קו השמאל צדקה כללות המצות, ותורה שהוא השכל וידוע אותי הוא מחבר אותם, דמצות הם כלים לאור התורה. ולעשות הישר בעיני הוי' דהנה יש עינא דלתתא ועינא דלעילא, עינא דלתתא הוא בריאה יש מאין שלמטה היש ולמעלה האין ועינא דלעילא הוא שכולא קמי' כלא חשיבי ולמעלה היש ולמטה האין, וכתי' כי עין בעין יראו שד\"ת יהי' כמו ד\"ע.\n<b>וזהו</b> הע' דמיער<sup data-n=\"1158\">17</sup> דהנה ע' הם ז' מדות כלולות מעשר הם והוא ז\"ת דבינה שהוא מקור ושרש ז' מלכין קדמאין שנפלו בשבירה, וע\"י תהלים מבררים אותם דתהלים הוא הסיפור איך שכולם אומרים קדוש, הללויה הללו ה' מן השמים הללוהו במרומים, הללו ה' מן הארץ תנינים וכל תהומות, וענין השירה הוא ביטול היש כשאומר שירה לא' מבטל א\"ע ועי\"ז מבררים אותם, וזהו שמע שם ע', ב\"ן רפ\"ח בגימ' שם, שעי\"ז מבררים הרפ\"ח ניצוצים. וזהו שהע' דמיער הוא עי\"ן תלוי', מפני שהוא מקיף דלבונה זכה שמקבלים משם חיותם בדרך מקיף ותהלים מברר זה. ומה שייך בתהלים חצי, דהנה דוד ספור<sup data-n=\"1159\">18</sup> תהלים וכתיב חצות לילה אקום<sup data-n=\"1160\">19</sup> להודות לך, דלילה חצי הראשונה הוא גבורות וחצי השני' מתחלשים הגבו' ורגע דחצות מחבר שניהם וזהו חצי התהלים וזה [דוקא] מברר. וזהו כל הולך על גחון ו' דגחון מפסיק כח הנחש, שטן בגימ' נחש, ותורה מחליש כחו שיהי' ואהבת את ה' אלקיך בכל לבבך בשני יצריך.",[["1156","15","<b>המשל ופחד עמו עושה שלום במרומיו</b>: ראה בשם הה\"מ: לקו\"ת תזריע כג, ג (ובהמ\"מ לשם). ביאוה\"ז ח, ג. סה\"מ תקס\"ג ח\"א ע' נב. סה\"מ אתהלך לאזניא ע' יב. ובביאור ד\"ה ביום השמיני עצרת דתקע\"ב (לא נדפס לע\"ע) מובא קרוב לענין זה בזה\"ל: ”בשם הה\"מ ששמע [כ\"ק אדה\"ז] ממנו סוכות האחרון תקל\"ג\"."],["1157","16","<b>לשמור מצותיו</b>: ראה לקו\"ת דברים שם כג, ג ואילך."],["1158","17","<b>וזהו הע' דמיער</b>: ראה גם לקו\"ת דברים ל, ב."],["1159","18","<b>ספור</b>: כ\"ה בגוכי\"ק. ובס' מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' פז: לפי שתלים הוא סיפור שבחי הבורא ית' כו'. ועיג\"כ בשאר מקומות שנסמנו לעיל בתחילת המאמר."],["1160","19","<b>וכתיב חצות לילה אקום</b>: ראה גם אוה\"ת ויקרא ע' רמד."],["e21","*","<b>עי\"ז מברר אותם</b>: בצד הגליון רשום בגוכי\"ק: ע' בביכל הקטן, רד\"צ ( ), ט\"ל."]]],[2000460370,"<h3>והמשכילים יזהירו</h3>\n<b>ש\"פ תו\"מ ט\"ל, לפ\"ק.</b>\n<b>והמשכילים</b> יזהירו כזהר הרקיע<sup data-n=\"1161\">1</sup> ומצדיקי הרבים ככוכבים ואמרז\"ל זה הדן דין אמת לאמיתו וגבאי צדקה, וצ\"ל מה שייך גבאי צדקה להמשכילים יזהירו כזהר הרקיע.\n<b>והנה</b> להבין ענין זהר הרקיע צ\"ל ענין מתיבתא דרקיע דאמרז\"ל קא מיפלגי במתיבתא דרקיע בהרת קדמה לשער לבן טמא, שער לבן קדמה לבהרת טהור, ספק, הקב\"ה אמר טהור וכולהו מתיבתא דרקיע אמרי טמא, מאן נוכח רבה בר נחמני נוכח שאמר אני יחיד בנגעים ובאהלות עד שאמר טהור טהור, ובמ\"א איתא מדכתיב לטהרו או לטמאו פתח הכתוב בטהרה תחילה שספק טהור. והנה צ\"ל מה שאנו רואין שתנאים ואמוראים עשו ניסים גדולים ועצומים שיוצאים מדרכי הטבע לגמרי כמו רפב\"י שא' גנאי נהרא חלוק לי מימיך וחלק למימיו, שזה הי' נס שיוצא מדרכי הטבע גבי משה וס' ריבוא ישראל, וכמאמר זוטרי דמנייכו מחי' מתים, וצ\"ל זה.\n<b>והנה</b> להבין מ\"ש הקב\"ה אומר טהור צ\"ל השם דקדב\"ה<sup data-n=\"1162\">2</sup> שחז\"ל קראו את הבורא בשם הקב\"ה, קדוש הוא שקדוש ומובדל מגדר עולמות, שאינו כמו הנשמה שממלאה את הגוף שמחי' את הגוף ומתפעלת ממקרי הגוף<sup data-n=\"1163\">3</sup>, אבל על למעלה כתי' אני הוי' לא שניתי שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנבה\"ע ואתה הוא לאחר שנברה\"ע שהוא קדוש ומובדל, הגם שהחיות הוא מבחי' סוכ\"ע מ\"מ הוא בבחי' מקיף וגם בהעלם, דאני מלא אך הוא בהעלם. ועל ל' הקבלה יש ג' מדרי' שנק' קדוש<sup data-n=\"1164\">4</sup>, דעת, ת\"ת, יסוד, שהוא קו האמצעי שעולה עד הכתר, ובהם יש מלמטלמ\"ע ומלמעלמ\"ט, דעת הוא מלמטלמ\"ע והוא העמקת הדעת בהתבוננות איך שלא שניתי ואתה הוא קודם שנבה\"ע ואתה הוא לאחר שנברה\"ע, ועי\"ז יבוא להתקשרות והתחברות לבחי' קדוש ומובדל, וכמ\"ש דע את אלקי אביך ועבדהו בלב שלם שבחי' דעת הוא שיהי' התקשרות והתחברות בבחי' קדוש ומובדל, וזהו מלמטלמ\"ע, ות\"ת ויסוד הוא המשכת קדוש ומובדל מלמעלמ\"ט, וזהו קדוש.",[["1161","1","<b>והמשכילים יזהירו כזהר הרקיע</b>: הנחה בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב מהמאמר הנדפס לעיל ע' קנח ואילך. והוא מיוסד על ד\"ה קא מיפלגי במתיבתא דרקיע בלקו\"ת תזריע כב, סע\"ב ואילך. וראה בהנסמן עוד בהמ\"מ בתחילת המאמר שם."],["1162","2","<b>צ\"ל השם דקדב\"ה</b>: בהבא לקמן ראה [נוסף ללקו\"ת תזריע שם] לקו\"ת שה\"ש כא, ב. מ, ג. סה\"מ תרל\"ד ס\"ע צז ואילך. ועוד."],["1163","3","<b>הנשמה. . ומתפעלת ממקרי הגוף</b>: ראה לעיל ע' קיב. וש\"נ."],["1164","4","<b>ועל ל' הקבלה יש ג' מדרי' שנק' קדוש</b>: בהבא לקמן ראה אוה\"ת ויקרא (כרך ד) ע' א'נג-ד. וראה גם לקו\"ת אמור לג, סע\"ב ואילך."]]],[2000460371,"<b>וברוך</b> יש בו ב' פירושים<sup data-n=\"1165\">5</sup>, א' שהוא ראש דסדר השתל' שהוא מקור הברכה וזהו ברו\"ך ר\"ת ראש ומקור כל ברכה<sup data-n=\"1166\">6</sup>, והוא כמ\"ש רחום וחנון לא שהוא מקבל רחמים אלא שנמשך בחי' רחום וכמו\"כ חנון, וזהו ברוך שהוא מקור הברכה. והב' כמ\"ש והמלך שלמה ברוך שמתברך<sup data-n=\"1167\">7</sup> מבחי' שלמעלה ממנו. וצ\"ל ענין שלמה הנה אמרז\"ל מלך שהשלום שלו, שלום הוא שמחבר ב' ענינים נפרדים שיהיו כאחד, וכמו\"כ למעלה אין מלך בלא עם וצ\"ל עם עוממות נבראים נפרדים ואיך אפשר להתחבר אלקות עם נבראים נפרדים, זהו שלום שהוא מחבר אותם, וצ\"ל ביטול היש, וזהו ברוך שמתברך מבחי' ראש ומקור כל ברכה. ונמצא יש כאן ג' בחי' קדוש ומובדל, וראש ומקור כל ברכה, והמקבל הברכה, וידוע דמקיפי' ופנימי' דבוקים זה בזה, דהמקיף הוא לפ\"ע הפנימי. וזהו הקב\"ה, קדוש סוכ\"ע, וברוך ממכ\"ע, שנמשך בדרך מקיף.\n<b>ועתה</b> צ\"ל ענין מתיבתא דרקיע דהנה כתי' ועל ראשי החיה רקיע כעין הקרח הנורא, דהנה ידוע דיש חיון עילאין וחיון תתאין, חיון תתאין הוא מחנה מיכאל מחנה גבריאל כו', וחיון עילאין הם אבות הן המרכבה, וצ\"ל מ\"ש חי' והול\"ל חיות. והענין דהנה מל' נק' חיה דכתי' ואתה מחי' את כולם שמחי' ומהווה עולמות נבראים, וראשי החי' הם אבות אברהם יצחק ויעקב, יצחק הוא צמצומים גבורות העלאות, ואברהם הוא להיפך המשכות מלמעלמ\"ט והוא קו הימין, יעקב ת\"ת קו האמצעי שמחבר ב' המדריגות ועי\"ז אפ\"ל שיחי' ויהווה נבראים. ועל ראשי החי' רקיע כעין הקרח הנורא, דהנה יש אור מים רקיע<sup data-n=\"1168\">8</sup>, כמו באדם יש משכיל שהוא מקור השכל, וגילוי השכל, והשגה והבנה, והנה כשהשכל בא בהשגה והבנה אז א\"א לנטותו לשום צד אבל כשהוא עדיין ברק המבריק אז יכולים לנטותו לצד זה ולצד זה, וזהו רקיע אגלידו מיא, דמים ניידי, אבל רקיע הוא כשנגלד וזהו השגה והבנת השכל, ולמעלה הוא להבין דבר מתוך דבר, תוך דבר הוא ממכ\"ע ודבר הוא סוכ\"ע<sup data-n=\"1169\">9</sup>, ומממכ\"ע יבין סוכ\"ע, וזהו בחי' בינה למעלה, ומתיבתא דרקיע הוא שמבחי' רקיע נמשך במתיבתא שהוא בחי' גבוה שהוא בחי' בינה ששם שורה אוא\"ס.\n<b>והנה</b> הזוכים לזה שהוא מדרי' גבוה וקוב\"ה אתי לאשתעשעא עם צדיקיא, זהו דוקא תנאים ואמוראים ע\"י עסק התורה לשמה כמאמר ר\"י עסיק בה לשמה, ר\"י הוה מצלי מתלתין יום לתלתין יום, דתפלה הוא התבוננות איך שלגדולתו אין",[["1165","5","<b>וברוך יש בו ב' פירושים</b>: בהבא לקמן ראה [נוסף ללקו\"ת תזריע שם] לקו\"ת שה\"ש כה, ד. וראה גם לקו\"ת דברים א, ג."],["1166","6","<b>ברו\"ך ר\"ת ראש ומקור כל ברכה</b>: ראה גם תו\"א שמות נג, ב."],["1167","7","<b>כמ\"ש והמלך שלמה ברוך שמתברך</b>: ראה גם לקו\"ת שה\"ש שם כח, ד. ביאוה\"ז לאדהאמ\"צ קב, א."],["1168","8","<b>דהנה יש אור מים רקיע</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח ע, א ואילך. סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. תרל\"ח ע' קסא ואילך."],["1169","9","<b>להבין דבר מתוך דבר תוך דבר. . ממכ\"ע ודבר. . סוכ\"ע</b>: ראה תו\"א בראשית א, א. לקו\"ת ואתחנן ו, ג."]]],[2000460372,"חקר פי' לגדולתו העצמיות אין חקר דכללות השתל' העולמות הוא רק שם והארה בעלמא שאינו נוגע לעצמיות ואין בערך כלל שאינו שייך לומר שהוא כמו ערך טיפה לגבי ים אוקינוס דאר\"י יכולני לשער כמה טיפות יש בים הרי שייך בזה השערה ומדידה, אבל עולמות לגבי אוא\"ס אין ערוך כלל, וזהו שאו מרום עיניכם וראו מי ברא אלה, אלה הם ו\"ק כלולים מו'<sup data-n=\"1170\">10</sup> הוא בגי' אל\"ה, והו\"ע ראשי החיה, ומי ברא בחי' אלה, דהנה והחכ' מאין תמצא דחכ' מבחי' אין דכתר הוא כמו מציאה והוא ע\"ד בריאה יש מאין, וא\"כ יובן מ\"ש מי ברא אלה שהוא בדרך בריאה, וע\"ז נא' מבטן מי יצא הקרח שבחי' רקיע כעין הקרח הנורא יצא מבטן מי, ועי\"ז יבא לדאגה ומרירות דאין מוסרין סתרי תורה אלא מי שלבו דואג בקרבו דלית מחתב\"כ אפי' עולמות עליונים אינם תופסים בו כלל, וזהו שדואג מה שאין לו השגה באוא\"ס. וע\"י תורה פקודי ה' ישרים משמחי לב<sup data-n=\"1171\">11</sup> שמשמח את הלב שדואג, דהנה לית מח' תפיסא בי' אבל בתורה יש תפיסא ואורייתא וקוב\"ה כולא חד ובעת הלימוד הוא מקיף ומוקף שהוא יחוד נפלא שאין כמוהו<sup data-n=\"1172\">12</sup>, ומ\"ש ישרים דהנה בסדר השתל' כל שלמטה יותר מתמעט כמו יחידות עשירות מאות<sup data-n=\"1173\">13</sup>, מאות בבריאה עשירות ביצי' יחידות בעשי' הרי שנתמעט, וזהו שא' ישרים שיומשך למטה כמו למעלה. וזהו עוד פי' בקדב\"ה שקדוש ומובדל יומשך למטה כמו למעלה וזהו ע\"י תורה.\n<b>והנה</b> תורה צ\"ל בדיבור דוקא דאי' בס\"י ע\"ס בלי מה כשלהבת הקשורה בגחלת, דהנה שלהבת הקשורה בגחלת הוא בהעלם בתוך הגחלת וע\"י רוח שנופח בפיו מוציא מהעלם לגילוי, והוא בחי' כי הוי' אלקיך אש אוכלה הוא שם הוי', וכמו\"כ בתורה ע\"י הדיבור שהוא רוח ממללא מוציא מהעלם אל הגילוי דרוח הוא מדריגה גבוה כמ\"ש עד שיערה עלינו רוח ממרום שהרוח הוא ממרום ובס\"י כ' אחר ע\"ס בלי מה כו' אחת רוח אלקים חיים הרי שהוא אחת. אך מ\"מ כ\"א ממשיך לפ\"ע מדריגתו, דתנאים ואמוראים שהי' להם מוחין דגדלות לכן הראו אותות ומופתים שיוצאים מדרכי הטבע וכמו רפב\"י שא' גנאי נהרא חלוק לי מימיך וחלק מימיו, דים ויבשה הוא עלדאת\"כ ועלמדאת\"ג<sup data-n=\"1174\">14</sup> והוא העלם וגילוי דסדר השתל', וע\"י תורה ממשיכים מבחי' שלמעלה מעלדאת\"כ ועלדאת\"ג, וזהו מקצה השמים דא עלמא עילאה כו' ה\"ה קצה וקצה אבל באוא\"ס ב\"ה אינו שייך לומר ח\"ו קצה וקצה, לכן הפך ים ליבשה.\n<b>ועתה</b> יובן הספק, ספק אם בהרת קדמה אם שער לבן קדמה מתיבתא דרקיע אמרי טמא כבכל מקום דספיקא דאורייתא לחומרא, והקב\"ה אומר טהור דקדוש",[["1170","10","<b>אלה הם ו\"ק כלולים מו'</b>: ראה גם לקו\"ת פקודי ד, ג. במדבר ו, ד. ובכ\"מ."],["1171","11","<b>וע\"י תורה פקודי ה' ישרים משמחי לב</b>: ראה בכ\"ז בארוכה לקו\"ת פנחס עח, ב."],["1172","12","<b>ובעת הלימוד הוא מקיף ומוקף. . יחוד נפלא שאין כמוהו</b>: ראה בכ\"ז תניא פ\"ה (ט, א ואילך)."],["1173","13","<b>כמו יחידות עשירות מאות</b>: ראה לקו\"ת בלק עד, ב. ועוד."],["1174","14","<b>דים ויבשה הוא עדלאת\"כ ועלמדאת\"ג</b>: ראה בכ\"ז לעיל ד\"ה אז ישיר. וש\"נ."]]],[2000460373,"הוא בחי' קדוש ומובדל ומצד בחי' זו טהור, מאן נוכח רבה בר נחמני שהוא מבחי' והמשכילים יזהירו כזהר הרקיע והוא יודע כמו שהוא בסובב לכן אמר טהור. והענין דהנה כתי' משכיל לאיתן האזרחי, איתן קשה<sup data-n=\"1175\">15</sup> והוא הביטול שלמעלה מטו\"ד והוא בחי' משכיל, וזהו יזהירו כזהר הרקיע שהוא בחי' אור, וכמו\"כ בצדקה כתי' צדקה כנחל איתן לכן גבאי צדקה נק' משכילים. ועפ\"י פשוט י\"ל והמשכילים יזהירו כו' אותן שמשכילים בתורה ותפילה, תפלה הוא שמעמיק דעת בהתבוננות שיהיה לבו דואג בקרבו, ואח\"כ מקשר דעתו בתורה, יזהירו כזהר הרקיע שעי\"ז ממשיכים בחי' אור שלמעלה מרקיע.\n<b>ועתה</b> יובן מ\"ש במתניתא תנא זה הדן דין אמת לאמיתו, דהנה אמרז\"ל כל דיין שדן דין אמת ה\"ה שותף להקב\"ה במע\"ב, דהנה ברה\"ע הי' בבי\"ת, ך\"ו דורות קרא האל\"ף תגר שלא הי' בו ברה\"ע, והטעם מפני שא' הוא ארור וב' ברכה<sup data-n=\"1176\">16</sup>, פי' מצד האל\"ף שהוא כחשיכה כאורה ויוכל לימשך אפי' למקום שאינו ראוי, לכן הי' בבי\"ת שיומשך למקום הראוי דוקא, ומ\"ת הי' באל\"ף דאחר שהי' ברה\"ע בבי\"ת אפ\"ל מ\"ת באל\"ף שיומשך למקום הראוי דוקא, והוא כמ\"ש בעבור זה לא אמרתי אלא בשעה שיש מצה ומרור מונחים לפניך אף שהי' הגילוי מבחי' [שלמעלה מסדר השתל'] מ\"מ דוקא בשעה שיש מצה שהוא חכ' ביטול<sup data-n=\"1177\">17</sup>. וזהו עוד פי' בהקב\"ה שבחי' קדוש ומובדל יומשך ע\"י ברוך שיומשך למקום הראוי דוקא. וזהו כל דיין שדן דין אמת נעשה שותף להקב\"ה במע\"ב, דין אמת שלא יהי' דין מרומה כן פי' התוס', דהגם שהעדות הוא כמו א' מהם מ\"מ יבין הדיין שהוא דין מרומה ה\"ז מצד המשכיל, וכמו\"כ למעלה כתי' ויבואו בני אלקים ויתיצבו שמקטרגים על ישראל שח\"ו ישראל חטאו, אך הקב\"ה יודע דהצדק עם ישראל וזהו מצד המשכיל, וזהו והמשכילים יזהירו כזהר הרקיע שהוא בחי' אור שלמעלה ממים רקיע.",[["1175","15","<b>דהנה כתי' משכיל לאיתן האזרחי איתן קשה</b>: ראה לקו\"ת ראה יח, א. סה\"מ תרל\"ג ח\"ב ע' תמד. [ובהנסמן שם בתחילת המאמר]."],["1176","16","<b>דהנה ברה\"ע הי' בבי\"ת ך\"ו דורות. . שא' הוא ארור וב' ברכה</b>: ראה בכ\"ז מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ובהנסמן לעיל ע' קסד."],["1177","17","<b>כמ\"ש בעבור זה. . דוקא בשעה שיש מצה. . ביטול</b>: ראה בכ\"ז לקו\"ת צו יב, ג."]]],[2000460374,"<h3>הללוי' הללו את ה' מן השמים</h3>\n<b></b><b>בס\"ד ש\"פ תו\"מ ט\"ל לפ\"ק</b>\n<b>הללויה</b> הללו את ה' מן השמים<sup data-n=\"1178\">1</sup> כו' ואי' ברש\"י בשבת דשני מזמורים הללויה הללו את ה' מן השמים ומזמור הללו אל בקדשו הם עיקר פסוד\"ז. ואפ\"ל דהנה אי' בזהר דשני מזמורים אלו הם כללא דתושבחתא, דבמזמור הללו אל בקדשו נרמז ע\"ס, ובמזמור הללו את ה' מן השמים נכלל התשבחות דכללות העולמות שהם נכללים בשמים וארץ. ובפרטיות אי' בסידור האריז\"ל הללו את ה' מן השמים אצי', הללוהו במרומים בריאה, הללוהו כל מלאכיו יצי', הללוהו כל צבאיו עשי'. הללוהו שמש וירח התכללות עשי' ביצי', הללוהו כל כוכבי אור התכללות יצי' בבריאה, הללוהו שמי השמים התכללות בריאה באצי', והמים אשר מעל השמים התכללות אצי' בא\"ס עצמות המאציל. הללו את ה' מן הארץ חשיב כאן ד' יסודות ארמ\"ע ודצח\"מ, אש יסוד האש, וברד שלג וקיטור יסוד המים, דקיטור העשן הוא מן המים דעצים שיש בהם הרבה לחלוחית עולה עשן הרבה, רוח סערה יסוד הרוח, ההרים וכל גבעות יסוד העפר ודומם, עץ פרי וכל ארזים צומח, החי' וכל בהמה חי בלתי מדבר, מלכי ארץ וכל לאומים שרים וכל שופטי ארץ בחורים וגם בתולות זקנים עם נערים מדבר, ואח\"כ אומרים יהללו את שם ה' כי נשגב כו' לבנ\"י עם קרובו כמ\"ש אשר לו אלקים קרובים ואי' במד' אשר לו גוי קרוב אין כתיב כאן אלא אשר לו אלקים קרובים, כבי' אלקי' קרובים אליו, וצ\"ל שהוא מצד ש' הוי'<sup data-n=\"1179\">2</sup> דכתי' קודם לזה לכן ישראל קרובי' אליו אבל מצד שם אלקים אלקים קרובי' אליו.\n<b>והענין</b> דהנה אמרז\"ל כל המאריך באחד שצריכין אריכות ההתבוננות באחד ולכן צריכים תחילה פסוד\"ז וברכות ק\"ש, הגם שדורות הראשונים<sup data-n=\"1180\">3</sup> תנאים ואמוראים היו ממעטים בתפלה ומכ\"ש בפסוד\"ז, זהו מפני שהיו נשמות גבוהות ומיד שהתבוננו נקבע בלבם אחדות אחד האמת ולא הי' חולף ועובר, אבל אנו שנתגשמנו ונתרחקנו מרוחניות צריכים אנו אריכות ההתבוננות. ומה אומרים בק\"ש שמע ישראל הוא מ\"ש לבנ\"י עם קרובו.\n<b>ה'</b> אלקינו ה' אחד, הנה אי' ברמב\"ם ליחדו שנא' הוי' אלקינו ה' אחד<sup data-n=\"1181\">4</sup>, וצ\"ל דהול\"ל יחיד שמורה על אחדות יותר מאחד<sup data-n=\"1182\">5</sup>, דהנה שימ\"ב דכתי' ששת ימים כתי' ויהי",[["1178","1","<b>הללוי' הללו את ה' מן השמים</b>: הנחת כ\"ק אדמו\"ר מוהרש\"ב מהמאמר שנדפס לעיל ע' קסה ואילך. — וראה בהנסמן שם לכללות המאמר.\nבכותרת המאמר נרשם: ”בס\"ד. ש\"פ תו\"מ [ תזריע ומצורע] ט\"ל, לפ\"ק\", אך במפתח המאמרים שבגוכתי\"ק אדמו\"ר מוהרש\"ב נרשם: אחו\"ק. וכן נרשם בכמה כת\"י. וראה במ\"מ להלן ס\"ע שטו."],["1179","2","<b>אשר לו אלקים קרובים. . וצ\"ל שהוא מצד ש' הוי'</b>: ראה בכ\"ז לקו\"ת שלח מ, ד."],["1180","3","<b>והענין דהנה אמרז\"ל. . הגם שדורות הראשונים</b>: בהבא לקמן ראה לקו\"ת ואתחנן יב, ב-ג. וראה גם לקמן ח\"ב ד\"ה עבדו את ה' בשמחה."],["1181","4","<b>אי' ברמב\"ם ליחדו שנא'. . ה' אחד</b>: ראה בכ\"ז סה\"מ תרכ\"ו ע' טז. נג. וס\"ע קסב ואילך. תרכ\"ט ע' קנו ואילך."],["1182","5","<b>ה' אחד וצ\"ל דהול\"ל יחיד. . אחדות יותר מאחד</b>: בהבא לקמן ראה תו\"א וארא נה, ב ואילך. לקו\"ת תזריע כג, ג. בלק ע, א. אמ\"ב שער הק\"ש פ\"ח דרמ\"צ קכד, א-ב. סה\"מ תרכ\"ו ע' קסג-ד. תרכ\"ז ע' רכג-ד. תרכ\"ט שם ע' קנו ואילך."]]],[2000460375,"ערב ויהי בקר יום אחד הגם שיש שני ושלישי מ\"מ הראשון נק' אחד, וכמו\"כ י\"ב שבטים א' מהם נק' אחד וכמ\"ש שלחו מכם אחד, אחיכם אחד, ומפתח אחד<sup data-n=\"1183\">6</sup>, אבל למעלה אינו שייך לומר זה דכתי' יש אחד ואין שני לו, והול\"ל יחיד, דבזה נכלל שיתוף ג\"כ, ומהו אומרו אחד. וצ\"ל שענין האחדות מרומז באחד יותר מביחיד. והענין דהנה יחיד הוא שא\"ס הוא יחיד ומיוחד והוא למעלה מסוכ\"ע וממכ\"ע, דאני הוי' לא שניתי שלא יש שום שינוי, ואתה הוא קודם שנברה\"ע ואתה הוא לאחר שנברה\"ע, והוא למעלה מסוכ\"ע וממכ\"ע, ואחד הוא מקור העולמות, וזה מרומז בתי' אחד דח' מורה על ז' רקיעים וארץ, ואת השמים כולל כל צבא השמים ואת הארץ כולל כל צבא הארץ, ולמעלה הם ז' מדות העליונות, וד' הוא ד' רוחות העולם, ואל\"ף הוא המהווה כולם, וזהו אחד שז' רקיעים וארץ וד' רוחות העולם בטלים לא\"ס אלופו ש\"ע. וזהו מרומז בתי' אחד דוקא, דיחיד מורה שא\"ס הוא יחיד ומיוחד אבל הנבראים הם יש ודברים נפרדים, אפי' בריאה יש מאין מ\"מ אפ\"ל שהנבראים הם יש ודבר נפרד, אבל אחד מורה שאפי' אחר שנעשו ז' רקיעים וארץ וד' רוחות העולם מ\"מ הם בטלים לא\"ס אלופו ש\"ע. וזהו שכ' ברמב\"ם הוא שא' הנביא ה' אלקים אמת ואין אמת מאמיתתו שאפי' כמו שנבראו העולמות מ\"מ בטלים בתכלית<sup data-n=\"e22\">*</sup>.\n<b>והנה</b> ז' רקיעים והארץ למעלה הם מדות, דהנה שמים הם אש ומים והוא ביטול המדות למד' דלמכאמ\"כ<sup data-n=\"1184\">7</sup> והוא בחי' יחיד. דהנה כתי' הבט משמים וראה וכן השקיפה ממעון קדשך מן השמים, וצ\"ל למה שמים דוקא. והענין דהנה אמרז\"ל נטל אש ומים ופתכן זה בזה ומזה נעשה שמים, אש הוא גבורה העלאות מלמטה למעלה, ומים הוא חסדי' מים יורדים מגבוה לנמוך, ות\"ת הוא המחברן, וזהו שאמרו יצחק ויעקב בגי' שמים<sup data-n=\"1185\">8</sup>, דיצחק הוא גבורה אש העלאה מלמטה למעלה, ואברהם מים המשכה מלמעלמ\"ט, ויעקב ת\"ת המחברם, והוא ביטול המדות לבחי' לאמכ\"א מא\"כ<sup data-n=\"1186\">9</sup>,",[["1183","6","<b>הגם שיש שני ושלישי מ'מ הראשון נק' אחד. . ומפתח אחד</b>: לעיל בהמאמר לא הובאה ראי' זו ממ\"ש ”ומפתח אחד\", ונראה דהכוונה ליחזקאל מא, יא: פתח אחד דרך הצפון ופתח אחד לדרום."],["1184","7","<b>למד' דלמכאמ\"כ</b>: למדריגה דלאו מכל אלין מדות כלל."],["1185","8","<b>וזהו שאמרו יצחק ויעקב בגי' שמים</b>: בסה\"מ תרכ\"ז ע' קעב מביא זה בשם ס' פנים יפות (להרה\"ק ר' פנחס הורביץ בעמ\"ח ספר ההפלאה) פ' וזאת הברכה ע\"פ רוכב שמים בעזרך."],["1186","9","<b>לאמכ\"א מא\"כ</b>: לאו מכל אלין מדות איהו כלל. (ועד\"ז הובא לקמן בכ\"מ)."],["e22","*","<b>בשולי הגליון נרשם בגוכתי\"ק (וכנראה שייך כאן, ראה לעיל ע' קסז)</b>: [וזהו ביום ההוא יהי' הוי' ושמו אחד ופריך בגמ' אטו האידנא לאו אחד הוא ותירצו ב' תירוצים לא כמו שאני נכתב אני נק' כו' (ואפ\"ל שלע\"ל יהי' בחי' אחד היינו איך שכל העולמות בטלים לא\"ס אלופו ש\"ע)]."]]],[2000460376,"וזהו שמים יש בו תי' מים בשלימות, ואש רק השי\"ן<sup data-n=\"1187\">10</sup>, מפני שז\"א רובו חסדים וכמ\"ש זכר חסדו. וזהו שאנו אומרים הבט משמים דוקא כדי שיהי' ואוהב את יעקב, דמצד בחי' לאמכ\"א מא\"כ אפשר שיומשך אפי' למקום שאינו ראוי, אבל ע\"י העלאת המדות לבחי' לאמכ\"א מא\"כ נמשך לשמים, והנה אהבה הוא פנימיות החסד<sup data-n=\"1188\">11</sup> ומשם נמשך שיומשך למקום הראוי דוקא, לכן מבקשים שיומשך לשמים.\n<b>וביאור</b> הענין דהנה כתי' לך ה' הגדולה<sup data-n=\"1189\">12</sup> והגבורה כו' כי כל בשמים ובארץ, הנה לך וכל שוים אותיותיהם, אלא שלך הוא מלמטלמ\"ע, וכל הוא מלמעלמ\"ט. דהנה המספר דלך וכל הוא חמישים, ואמרז\"ל חמשים שערי בינה נבראו בעולם, וענין השערים<sup data-n=\"1190\">13</sup> הוא שמשם נמשך לידת המדות, דמדות משכנם בלב אבל נולדים מהבינה, דאהבה הוא מצד שמתבונן בשכלו שטוב לו הדבר ההוא רוצה בה, ואם יתבונן בשכלו שאינו טוב לו אינו רוצה בה, הרי שהם נולדים מהבינה, וז' כלול מז' הוא מ\"ט, ושער הנו\"ן הוא בינה בעצם, וזהו לך ה' הגדולה שמדת הגדולה הגם שהיא מדריגה גבוה שבה הי' ברה\"ע וכמארז\"ל והגדולה [זו מעשה בראשית], מ\"מ טפל ובטל לך היינו ע\"י השערים. וזהו כגוונא דאינון מתייחדין לעילא<sup data-n=\"1191\">14</sup> באחד, אינון הם מדות, לעילא הוא בינה, דהתגלות עתיק בבינה, והוא בחי' יחיד, וזהו אחד ביטול המדות למד' לאמכאמא\"כ. וזהו שאמרו השבטים ליעקב כשם שאין בלבך אלא אחד<sup data-n=\"1192\">15</sup>, יעקב הוא בחי' ת\"ת המחבר חו\"ג, אלא אחד הביטול לבחי' לאו מכל אילין מדות איהו כלל, ועי\"ז אח\"כ כי כל בשמים וארץ שיומשך בהשמים וארץ שיומשך למטה ג\"כ כשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד וכמ\"ש כגוונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד. וזהו מ\"ש כל תשא עון ופי' המגיד<sup data-n=\"1193\">16</sup> שהוא בחי' סובב הכללי, שלמעלה מסוכ\"ע שהוא סובב הפרטי, וזהו כי כל בשמים כו' שיומשך בשו\"א. והוא ע\"ד מ\"ש מי עלה שמים<sup data-n=\"1194\">17</sup>, שהשמים עולה בבחי' מי, והוא כמ\"ש מי יתן והי' לבבם זה ליראה אותי כל הימים",[["1187","10","<b>שמים. . תי' מים בשלימות ואש רק השי\"ן</b>: ראה סה\"מ תרכ\"ז ע' קע. [ובהנסמן שם]."],["1188","11","<b>אהבה הוא פנימיות החסד</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיד ואילך. דרמ\"צ יב, ב ואילך. סה\"מ תרל\"א ע' קצה. וש\"נ."],["1189","12","<b>וביאור הענין דהנה כתיב לך ה' הגדולה</b>: בהבא לקמן ראה סה\"מ תר\"ל ע' קסט ואילך. תרל\"ד ע' רל ואילך. המשך מים רבים תרל\"ו פמ\"ו ואילך. ועוד."],["1190","13","<b>חמשים שערי בינה. . וענין השערים</b>: בהבא לקמן ראה בארוכה לקמן ח\"ב ד\"ה מזמור לתודה. וש\"נ."],["1191","14","<b>וזהו כגוונא דאינון מתייחדין לעילא</b>: בהבא לקמן ראה בארוכה סידור עם דא\"ח קסח, א ואילך."],["1192","15","<b>וזהו שאמרו. . כשם שאין בלבך אלא אחד</b>: בהבא לקמן ראה גם תו\"א תצוה פד, סע\"ד. פז, ג. סידור עם דא\"ח קסח, א-ב. שערי תשובה לאדהאמ\"צ ח\"ב יט, רע\"א ואילך. סה\"מ תרכ\"ז ע' שפד. וש\"נ."],["1193","16","<b>וזהו מ\"ש כל תשא עון ופי' המגיד</b>: ראה סה\"מ תרכ\"ט ע' קכו. וראה גם שם ע' קיג. המשך תער\"ב ח\"א ע' קמט. סה\"מ תרצ\"ו ע' 129. סה\"מ מלוקט ח\"א ע' קע. ח\"ג ע' כא."],["1194","17","<b>והוא ע\"ד מ\"ש מי עלה שמים</b>: בהבא לקמן ראה בארוכה ביאוה\"ז לאדהאמ\"צ נה, ד ואילך. ולהצ\"צ ח\"ב ע' תתלד ואילך."]]],[2000460377,"ואמרז\"ל הכל תלוי בידי שמים חוץ מיראת שמים. וצ\"ל והלא דוד א' יחד לבבי ליראה<sup data-n=\"1195\">18</sup> שמך וכן אנו אומרים ויחד לבבינו לאהבה וליראה את שמך. אך הענין הוא דהנה יראת שמים אינו תלוי בידי שמים אלא בבחי' מי, דאם הי' בידי שמים הי' הידיעה מכרחת הבחירה, אבל מצד בחי' מי אין הידיעה שהוא בחי' ד\"ע מכרחת הבחירה<sup data-n=\"1196\">19</sup>, דמי הוא בחי' שאינו מושג, וכמ\"ש מי יתן טהור מטמא, מי יתן מותינו במדבר, וזהו מי עלה שמים, שהשמים עולה במי ואח\"כ וירד שאז נמשך בהשמים<sup data-n=\"e23\">*</sup>.\n<b>וזהו</b> הללויה הללו את ה' מן השמים שהוא העלאת השמים מדות עליונות למדרי' לאו מכאמא\"כ, ועי\"ז הללוהו במרומים שנמשך בבריאה, דעצם השמים א\"א לראות דכגבוה שמים מארץ, בין ארץ לרקיע מהלך ת\"ק שנה, ומה שאנו רואין הוא רק זהרורית השמים וזהו בריאה, הללוהו כל מלאכיו יצי' שהם מלאכים שלוחי השפע כגרזן ביד החוצב בו, דהנה כתי' אלף אלפים ישמשוני' וריבוו רבבן קדמוהי יקומון, דיש מלאכים שהם ישמשוני' שלוחי השפע, ויש שהם קדמוהי יקומון שאינם שייכים להשפעה, וכמ\"ש יוצר אור ובורא חשך בריאה הוא חושך שאינו שייך להשפעה העלם, ויצי' אור גילוי, צבאיו עשי' שהם עושים רצה\"ע וכמו עושים צביונו פי' עושים רצונו. הללוהו שמש וירח התכללות עשי' ביצי' דשמש וירח הם ז\"א ומל' דז\"א מקננא ביצי' ואימ' תתאה מקננא בעשי', כוכבי אור התכללות יצי' בבריאה דכוכבי' הם ברקיע תמינאה שהוא בינה ואימא עילאה מקננא בכורסייא. ואח\"כ אומרים יהללו את שם ה' כי הוא צוה ונבראו ולכאו' והלא כתי' בראשית ברא אלקים והול\"ל ברא ומהו ונבראו. והענין דהנה ברא שייך באלקים שהוא כח הפועל בנפעל, אבל עיקר ההתהוות מצד שם הוי' דהוי' לשון מהווה, וע\"ז אינו שייך לומר ברא אלא ונבראו, בדרך מאיליו וממילא<sup data-n=\"1197\">20</sup>, וכמו מי שאמר והי' העולם מאיליו וממילא, ומזה אפ\"ל מי שאמר לשמן וידליק יאמר לחומץ וידליק שהוא למעלה מטבע. ויעמידם לעד לעולם, ית\"ל אי\"ה.\n<b>ואח\"כ</b> אומר אש כו' ד' יסודות ארמ\"ע ודצח\"מ, ואח\"כ יהללו שם ה' כי נשגב שמו לבדו הודו על ארץ ושמים, בכל המזמור אמר תחילה שמים הללו את ה'",[["1195","18","<b>ואמרז\"ל הכל בידי שמים חוץ מיראת שמים וצ\"ל והלא דוד א' יחד לבבי ליראה</b>: בהבא לקמן ראה בארוכה לקו\"ת במדבר טו, א. אוה\"ת בשלח ע' תרעג. ואתחנן ע' קצה-ו. עקב ע' תקסא. דרושים לשבת שובה ע' א'תצב. ביאוה\"ז להצ\"צ ח\"א ע' מו. ח\"ב שם ע' תתלד. יהל אור לתהלים ס\"ע לה-ו. סה\"מ תרל\"ה ח\"א ע' רכו."],["1196","19","<b>אין הידיעה. . ד\"ע מכרחת הבחירה</b>: ראה תו\"א וירא טו, א ואילך. סה\"מ תרכ\"ז ע' קעד."],["1197","20","<b>מצד שם הוי'. . אינו שייך לומר ברא אלא ונבראו. . מאיליו וממילא</b>: ראה בארוכה לקו\"ת שה\"ש יד, ג ואילך. סה\"מ תרכ\"ט ע' קלה ואילך. תרל\"ג ח\"א ע' כב. וש\"נ."],["e23","*","<b>בשולי הגליון נרשם בגוכתי\"ק (וכנראה שייך כאן, ראה לעיל ע' קע)</b>: [וזהו אשא עיני אל ההרים, היושבי בשמים תוס' יו\"ד שיומשך מבחי' [חכ'] למטה]."]]],[2000460378,"מן השמים ואח\"כ הללו גו' מן הארץ וכאן אומר ארץ קודם שמים. והענין דהנה הודו הוא תורה, דמלאכים אמרו אשר תנה הודך על השמים, אך לא נתן להם תורה כ\"א על הארץ דוקא, והשמים מקבלים מהארץ וכמ\"ש היושבת בגנים חברים מקשיבים לקולך השמיעני, היושבת בגנים היינו נשמות שיושבין בג\"ע ולומדים תורה ומלאכים מקבלים מהם, לכן א' ארץ ואח\"כ שמים.\n<b>ואח\"כ</b> אומר וירם קרן לעמו כו', והענין דהנה כתי' יראו את ה' קדושיו וצ\"ל למה קדושיו דוקא, והלא כתי' ייראו מה' כל הארץ<sup data-n=\"1198\">21</sup>. והענין דהנה יראו מה' שהוא יראה מרחוק מצד שם אלקים זהו כל הארץ, שכ\"א יוכל לבוא לבחי' זו, אבל יראו את הוי' דהיינו שיהי' טפל ובטל לש' ה' זהו דוקא קדושיו, קדשנו במצותיו וציונו, והוא מ\"ש לבנ\"י עם קרובו, ועי\"ז כי אין מחסור ליריאיו, אין הוא אין שלמעלה מסדר השתל', ועי\"ז נמשך מבחי' אין שלמעלה מסדר השתל', והנה זהו מ\"ש לבנ\"י עם קרובו.\n<b>וענין</b> הקרן הנה יש בזה כ\"פ ג' פי'<sup data-n=\"1199\">22</sup>, (א) ל' קרן זווית וכמ\"ש בזהר על משנה ובא לו לקרן דרומית מזרחית, ובא לו לקרן בקדמיתא קודם שיבוא לבחי' דרומית שהוא אהבה וכמ\"ש גבי אברהם הלוך ונסוע הנגבה, וצ\"ל קודם לזה קרן. והענין דהנה קרן עד\"מ קרן דרומית מזרחית הנה כמה שנמשך דרום הוא דרום, ומה שנמשך מזרח הוא מזרח, והקרן בעצמו אינו מציאות בפ\"ע כלל והוא מורה על ביטול, (ב) מלוכה נק' קרן כמ\"ש רמה קרני, קרן חזית, והוא ביטול העם אל המלך דהנה המלך הוא מציאות בפ\"ע והעם מציאות בפ\"ע והאיך הם מתחברים זהו ע\"י הביטול, ולמעלה הו\"ע קבלת עומ\"ש. ועי\"ז ממשיכים שיש עוד פי' (ג) ל' קרן עור פני משה, דהנה על משה כתי' ואנחנו מה שהוא בחי' חכמ\"ה כח מ\"ה, שהוא ראשית השתל', אבל קרן עור פני משה הוא למעלה מסדר השתל'. וזהו שממשיכים ע\"י הביטול, וזה א\"א לימשך ע\"י אהבה שהוא יש מי שאוהב אבל יראה שהוא אינו יש שהרי הוא בטל לכן עי\"ז ממשיכים בחי' זו. (היה נראה שמפרש לפי פי' הא' שהקרן הוא בחי' שהוא בטל תמיד מפני דנתב\"ס, ופי' הב' ביטול עולמות התחתונים לבחי' מל' וכ\"ז העלאה, ופי' הג' המשכה פי' שע\"י הביטול או ביטול דמל' או הביטול לבחי' מל' עי\"ז ממשיכים מאור הכתר כן נ\"ל עכ\"ה).\n<b>והנה</b> מ\"ש הללויה הללו את ה' מן השמים כו' הללו גו' מן הארץ הוא להמשיך חדוש הישינות, דבכ\"ע מחי' ומהווה נבראים והו\"ע בריאה יש מאין, ולזה צ\"ל זיווג חו\"ב, דבינה הוא יש כמ\"ש להנחיל אוהבי יש, וחכ' הוא אין דוהחכ' מאין",[["1198","21","<b>דהנה כתי' יראו את ה' קדושיו. . והלא כתי' ייראו מה' כל הארץ</b>: בהבא לקמן ראה בארוכה אוה\"ת בשלח ע' תס ואילך. וראה גם שם ע' תלב ואילך. סה\"מ תרכ\"ז ע' רמז ואילך. וש\"נ."],["1199","22","<b>וענין הקרן הנה יש בזה. . ג' פי'</b>: בהבא לקמן ראה ביאוה\"ז לאדהאמ\"צ קמד, ב ואילך. ולהצ\"צ ח\"א ע' תסד ואילך. אוה\"ת נ\"ך ע' קלו ואילך. וראה גם סה\"מ תרכ\"ט ע' רפט."]]],[2000460379,"תמצא, והוא זיווג חיצוני דחו\"ב, אבל ע\"י ביטול דוירם קרן לעמו ממשיכים תוס' אור חדש וצ\"ל קבלו מלכותי ואח\"כ קבלו גזירותי שהוא אשר קדשנו במצותיו וציונו, וזהו שע\"י היראה ממשיכים אור חדש."],[2000460380,"<h3>דרש ר' שמלאי תרי\"ג מצות</h3>\n<b></b><b>בס\"ד. הנחה פ' בשלח תרל\"ט, ליובאוויץ.</b>\n<b>דרש</b> ר' שמלאי<sup data-n=\"1200\">1</sup> תרי\"ג מצות נאמרו למשה מסיני רמ\"ח מ\"ע ושס\"ה מל\"ת ובא דוד והעמידן על אחד עשר הולך תמים ופועל צדק ודובר אמת בלבבו וכו' וכספו לא נתן בנשך, ואח\"כ בא ישעי' והעמידן על שש, ואח\"כ על שתים, עד שבא חבקוק והעמידן על אחת. ופרש\"י מפני שבדורות הראשונים היו יכולין לקיים כל התרי\"ג מצות אבל אח\"כ כשנתמעטו הלבבות שאינם יכולים לקיימם בא דוד והעמידן על אחד עשר. והקשו כל המפרשים הלא התורה היא נצחית, וכתי' לא תוסיפו ולא תגרעו שאפי' נביא אינו רשאי לחדש אפי' אות א' שצריכין לקיים כל התרי\"ג מצות, לא מבעי השס\"ה ל\"ת בודאי צריכין לקיים, אלא אפי' הרמ\"ח מ\"ע שיש איזה מצות מהם שאין יכולים לקיים בזמן הזה היינו מצות התלויות בכהן או בלוים או מצות התלוי' בארץ, אבל מ\"מ הרי פ\"ז מצות עשה נשארו<sup data-n=\"1201\">2</sup> שצריכין לקיימם, והאיך אמר שבא דוד והעמידן על אחד עשר, ותירצו שם מה שתירצו. אבל לפי האמת התירוץ הוא שמה שאומר שהעמידן על אחד עשר אין הפי' שנגרעו ח\"ו אלא העמידן בקיום, מפני שראה שאין יכולים לקיימם מצא המצאה שע\"י הי\"א כללים יבואו לקיים כל התרי\"ג מצות<sup data-n=\"1202\">3</sup>, וכמ\"ש מה הוי' שואל מעמך כ\"א ליראה, וחשיב שם לאהבה אותו ולדבקה בו ולכאורה הלא כתי' אחת שאלתי, אלא הפי' הוא שע\"י יראה במילא יבוא לאהבה אותו ולדבקה בו, כמ\"ש בדוד אחת שאלתי מאת הוי' אותה אבקש שבתי בבית הוי' וחשיב שם לחזות בנועם הוי' ולבקר בהיכלו, אלא",[["1200","1","<b>דרש ר' שמלאי</b>: מאמר זה הוא הנחת א' מהשומעים. ונמצא בכת\"י מס' 1185 קפה, א ואילך. התחלת המאמר נמצא לעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב (ע' ריח).\nהמאמר מיוסד על ד\"ה זה להצ\"צ בכת\"י מס' 1063 (נז, א ואילך). ונמצא בתוס' הגהות בד\"ה זה בסה\"מ תר\"ס ע' כט ואילך. מאמר הצ\"צ מיוסד על ד\"ה להבין מארז\"ל יפה שיחתן בס' מאמרי אדה\"ז תקס\"ג ח\"א ע' לו ואילך. ונו\"א בד\"ה והאיש משתאה בסידור עם דא\"ח צא, ג ואילך. ובאריכות הביאור בתו\"ח חיי שרה קלז ד ואילך. [וראה גם שם קלה, א ואילך]. ובתוס' הגהות באוה\"ת חיי שרה קכז, ב ואילך. וקיצורים והוספות שם קלג, א ואילך.\nוראה גם לעניני המאמר לקו\"ת ברכה צה, סע\"ב ואילך. ד\"ה יפה שיחתן: בסה\"מ תשל\"ב ע' 46 ואילך. תשל\"ו ע' 51 ואילך. תשל\"ט ע' 40 ואילך. תשמ\"ב ע' 56 ואילך. תשמ\"ה ע' 44 ואילך. תשמ\"ז ע' 36 ואילך. תשמ\"ח ע' 273 ואילך. סה\"ש תשנ\"ב ח\"א ע' 103 ואילך. פלח הרמון בראשית סו, ג ואילך. עב, א ואילך.\nלהתחלת וסיום המאמר ראה סה\"מ תרכ\"ז ע' טז-יז. תרל\"ד ע' מז-ח. פר\"ת ע' קלג. תרפ\"ו ס\"ע קב-ג. תש\"ח ע' 240."],["1201","2","<b>בזמן הזה. . פ\"ז מצות עשה נשארו</b>: ראה לעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב ממאמר זה. וש\"נ."],["1202","3","<b>שע\"י הי\"א כללים יבואו לקיים כל התרי\"ג מצות</b>: ראה עד\"ז סה\"מ תרכ\"ז ע' טז. תרפ\"ו ע' קג. תש\"ח ע' 240. לעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב מהמאמר. וש\"נ."]]],[2000460381,"שע\"י שבתי בבית הוי' יכולין לבוא לקיים כל המצות. ובאמת מצינו שארז\"ל שאמר הקב\"ה לדוד שאלה אחת שאלת והדר חשבת שארי מצות, אמר לו דוד להקב\"ה ממך למדתי<sup data-n=\"1203\">4</sup> שאמרת כ\"א ליראה, אף אני ג\"כ, שהטעם הוא שע\"י הכלל יבוא לקיים הפרט. כמו\"כ כאן מה שבא דוד והעמידן על אחד עשר הוא מפני שראה שאין יכולים לקיים כל התרי\"ג מצות לכן העמידן על אחד עשר כללים, שע\"י הי\"א כללים יקיימו כל התרי\"ג מצות.\n<b>ולהבין</b> ענין פרט וכלל, צ\"ל תחילה מהו ענין שמצינו שהסיפור של אברהם איך שאמר לאליעזר ואיך שאמר אליעזר לרבקה שהסיפור הוא על כמה עמודים בתורה, וגופי תורה אינם אלא ברמיזא, דהיינו מניין שדם של שרץ שמטמא כבשרו שנאמר וזה יהי' לך הטמא ולא כתי' זה שמהוא\"ו יתירה אנו למידין שמטמא, שזה אינו אלא ברמיזא וה\"ז גופי תורה, והסיפור של אליעזר הוא על כמה עמודין בתורה. והענין הוא שארז\"ל יפה שיחתן של עבדי בתי אבות יותר מתורתן של בנים מפני ששיחתן של עבדי אבות הם באריכות בתורה אבל תורתן של בנים אינם אלא ברמיזא. וצ\"ל מפני מה יפה מהו הטעם.\n<b>אך</b> הנה ארז\"ל על שלשה דברים העולם עומד על התורה ועבודה וגמ\"ח, וזהו לאחר מ\"ת שהם המצות, אבל קודם מ\"ת הם האבות שמעשה אבות הם סימן לבנים, שעמוד גמ\"ח הוא אברהם, שגמ\"ח הו\"ע חסד וכתי' באברהם ויטע אשל בבאר שבע ויקרא שם בש' הוי' אל עולם ופי' אשל ח\"א פרדס וח\"א פונדק, שאשל הוא ר\"ת אכילה שתי' לויה שהי' מאכיל לכולם לא פלוג אפי' לערביים, וזהו\"ע מדת החסד בגשמיות, ואף ברוחניות הי' משפיע להם כמ\"ש ויקרא שם בש' הוי' אל עולם שהי' משגר שם שמים בפי כל, לפי שההשפעה של מדת החסד יש ברוחניות וגשמיות, בגשמיות שהי' מאכיל אותם, וברוחניות שהי' אומר להם בתר האכילה בירכו למי שאכלתם משלו כמ\"ש באורחות צדיקים שאברהם הי' נדיב בין בממונו<sup data-n=\"1204\">5</sup> בין בגופו ובין בנפשו, בממונו שהי' מאכיל אותם משלו, בגופו שהי' מטריח את עצמו בשבילם, ובנפשו שהי' משפיע להם מנפשו שיהי' שם שמים שגור בפיהם, עד שנעשה מרכבה למדת החסד כמו שאי' בפרד\"ס בשם ס' הבהיר אמרה מדת החסד לפני הקב\"ה רבונו של עולם כל ימי היות אברם בעולם לא הוצרכתי לעשות מלאכתי שהרי אברהם עומד ומשמש במקומי כמ\"ש וישמור משמרתי שהי' מחליף מדת החסד. ועמוד התורה הוא יעקב כמ\"ש ויקם עדות ביעקב ותורה שם בישראל. ועמוד העבודה הוא יצחק, ועבודה הוא קרבנות כמארז\"ל ולעבדו בכל לבבכם איזה עבודה שבלב הוי אומר זו תפלה ותפלה כנגד תמידין תיקנו, ויצחק הי' מקור הקרבנות שהוא בעצמו הי' קרבן כמ\"ש ממעל לעצים.",[["1203","4","<b>מה הוי' שואל מעמך. . ולכאורה הלא כתי' אחת שאלתי. . אמר לו דוד להקב\"ה ממך למדתי</b>: ראה בכ\"ז (בשם הה\"מ) לקו\"ת מסעי צו, סע\"ב. אוה\"ת מסעי ע' א'תטז-יז. ואתחנן ע' תיח ואילך. דרושים לר\"ה (כרך ו) ע' ב'תמד ואילך. סה\"מ תרכ\"ט ע' שכה. וש\"נ."],["1204","5","<b>כמ\"ש באורחות צדיקים שאברהם הי' נדיב בין בממונו</b>: הובא ונת' גם בסה\"מ תרכ\"ז ע' קצט. תמח. ובארוכה סה\"מ תרפ\"ט ע' 90 ואילך. תרח\"צ ע' קכט ואילך."]]],[2000460382,"<b>ולהבין</b> כ\"ז צ\"ל בכלל ענין הקרבנות, הלא קרבן היא בהמה גשמי' והי' מעלה אותה על גבי המזבח והי' נכלל אש שלמטה באש שלמעלה ונעשה ריח ניחוח להוי'. וצ\"ל מהו\"ע קישור וחיבור בהמה גשמי' לאש שלמעלה ושתהי' ריח ניחוח להוי'. והענין הוא כי הנה ארז\"ל ג' שותפים באדם אב ואם והקב\"ה נותן בו נשמה, והעיקר היא הנשמה שמחי' אותו. והנה מקור החיות של הבהמה הוא מש' ב\"ן שנפל בשבירת הכלים ונעשה חיות לבהמה גשמי', שבהמה היא בגימט' ב\"ן וחיותה הוא מש' ב\"ן שנפל בשה\"כ. וענין שבירת הכלים הוא עד\"מ תיבת ברו\"ך אם הם בצירוף אזי יש לו השכלה פי' ברו\"ך גיבענצט, אבל אם האותיות הם בפיזור זה מזה אז אין להם ההשכלה, כמו\"כ האותיות שנפלו מש' ב\"ן נעשה שרש ומקור לבהמה שלמטה שמקבלת מפני שור שבמרכבה. ולכן נק' בש' שור כמו שמצינו באדם הראשון ששאל אותו הקב\"ה איך לקרות השמות והשיב לזה נאה לקרוא שור לזה נאה לקרוא חמור, והטעם הוא מפני שע\"י אותיות שבשמו הוא מקבל חיות<sup data-n=\"1205\">6</sup> מלמעלה. ומוכרח לומר כן שאל\"כ אלא שקריאת השם הוא הסכם הי' כל אחד ואחד יכול לקרות שמות, ומצינו שאמר הקב\"ה למלאכים שחכמתו מרובה משלכם אלא שקרא לשור שור משום שמקבל חיות משור שבמרכבה. וענין הקרבנות הוא להעלות ש' ב\"ן שנפל בשבירת הכלים למקורה, כדי שיוכלו החיות שבמרכבה לנשא את הכסא ודמות כמראה אדם שעל הכסא, והוא מפני שקרבן הו\"ע לחם כמ\"ש את קרבני לחמי שכמו הלחם הוא נותן כח לאדם שיוכל לילך כמו\"כ ענין קרבנות הוא כדי להעלות ש' ב\"ן שלמטה לפני שור שבמרכבה. ואף שפני שור שבמרכבה חיות שלו ג\"כ מש' ב\"ן, אך ש' ב\"ן שלמעלה הוא לאחר שנתברר, אבל ש' ב\"ן שלמטה הוא קודם שנתברר. וענין הקרבנות הוא כדי להעלות ש' ב\"ן שלמטה למקורו ושרשו כדי שיוכלו חיות שבמרכבה לנשאות את הכסא ודמות כמראה אדם שעל הכסא לבחי' כי לא אדם הוא, שאדם הוא בגימט' מ\"ה כדי שיהי' יחוד מ\"ה וב\"ן. ואעפ\"י ששור שבמרכבה הוא ג\"כ ממה שהוברר מש' ב\"ן ה\"ז ג\"כ ענין יחוד מ\"ה וב\"ן, אלא שזהו רק ע\"ד ביטול היש, אבל עיקר המכוון הוא שיהי' יחוד מ\"ה וב\"ן בביטול אמיתי, שאדם הוא בגימט' מ\"ה והו\"ע ביטול ע\"ד מ\"ש במשה ונחנו מ\"ה. וזהו ההפרש שבין אצי' לבי\"ע, שאצי' הו\"ע ביטול אמיתי אבל בי\"ע הוא ביטול היש עד שבהשתל' ממדריגה למדריגה נעשה יש גמור, כמארז\"ל רוח האדם הוא העולה למעלה ורוח הבהמה יורדת למטה, שרוח הבהמה הוא ש' ב\"ן ביטול היש ורוח האדם עולה למעלה שאדם הו\"ע מ\"ה. וזהו\"ע קרבנות בקצרה.\n<b>וכן</b> יובן עד\"ז ביצחק ורבקה שהוא ג\"כ ענין יחוד מ\"ה וב\"ן<sup data-n=\"1206\">7</sup>, שרבקה הוא ע\"ד מ\"ש במשנה רבקה של שלש שלש ושל ארבע ארבע<sup data-n=\"1207\">8</sup>, כמארז\"ל על ים של שלמה",[["1205","6","<b>והשיב לזה נאה לקרות שור. . שע\"י אותיות שבשמו הוא מקבל חיות</b>: ראה בכ\"ז בארוכה אוה\"ת בראשית (כרך ג) תקמא, ב. סה\"מ תרכ\"ט ע' קלו ואילך. וראה גם לקו\"ת נשא כו, ב. כז, א. סה\"מ תרל\"ד ע' עז-ח. המשך מים רבים תרל\"ו ע' כט. לקו\"ש חט\"ו ע' 13 ואילך."],["1206","7","<b>וכן יובן עד\"ז ביצחק ורבקה. . יחוד מ\"ה וב\"ן</b>: בכ\"ז ראה לקו\"ת ברכה שם צו, סע\"ג-ד. ובארוכה בדרושים שנסמנו לעיל בתחילת המאמר."],["1207","8","<b>שרבקה הוא ע\"ד. . רבקה של שלש שלש ושל ארבע ארבע</b>: ראה בארוכה תו\"א תולדות יח, א. יט, סע\"ג-ד."]]],[2000460383,"שנים עשר בקר שלשה צפונה ושלשה נגבה והים עומד עליהם, ים הו\"ע מל' דאצי' ובקר הוא בבריאה, ורבקה הו\"ע קרבן. וכמו שבקרבן צריך כהן שהוא מקו הימין חח\"ן מימין, שיש ג' מדריגות כהנים, כה\"ג, כהן סגן, כהן הדיוט, כמו\"כ אברהם שהי' מקו הימין שלח את אליעזר שהי' זקן ביתו שהוא מט\"ט ויש מט\"ט בברי' ומט\"ט ביצי'<sup data-n=\"1208\">9</sup> שהוא כולל ג' עולמות בי\"ע, והזהירו לא תקח אשה לבני מבנות כנען אלא אל ארצי ואל מולדתי, ואליעזר אמר וישביעני אדוני גו' אל בית אבי תלך ואל משפחתי, שהיא משפחת רם, שרם הוא אברהם, כמו שמצינו באלי' בן ברכאל שהי' ממשפחת רם, שזהו אברהם. וכמו שיש בקדושה אצי' וג' עולמות בי\"ע, כך יש ג\"כ בלעומת זה נוגה וג' קליפות הטמאות לגמרי, שג' קליפות הטמאות אין יכולין להתברר וצריך לדחות אותם לגמרי, ע\"ד כלי חרס שבירתן זהו טהרתן, איבודן זהו תיקונן, אבל נוגה הוא מעורב טוב ורע שהרע צריך לדחותו לגמרי אבל הטוב יכול להתברר, ע\"ד שיש מאכלים המותרים ומאכלים האסורים, שהאסורים אין יכולין להתברר וצריכין לדחותן, אבל המותרים יכולין להתברר דהיינו שילמוד ויתפלל בכח האכילה הלזו<sup data-n=\"1209\">10</sup>, וע\"ד ענין הקרבנות שע\"י שמקריבין הבהמה טהורה ע\"ג המזבח מתבררת ומתעלה למקורה ושרשה. וכמו\"כ רבקה שהיא ממשפחת רם שהיא מקליפת נוגה שיש בה טוב ורע שלח אחריה אליעזר לבררה ולהעלותה ליצחק שזהו\"ע יחוד מ\"ה וב\"ן, לכן כתי' באריכות הסיפור איך שאמר אברהם לאליעזר ואליעזר לרבקה. והגם שאברהם ושרה הם ג\"כ יחוד מ\"ה וב\"ן, אך זהו רק היחוד בבחי' מקיף כי שרה היא לשון שררה כמ\"ש כי שרית עם אלקים שזהו\"ע כתר מל' בחי' מקיף שכתר הוא מוכתר על הראש, ואברהם הוא ג\"כ ענין מקיף כמ\"ש וימינו תחבקני שהוא מדת החסד שהו\"ע מקיף. אבל עיקר היחוד הוא ע\"י יצחק שהו\"ע יחוד פנימי, שיחוד פנימי הוא מקו השמאל, כמ\"ש שמאלו תחת לראשי שזהו דוקא מבחי' שמאל היינו גבורה, כמו ענין גשמים שנק' בש' גבורה גבורות גשמים<sup data-n=\"1210\">11</sup> שהם עיקר החיות לעולם כמ\"ש כי כאשר ירד השלג והגשם והרווה את הארץ והולידה והצמיחה שזהו דוקא ע\"י גבורה כמ\"ש ישיש כגבור לרוץ אורח, שיהי' לרוץ אורח זהו דוקא ע\"י גבורה. ולכן יחוד פנימי דמ\"ה וב\"ן הוא דוקא ע\"י יצחק שהוא מקו השמאל.\n<b>וזהו\"ע</b> יפה שיחתן של עבדי בתי אבות יותר מתורתן של בנים, שלכן יפה היא וכתובה באריכות מפני שזהו\"ע יחוד מ\"ה וב\"ן. והגם שכל המצות הם ג\"כ ענין יחוד מ\"ה וב\"ן, היינו מצות ציצית הם בצמר כבשים ועזים טהורים, או תפלין בקלף בהמה טהורה, או סכך של סוכה וד' מינים שבלולב, ועד\"ז האדם וכמו אדם",[["1208","9","<b>ויש מט\"ט בבריאה ומט\"ט ביצי'</b>: ראה בהנסמן ע\"ז בהערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ד ע' 213. ותש\"ח ע' 202. וראה גם סה\"מ תרל\"ג ח\"א ע' ז. תר\"ס ע' קכד ואילך. קכח ואילך. ועוד."],["1209","10","<b>הטוב יכול להתברר. . שילמוד ויתפלל בכח האכילה הלזו</b>: ראה תניא פ\"ז (יא, סע\"ב). ובכ\"מ."],["1210","11","<b>גשמים. . גבורה גבורות גשמים</b>: ראה תו\"א נח ט, ג. לקו\"ת ואתחנן יג, רע\"ג. סה\"מ תרכ\"ז ע' רמט. וש\"נ."]]]]});
